                std::sin(t_k) /
                local_density
            );

        const double non_bias_weight =
            1.0 / denominator;

        const double weighted_action =
            t_k *
            non_bias_weight;

        cumulative_action +=
            weighted_action;

        normalization_sum +=
            non_bias_weight;

        sum_height += t_k;
        sum_weight += non_bias_weight;

        if (non_bias_weight < minimum_weight) {

