namespace RealCrypto {

    inline uint32_t rotr(
        uint32_t x,
        uint32_t n
    ) {

        return
            (x >> n) |
            (x << (32 - n));
    }

    inline uint32_t ch(
        uint32_t x,
        uint32_t y,
        uint32_t z
    ) {

        return
            (x & y) ^
            (~x & z);
    }

    inline uint32_t maj(
        uint32_t x,
        uint32_t y,
        uint32_t z
    ) {

        return
            (x & y) ^
            (x & z) ^
            (y & z);
    }

    inline uint32_t ep0(
        uint32_t x
    ) {

        return
            rotr(x, 2) ^
            rotr(x, 13) ^
            rotr(x, 22);
    }

    inline uint32_t ep1(
        uint32_t x
    ) {

        return
            rotr(x, 6) ^
            rotr(x, 11) ^
            rotr(x, 25);
    }

    inline uint32_t sig0(
        uint32_t x
    ) {

        return
            rotr(x, 7) ^
            rotr(x, 18) ^
            (x >> 3);
    }

    inline uint32_t sig1(
        uint32_t x
    ) {

        return
            rotr(x, 17) ^
            rotr(x, 19) ^
            (x >> 10);
    }

