// ============================================================
// 6. SHA-256 → Volumetric Exp(1) Coordinates
// ============================================================
//
// Each 32-bit section of the digest is interpreted as
// approximately uniform:
//
//     U = (chunk + 0.5) / 2^32
//
// then transformed:
//
//     X = -log(U)
//
// giving approximately Exp(1).
//
// With n=8, the same digest supplies 8 overlapping
// 32-bit coordinates.
// ============================================================

double compute_volumetric_sum(
    const uint8_t hash_digest[32],
    std::size_t n
) {

    double sum = 0.0;

    for (
        std::size_t i = 0;
        i < n;
        ++i
    ) {

        // 28-byte limit prevents offset+3
        // from exceeding the digest.
        const std::size_t offset =
            (i * 4) % 28;

        const uint32_t chunk =
            (static_cast<uint32_t>(
                hash_digest[offset]
            ) << 24)
            |
            (static_cast<uint32_t>(
                hash_digest[offset + 1]
            ) << 16)
            |
            (static_cast<uint32_t>(
                hash_digest[offset + 2]
            ) << 8)
            |
            static_cast<uint32_t>(
                hash_digest[offset + 3]
            );

        double u =
            (
                static_cast<double>(chunk)
                +
                0.5
            )
            /
            4294967296.0;

        if (u <= 0.0) {
            u = 1e-12;
        }

        if (u >= 1.0) {
            u = 1.0 - 1e-12;
        }

        const double x =
            -std::log(u);

        sum += x;
    }

    return sum;
}

// ============================================================
// Compute individual volumetric coordinates
// ============================================================

std::vector<double> compute_volumetric_coordinates(
    const uint8_t hash_digest[32],
    std::size_t n
) {

    std::vector<double> coordinates;

    coordinates.reserve(n);

    for (
        std::size_t i = 0;
        i < n;
        ++i
    ) {

        const std::size_t offset =
            (i * 4) % 28;

        const uint32_t chunk =
            (static_cast<uint32_t>(
                hash_digest[offset]
            ) << 24)
            |
            (static_cast<uint32_t>(
                hash_digest[offset + 1]
            ) << 16)
            |
            (static_cast<uint32_t>(
                hash_digest[offset + 2]
            ) << 8)
            |
            static_cast<uint32_t>(
                hash_digest[offset + 3]
            );

        double u =
            (
                static_cast<double>(chunk)
                +
                0.5
            )
            /
            4294967296.0;

        if (u <= 0.0) {
            u = 1e-12;
        }

        if (u >= 1.0) {
            u = 1.0 - 1e-12;
        }

        coordinates.push_back(
            -std::log(u)
        );
    }

    return coordinates;
}

