// ============================================================
// 8. Analytical Gamma Tail Reference
// ============================================================
//
// For iid Exp(1):
//
//     S_n = X_1 + ... + X_n
//
// follows Gamma(n,1).
//
// For integer n:
//
//     P(S_n >= x)
//       = exp(-x) *
//         sum_{k=0}^{n-1} x^k/k!
//
// This gives a useful reference against the Monte Carlo
// result.
// ============================================================

double gamma_integer_tail(
    std::size_t n,
    double x
) {

    if (n == 0) {
        return 0.0;
    }

    if (x < 0.0) {
        return 1.0;
    }

    double term = 1.0;

    double sum = 1.0;

    for (
        std::size_t k = 1;
        k < n;
        ++k
    ) {

        term *=
            x /
            static_cast<double>(k);

        sum += term;
    }

    return
        std::exp(-x) *
        sum;
}

// ============================================================
// 9. Correlated Analytical Probability
// ============================================================
//
// If:
//
//     X_i = X
//
// then:
//
//     sum = nX
//
// and:
//
//     P(sum >= threshold)
//
//       = P(X >= threshold/n)
//
//       = exp(-threshold/n)
// ============================================================

double correlated_analytical_probability(
    std::size_t n,
    double threshold
) {

    if (n == 0) {
        return 0.0;
    }

    return std::exp(
        -threshold /
        static_cast<double>(n)
    );
}

