// ============================================================
// SHA-256
// ============================================================

static inline std::uint32_t rotr(std::uint32_t x, std::uint32_t n)
{
    return (x >> n) | (x << (32 - n));
}

static inline std::uint32_t ch(
    std::uint32_t x,
    std::uint32_t y,
    std::uint32_t z)
{
    return (x & y) ^ (~x & z);
}

static inline std::uint32_t maj(
    std::uint32_t x,
    std::uint32_t y,
    std::uint32_t z)
{
    return (x & y) ^ (x & z) ^ (y & z);
}

static inline std::uint32_t ep0(std::uint32_t x)
{
    return rotr(x, 2) ^ rotr(x, 13) ^ rotr(x, 22);
}

static inline std::uint32_t ep1(std::uint32_t x)
{
    return rotr(x, 6) ^ rotr(x, 11) ^ rotr(x, 25);
}

static inline std::uint32_t sig0(std::uint32_t x)
{
    return rotr(x, 7) ^ rotr(x, 18) ^ (x >> 3);
}

static inline std::uint32_t sig1(std::uint32_t x)
{
    return rotr(x, 17) ^ rotr(x, 19) ^ (x >> 10);
}


