void sha256(
    const std::uint8_t* data,
    std::size_t len,
    std::uint8_t hash[32])
{
    std::uint32_t H[8] = {
        0x6a09e667,
        0xbb67ae85,
        0x3c6ef372,
        0xa54ff53a,
        0x510e527f,
        0x9b05688c,
        0x1f83d9ab,
        0x5be0cd19
    };

    const std::size_t padded_len =
        ((len + 9 + 63) / 64) * 64;

    std::vector<std::uint8_t> msg(padded_len, 0);

    std::memcpy(msg.data(), data, len);

    msg[len] = 0x80;

    const std::uint64_t bit_len =
        static_cast<std::uint64_t>(len) * 8ULL;

    for (int i = 0; i < 8; ++i) {
        msg[padded_len - 1 - i] =
            static_cast<std::uint8_t>(
                bit_len >> (8 * i));
    }

    for (std::size_t offset = 0;
         offset < padded_len;
         offset += 64)
    {
        std::uint32_t w[64];

        for (int i = 0; i < 16; ++i) {
            const std::size_t p =
                offset + i * 4;

            w[i] =
                (static_cast<std::uint32_t>(msg[p]) << 24) |
                (static_cast<std::uint32_t>(msg[p + 1]) << 16) |
                (static_cast<std::uint32_t>(msg[p + 2]) << 8) |
                (static_cast<std::uint32_t>(msg[p + 3]));
        }

        for (int i = 16; i < 64; ++i) {
            w[i] =
                sig1(w[i - 2]) +
                w[i - 7] +
                sig0(w[i - 15]) +
                w[i - 16];
        }

        std::uint32_t a = H[0];
        std::uint32_t b = H[1];
        std::uint32_t c = H[2];
        std::uint32_t d = H[3];
        std::uint32_t e = H[4];
        std::uint32_t f = H[5];
        std::uint32_t g = H[6];
        std::uint32_t h = H[7];

        for (int i = 0; i < 64; ++i) {

            const std::uint32_t t1 =
                h +
                ep1(e) +
                ch(e, f, g) +
                K[i] +
                w[i];

            const std::uint32_t t2 =
                ep0(a) +
                maj(a, b, c);

            h = g;
            g = f;
            f = e;
            e = d + t1;
            d = c;
            c = b;
            b = a;
            a = t1 + t2;
        }

        H[0] += a;
        H[1] += b;
        H[2] += c;
        H[3] += d;
        H[4] += e;
        H[5] += f;
        H[6] += g;
        H[7] += h;
    }

    for (int i = 0; i < 8; ++i) {
        hash[i * 4] =
            static_cast<std::uint8_t>(H[i] >> 24);

        hash[i * 4 + 1] =
            static_cast<std::uint8_t>(H[i] >> 16);

        hash[i * 4 + 2] =
            static_cast<std::uint8_t>(H[i] >> 8);

        hash[i * 4 + 3] =
            static_cast<std::uint8_t>(H[i]);
    }
}


