std::string bytes_to_hex(
    const std::uint8_t* data,
    std::size_t len)
{
    std::ostringstream out;

    out << std::hex
        << std::setfill('0');

    for (std::size_t i = 0; i < len; ++i) {
        out << std::setw(2)
            << static_cast<unsigned>(data[i]);
    }

    return out.str();
}


// ============================================================
// COUNT LEADING ZERO BITS
// ============================================================
//
// Counts zeros from the beginning of a 32-bit region.
//
// Example:
//
// 00000000 101xxxxx...
// ^^^^^^^^
//
// = 8 leading zero bits
//
// A completely zero 32-bit region gives 32.
//
unsigned count_leading_zero_bits(std::uint32_t x)
{
    if (x == 0)
        return 32;

#if defined(__GNUC__) || defined(__clang__)
    return static_cast<unsigned>(__builtin_clz(x));
#else
    unsigned count = 0;

    for (int bit = 31; bit >= 0; --bit) {
        if ((x & (1u << bit)) != 0)
            break;

        ++count;
    }

    return count;
#endif
}


// ============================================================
// EXTRACT THE 8 × 32-BIT HASH REGIONS
// ============================================================

std::array<std::uint32_t, NUM_REGIONS>
extract_regions(const std::uint8_t hash[32])
{
    std::array<std::uint32_t, NUM_REGIONS> regions{};

    for (std::size_t r = 0; r < NUM_REGIONS; ++r) {

        const std::size_t p = r * 4;

        regions[r] =
            (static_cast<std::uint32_t>(hash[p]) << 24) |
            (static_cast<std::uint32_t>(hash[p + 1]) << 16) |
            (static_cast<std::uint32_t>(hash[p + 2]) << 8) |
            (static_cast<std::uint32_t>(hash[p + 3]));
    }

    return regions;
}


