struct ZeroProfile
{
    std::array<unsigned, NUM_REGIONS> zero_bits{};

    unsigned total_zero_bits = 0;

    bool success = false;
};


ZeroProfile analyze_hash(
    const std::uint8_t hash[32])
{
    ZeroProfile profile;

    const auto regions =
        extract_regions(hash);

    profile.success = true;

    for (std::size_t i = 0;
         i < NUM_REGIONS;
         ++i)
    {
        profile.zero_bits[i] =
            count_leading_zero_bits(regions[i]);

        profile.total_zero_bits +=
            profile.zero_bits[i];

        if (profile.zero_bits[i] <
            REQUIRED_ZERO_BITS[i])
        {
            profile.success = false;
        }
    }

    return profile;
}


