// ============================================================
// BLOCK HEADER
// ============================================================
//
// 4 bytes  : block index
// 32 bytes : previous hash
// 8 bytes  : nonce
//
// Total = 44 bytes.
//
std::vector<std::uint8_t> make_header(
    std::uint32_t block_index,
    const std::array<std::uint8_t, 32>& previous_hash,
    std::uint64_t nonce)
{
    std::vector<std::uint8_t> header(44);

    // Explicit big-endian encoding so the hash is
    // deterministic across machines.

    header[0] =
        static_cast<std::uint8_t>(block_index >> 24);

    header[1] =
        static_cast<std::uint8_t>(block_index >> 16);

    header[2] =
        static_cast<std::uint8_t>(block_index >> 8);

    header[3] =
        static_cast<std::uint8_t>(block_index);

    std::copy(
        previous_hash.begin(),
        previous_hash.end(),
        header.begin() + 4);

    for (int i = 0; i < 8; ++i) {
        header[36 + i] =
            static_cast<std::uint8_t>(
                nonce >> (56 - 8 * i));
    }

    return header;
}


// ============================================================
// BLOCK
// ============================================================

struct Block
{
    std::uint32_t index;

    std::array<std::uint8_t, 32>
        previous_hash{};

    std::uint64_t nonce = 0;

    std::array<std::uint8_t, 32>
        hash{};

    ZeroProfile profile;
};


// ============================================================
// MINE BLOCK
// ============================================================

Block mine_block(
    std::uint32_t block_index,
    const std::array<std::uint8_t, 32>& previous_hash,
    std::uint64_t& total_hashes,
    std::uint64_t& printed_attempts)
{
    Block block;

    block.index =
        block_index;

    block.previous_hash =
        previous_hash;

    std::uint64_t nonce = 0;

    while (true) {

        const auto header =
            make_header(
                block_index,
                previous_hash,
                nonce);

        std::array<std::uint8_t, 32>
            hash{};

        sha256(
            header.data(),
            header.size(),
            hash.data());

        ++total_hashes;

        const ZeroProfile profile =
            analyze_hash(hash.data());

        if (SHOW_ALL_HASHES &&
            printed_attempts < MAX_PRINTED_ATTEMPTS)
        {
            print_pow_attempt(
                block_index,
                nonce,
                hash.data(),
                profile);

            ++printed_attempts;
        }

        if (profile.success) {

            block.nonce =
                nonce;

            block.hash =
                hash;

            block.profile =
                profile;

            return block;
        }

        ++nonce;
    }
}


