         i < NUM_RIEMANN_ZEROS;
         ++i) {

        const double t_k =
            RIEMANN_ZEROS_100[i];

        const double local_density =
            std::log(
                t_k / (2.0 * M_PI)
            )
            + 0.5772156649015329;

        const double non_bias_weight =
            1.0 /
            (
                1.0 +
                std::abs(
                    std::sin(t_k) /
                    local_density
                )
            );

        const double weighted_action =
            t_k * non_bias_weight;

        cumulative_action += weighted_action;
        normalization_sum += non_bias_weight;
        sum_height += t_k;

        if (non_bias_weight < minimum_weight) {
            minimum_weight = non_bias_weight;
            minimum_index = i + 1;
        }

        if (non_bias_weight > maximum_weight) {
            maximum_weight = non_bias_weight;
            maximum_index = i + 1;
