// ------------------------------------------------------------
// SHA-256
// ------------------------------------------------------------

void sha256(
    const uint8_t* data,
    std::size_t len,
    uint8_t hash[32]
) {

    uint32_t state[8] = {

        0x6a09e667,
        0xbb67ae85,
        0x3c6ef372,
        0xa54ff53a,
        0x510e527f,
        0x9b05688c,
        0x1f83d9ab,
        0x5be0cd19
    };

    const std::size_t padded_len =
        ((len + 9 + 63) / 64) * 64;

    std::vector<uint8_t> padded(
        padded_len,
        0
    );

    std::memcpy(
        padded.data(),
        data,
        len
    );

    padded[len] = 0x80;

    const uint64_t bitlen =
        static_cast<uint64_t>(len) * 8ULL;

    for (int j = 0; j < 8; ++j) {

        padded[
            padded_len - 1 - j
        ] =
            static_cast<uint8_t>(
                bitlen >> (8 * j)
            );
    }

    for (
        std::size_t block_offset = 0;
        block_offset < padded_len;
        block_offset += 64
    ) {

        uint32_t m[64];

        for (int j = 0; j < 16; ++j) {

            const std::size_t p =
                block_offset +
                static_cast<std::size_t>(j) * 4;

            m[j] =
                (static_cast<uint32_t>(
                    padded[p]
                ) << 24)
                |
                (static_cast<uint32_t>(
                    padded[p + 1]
                ) << 16)
                |
                (static_cast<uint32_t>(
                    padded[p + 2]
                ) << 8)
                |
                static_cast<uint32_t>(
                    padded[p + 3]
                );
        }

        for (int j = 16; j < 64; ++j) {

            m[j] =
                sig1(m[j - 2])
                +
                m[j - 7]
                +
                sig0(m[j - 15])
                +
                m[j - 16];
        }

        uint32_t a = state[0];
        uint32_t b = state[1];
        uint32_t c = state[2];
        uint32_t d = state[3];

        uint32_t e = state[4];
        uint32_t f = state[5];
        uint32_t g = state[6];
        uint32_t h = state[7];

        for (int j = 0; j < 64; ++j) {

            const uint32_t t1 =
                h +
                ep1(e) +
                ch(e, f, g) +
                K[j] +
                m[j];

            const uint32_t t2 =
                ep0(a) +
                maj(a, b, c);

            h = g;
            g = f;
            f = e;
            e = d + t1;

            d = c;
            c = b;
            b = a;
            a = t1 + t2;
        }

        state[0] += a;
        state[1] += b;
        state[2] += c;
        state[3] += d;

        state[4] += e;
        state[5] += f;
        state[6] += g;
        state[7] += h;
    }

    for (int j = 0; j < 8; ++j) {

        hash[j * 4] =
            static_cast<uint8_t>(
                state[j] >> 24
            );

        hash[j * 4 + 1] =
            static_cast<uint8_t>(
                state[j] >> 16
            );

        hash[j * 4 + 2] =
            static_cast<uint8_t>(
                state[j] >> 8
            );

        hash[j * 4 + 3] =
            static_cast<uint8_t>(
                state[j]
            );
    }
}

