std::string bytes_to_hex(
    const uint8_t* data,
    std::size_t len
) {

    std::stringstream ss;

    ss
        << std::hex
        << std::setfill('0');

    for (
        std::size_t i = 0;
        i < len;
        ++i
    ) {

        ss
            << std::setw(2)
            << static_cast<int>(data[i]);
    }

    return ss.str();
}

