// ============================================================
// Exact Gamma tail
// ============================================================

double gamma_integer_tail(
    std::size_t n,
    double x
) {

    if (n == 0)
        return 0.0;

    if (x < 0.0)
        return 1.0;

    double term = 1.0;

    double sum = 1.0;

    for (
        std::size_t k = 1;
        k < n;
        ++k
    ) {

        term *=
            x /
            static_cast<double>(k);

        sum += term;
    }

    return
        std::exp(-x) *
        sum;
}

// ============================================================
// Correlated analytical probability
// ============================================================

double correlated_analytical_probability(
    std::size_t n,
    double threshold
) {

    if (n == 0)
        return 0.0;

    return std::exp(
        -threshold /
        static_cast<double>(n)
    );
}

