struct Result {
    double success_probability;
    double expected_trials;
};

class Exp1RNG {
public:
    explicit Exp1RNG(uint64_t seed = 123456789ULL)
        : rng(seed), uniform(0.0, 1.0) {}

    double exp1() {
        double u;
        do {
            u = uniform(rng);
        } while (u <= 0.0 || u >= 1.0);
        return -std::log(u);
    }

private:
    std::mt19937_64 rng;
    std::uniform_real_distribution<double> uniform;
};

// ------------------------------------------------------------
// 1. Statistical Monte Carlo Constructions
// ------------------------------------------------------------
Result iid_exp1(std::size_t n, double threshold, uint64_t trials, uint64_t seed) {
    Exp1RNG rng(seed);
    uint64_t successes = 0;

    for (uint64_t t = 0; t < trials; ++t) {
        double sum = 0.0;
        for (std::size_t i = 0; i < n; ++i) {
            sum += rng.exp1();
        }
        if (sum >= threshold) {
            ++successes;
        }
    }

    double p = static_cast<double>(successes) / static_cast<double>(trials);
    double expected = p > 0.0 ? 1.0 / p : std::numeric_limits<double>::infinity();
    return {p, expected};
}

Result correlated_exp1(std::size_t n, double threshold, uint64_t trials, uint64_t seed) {
    Exp1RNG rng(seed);
    uint64_t successes = 0;

    for (uint64_t t = 0; t < trials; ++t) {
        const double x = rng.exp1();
        const double sum = static_cast<double>(n) * x;
        if (sum >= threshold) {
            ++successes;
        }
    }

    double p = static_cast<double>(successes) / static_cast<double>(trials);
    double expected = p > 0.0 ? 1.0 / p : std::numeric_limits<double>::infinity();
    return {p, expected};
}

