    const double known_t[8] = {
        14.134725, 21.022040, 25.010858, 30.424876, 
        32.935062, 37.586178, 40.918719, 43.327073
    };

    double cumulative_action = 0.0;
    double normalization_sum = 0.0;

    std::cout << std::left 
              << std::setw(10) << "Index (k)" 
              << std::setw(16) << "Height (t_k)" 
              << std::setw(20) << "Density Response" 
              << "Non-Bias Weight" << "\n";
    std::cout << std::string(70, '-') << "\n";

    for (std::size_t i = 0; i < n_zeros; ++i) {
        double t_k = known_t[i];
        double local_density = std::log(t_k / (2.0 * M_PI)) + 0.577215;
        double non_bias_weight = 1.0 / (1.0 + std::abs(std::sin(t_k) / local_density));

        cumulative_action += t_k * non_bias_weight;
        normalization_sum += non_bias_weight;

        std::cout << std::left 
                  << std::setw(10) << (i + 1) 
                  << std::setw(16) << std::fixed << std::setprecision(4) << t_k 
                  << std::setw(20) << std::setprecision(4) << local_density 
                  << non_bias_weight << "\n";
    }

    double metric = cumulative_action / (normalization_sum * static_cast<double>(n_zeros));
    std::cout << "\nFinal Lagrangian Non-Bias Metric: " << std::scientific << metric << "\n";
    return metric;
}

