double compute_volumetric_sum(const uint8_t hash_digest[32], std::size_t n) {
    double sum = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        size_t offset = (i * 4) % 28;
        uint32_t chunk = (static_cast<uint32_t>(hash_digest[offset]) << 24) |
                         (static_cast<uint32_t>(hash_digest[offset + 1]) << 16) |
                         (static_cast<uint32_t>(hash_digest[offset + 2]) << 8) |
                         (static_cast<uint32_t>(hash_digest[offset + 3]));

        double u = (static_cast<double>(chunk) + 0.5) / 4294967296.0;
        if (u <= 0.0) u = 1e-12;
        if (u >= 1.0) u = 1.0 - 1e-12;
        sum += -std::log(u);
    }
    return sum;
}

