// ============================================================
// SHA-256 ROTATIONS
// ============================================================

static inline std::uint32_t rotr(
    std::uint32_t x,
    unsigned n)
{
    return (x >> n) | (x << (32 - n));
}


static inline std::uint32_t Ch(
    std::uint32_t x,
    std::uint32_t y,
    std::uint32_t z)
{
    return (x & y) ^ (~x & z);
}


static inline std::uint32_t Maj(
    std::uint32_t x,
    std::uint32_t y,
    std::uint32_t z)
{
    return (x & y) ^ (x & z) ^ (y & z);
}


static inline std::uint32_t Sigma0(
    std::uint32_t x)
{
    return rotr(x, 2) ^
           rotr(x, 13) ^
           rotr(x, 22);
}


static inline std::uint32_t Sigma1(
    std::uint32_t x)
{
    return rotr(x, 6) ^
           rotr(x, 11) ^
           rotr(x, 25);
}


static inline std::uint32_t sigma0(
    std::uint32_t x)
{
    return rotr(x, 7) ^
           rotr(x, 18) ^
           (x >> 3);
}


static inline std::uint32_t sigma1(
    std::uint32_t x)
{
    return rotr(x, 17) ^
           rotr(x, 19) ^
           (x >> 10);
}


// ============================================================
// LOAD BIG-ENDIAN 32-BIT INTEGER
// ============================================================

static inline std::uint32_t load_be32(
    const std::uint8_t* p)
{
    return
        (static_cast<std::uint32_t>(p[0]) << 24) |
        (static_cast<std::uint32_t>(p[1]) << 16) |
        (static_cast<std::uint32_t>(p[2]) << 8)  |
        (static_cast<std::uint32_t>(p[3]));
}


// ============================================================
// STORE BIG-ENDIAN 32-BIT INTEGER
// ============================================================

static inline void store_be32(
    std::uint8_t* p,
    std::uint32_t x)
{
    p[0] = static_cast<std::uint8_t>(x >> 24);
    p[1] = static_cast<std::uint8_t>(x >> 16);
    p[2] = static_cast<std::uint8_t>(x >> 8);
    p[3] = static_cast<std::uint8_t>(x);
}


// ============================================================
// FAST SHA-256 FOR THIS SPECIFIC HEADER
// ============================================================
//
// Our header is:
//
//     4 bytes  block index
//    32 bytes  previous hash
//     8 bytes  nonce
//
// Total:
//     44 bytes
//
// SHA-256 padding makes this exactly one 64-byte block.
//
// Therefore we don't need a generic allocator-based SHA-256.
// This function works directly on a 64-byte local block.
//
// ============================================================

static inline void sha256_header(
    const std::uint8_t header[44],
    std::uint8_t digest[32])
{
    std::uint32_t w[64];

    // First 44 bytes of the message.
    for (int i = 0; i < 11; ++i)
    {
        w[i] = load_be32(header + i * 4);
    }

    // Padding byte.
    w[11] = 0x80000000U;

    // Bytes 48..55 are zero.
    w[12] = 0;
    w[13] = 0;

    // Length = 44 bytes = 352 bits.
    w[14] = 0;
    w[15] = 352;

    // Message schedule.
    for (int i = 16; i < 64; ++i)
    {
        w[i] =
            sigma1(w[i - 2]) +
            w[i - 7] +
            sigma0(w[i - 15]) +
            w[i - 16];
    }

    std::uint32_t a = 0x6a09e667;
    std::uint32_t b = 0xbb67ae85;
    std::uint32_t c = 0x3c6ef372;
    std::uint32_t d = 0xa54ff53a;
    std::uint32_t e = 0x510e527f;
    std::uint32_t f = 0x9b05688c;
    std::uint32_t g = 0x1f83d9ab;
    std::uint32_t h = 0x5be0cd19;

    for (int i = 0; i < 64; ++i)
    {
        const std::uint32_t T1 =
            h +
            Sigma1(e) +
            Ch(e, f, g) +
            K[i] +
            w[i];

        const std::uint32_t T2 =
            Sigma0(a) +
            Maj(a, b, c);

        h = g;
        g = f;
        f = e;
        e = d + T1;
        d = c;
        c = b;
        b = a;
        a = T1 + T2;
    }

    a += 0x6a09e667;
    b += 0xbb67ae85;
    c += 0x3c6ef372;
    d += 0xa54ff53a;
    e += 0x510e527f;
    f += 0x9b05688c;
    g += 0x1f83d9ab;
    h += 0x5be0cd19;

    store_be32(digest + 0,  a);
    store_be32(digest + 4,  b);
    store_be32(digest + 8,  c);
    store_be32(digest + 12, d);
    store_be32(digest + 16, e);
    store_be32(digest + 20, f);
    store_be32(digest + 24, g);
    store_be32(digest + 28, h);
}


// ============================================================
// COUNT LEADING ZERO BITS
// ============================================================

static inline unsigned leading_zero_bits(
    std::uint32_t x)
{
    if (x == 0)
        return 32;

#if defined(__GNUC__) || defined(__clang__)

    return static_cast<unsigned>(
        __builtin_clz(x));

#elif defined(_MSC_VER)

    unsigned long index;

    if (_BitScanReverse(
            &index,
            x))
    {
        return 31U - index;
    }

    return 32;

#else

    unsigned n = 0;

    for (int bit = 31; bit >= 0; --bit)
    {
        if (x & (1U << bit))
            break;

        ++n;
    }

    return n;

#endif
}


// ============================================================
// HASH ANALYSIS
// ============================================================

struct ZeroProfile
{
    std::array<unsigned, NUM_REGIONS>
        zeros{};

    bool success = false;

    unsigned total = 0;
};


// ============================================================
// FAST DIFFICULTY TEST
// ============================================================
//
// This function checks the eight regions directly.
//
// The digest is:
//
//     digest[0..3]   -> region 0
//     digest[4..7]   -> region 1
//     ...
//
// No temporary array is required.
//
// ============================================================

static inline bool check_pow(
    const std::uint8_t digest[32],
    ZeroProfile* profile = nullptr)
{
    bool success = true;
    unsigned total = 0;

    for (std::size_t r = 0;
         r < NUM_REGIONS;
         ++r)
    {
        const std::uint32_t value =
            load_be32(
                digest + r * 4);

        const unsigned zeros =
            leading_zero_bits(value);

        total += zeros;

        if (profile)
            profile->zeros[r] = zeros;

        if (zeros <
            REQUIRED_ZERO_BITS[r])
        {
            success = false;

            // We can stop here when no profile is
            // required. This is an important speedup
            // for failed hashes.
            if (!profile)
                return false;
        }
    }

    if (profile)
    {
        profile->total = total;
        profile->success = success;
    }

    return success;
}


