static const char HEX[] =
    "0123456789abcdef";


static void hash_to_hex(
    const std::uint8_t hash[32],
    char output[65])
{
    for (int i = 0; i < 32; ++i)
    {
        output[i * 2] =
            HEX[hash[i] >> 4];

        output[i * 2 + 1] =
            HEX[hash[i] & 15];
    }

    output[64] = '\0';
}


// ============================================================
// HEADER CREATION
// ============================================================

static inline void make_header(
    std::uint32_t block_index,
    const std::array<std::uint8_t, 32>& previous_hash,
    std::uint64_t nonce,
    std::uint8_t header[44])
{
    // Block index.
    header[0] =
        static_cast<std::uint8_t>(
            block_index >> 24);

    header[1] =
        static_cast<std::uint8_t>(
            block_index >> 16);

    header[2] =
        static_cast<std::uint8_t>(
            block_index >> 8);

    header[3] =
        static_cast<std::uint8_t>(
            block_index);

    // Previous hash.
    std::memcpy(
        header + 4,
        previous_hash.data(),
        32);

    // Nonce.
    //
    // Explicit big-endian encoding.
    for (int i = 0; i < 8; ++i)
    {
        header[36 + i] =
            static_cast<std::uint8_t>(
                nonce >> (56 - i * 8));
    }
}


