// ============================================================
// MINE ONE BLOCK
// ============================================================

static Block mine_block(
    std::uint32_t block_index,
    const std::array<std::uint8_t, 32>& previous_hash,
    std::uint64_t& total_hashes,
    std::uint64_t& printed_hashes)
{
    Block block;

    block.index =
        block_index;

    block.previous_hash =
        previous_hash;

    // Header never changes except for nonce.
    std::uint8_t header[44];

    make_header(
        block_index,
        previous_hash,
        0,
        header);

    std::uint8_t digest[32];

    const auto start =
        std::chrono::steady_clock::now();

    std::uint64_t nonce = 0;

    while (true)
    {
        // Update only the nonce bytes.
        for (int i = 0; i < 8; ++i)
        {
            header[36 + i] =
                static_cast<std::uint8_t>(
                    nonce >> (56 - i * 8));
        }

        sha256_header(
            header,
            digest);

        ++total_hashes;

        // Fast path:
        // no profile allocation/calculation
        // beyond what is necessary.
        if (check_pow(digest, nullptr))
        {
            ZeroProfile profile;

            check_pow(
                digest,
                &profile);

            block.nonce =
                nonce;

            std::memcpy(
                block.hash.data(),
                digest,
                32);

            block.profile =
                profile;

            return block;
        }

        // Optional diagnostic output.
        if (SHOW_ALL_HASHES &&
            printed_hashes <
                MAX_PRINTED_HASHES)
        {
            ZeroProfile profile;

            check_pow(
                digest,
                &profile);

            print_attempt(
                block_index,
                nonce,
                digest,
                profile);

            ++printed_hashes;
        }

        // Periodic progress.
        if (SHOW_PROGRESS &&
            (total_hashes %
             PROGRESS_INTERVAL == 0))
        {
            const auto now =
                std::chrono::steady_clock::now();

            const double seconds =
                std::chrono::duration<double>(
                    now - start).count();

            const double rate =
                seconds > 0.0
                ? static_cast<double>(
                      total_hashes) / seconds
                : 0.0;

            std::cout
                << "\rBlock "
                << block_index
                << " | hashes = "
                << total_hashes
                << " | nonce = "
                << nonce
                << " | rate = "
                << std::fixed
                << std::setprecision(2)
                << rate
                << " H/s"
                << std::flush;
        }

        ++nonce;

        // Prevent unsigned wraparound.
        if (nonce == 0)
        {
            std::cerr
                << "\nNonce space exhausted.\n";

            std::exit(1);
        }
    }
}


