        << (SHOW_ALL_HASHES ? "ON" : "OFF")
        << "\n\n";

    std::array<std::uint8_t, 32>
        previous_hash{};

    std::uint64_t total_hashes = 0;

    std::uint64_t printed_hashes = 0;

    std::array<Block, TOTAL_BLOCKS>
        chain{};


    const auto global_start =
        std::chrono::steady_clock::now();


    // ========================================================
    // MINE BLOCKS
    // ========================================================

    for (std::uint32_t i = 0;
         i < TOTAL_BLOCKS;
         ++i)
    {
        std::cout
            << "\n============================================================\n";

        std::cout
            << "MINING BLOCK "
            << i
            << "\n";

        std::cout
            << "============================================================\n";

        Block block =
            mine_block(
                i,
                previous_hash,
                total_hashes,
                printed_hashes);

        chain[i] =
            block;

        previous_hash =
            block.hash;

        char hex[65];

        hash_to_hex(
            block.hash.data(),
            hex);

        std::cout
            << "\n\nBLOCK "
            << i
            << " SOLVED\n";

        std::cout
            << "Nonce: "
            << block.nonce
            << '\n';

        std::cout
            << "Hash : "
            << hex
            << '\n';

        std::cout
            << "Zero profile: ";

        for (std::size_t r = 0;
             r < NUM_REGIONS;
             ++r)
        {
            std::cout
                << block.profile.zeros[r];

            if (r + 1 <
                NUM_REGIONS)
            {
                std::cout
                    << ',';
            }
        }

        std::cout
            << '\n';

        std::cout
            << "Total leading zero bits: "
            << block.profile.total
            << "\n";
    }


    // ========================================================
    // VERIFY CHAIN
    // ========================================================

    bool valid = true;

    for (std::size_t i = 1;
         i < chain.size();
         ++i)
    {
        if (chain[i].previous_hash !=
            chain[i - 1].hash)
        {
            valid = false;
            break;
        }
    }


    // ========================================================
    // PERFORMANCE
    // ========================================================

    const auto global_end =
        std::chrono::steady_clock::now();

    const double elapsed =
        std::chrono::duration<double>(
            global_end - global_start)
            .count();

    const double hash_rate =
        elapsed > 0.0
        ? static_cast<double>(
              total_hashes) / elapsed
        : 0.0;


    // ========================================================
    // SUMMARY
    // ========================================================

    std::cout
        << "\n\n============================================================\n"
        << "                       SUMMARY\n"
        << "============================================================\n";

    std::cout
        << "Blocks mined        : "
        << TOTAL_BLOCKS
        << '\n';

    std::cout
        << "Total SHA-256 hashes: "
        << total_hashes
        << '\n';

    std::cout
        << "Elapsed time        : "
        << std::fixed
        << std::setprecision(4)
        << elapsed
        << " seconds\n";

    std::cout
        << "Hash rate           : "
        << std::fixed
        << std::setprecision(2)
        << hash_rate
        << " H/s\n";

    if (TOTAL_BLOCKS > 0)
    {
        std::cout
            << "Average hashes/block: "
            << std::fixed
            << std::setprecision(2)
            << static_cast<double>(
                   total_hashes) /
                   TOTAL_BLOCKS
            << '\n';
    }

    std::cout
        << "Chain linkage       : "
        << (valid ? "VALID" : "INVALID")
        << '\n';

    std::cout
        << "============================================================\n";
}


