// ================================================================
// SHA-256 FUNCTIONS
// ================================================================

static inline std::uint32_t rotr(
    std::uint32_t x,
    unsigned n)
{
    return (x >> n) | (x << (32 - n));
}


static inline std::uint32_t Ch(
    std::uint32_t x,
    std::uint32_t y,
    std::uint32_t z)
{
    return (x & y) ^ (~x & z);
}


static inline std::uint32_t Maj(
    std::uint32_t x,
    std::uint32_t y,
    std::uint32_t z)
{
    return (x & y) ^ (x & z) ^ (y & z);
}


static inline std::uint32_t BigSigma0(
    std::uint32_t x)
{
    return rotr(x, 2) ^
           rotr(x, 13) ^
           rotr(x, 22);
}


static inline std::uint32_t BigSigma1(
    std::uint32_t x)
{
    return rotr(x, 6) ^
           rotr(x, 11) ^
           rotr(x, 25);
}


static inline std::uint32_t SmallSigma0(
    std::uint32_t x)
{
    return rotr(x, 7) ^
           rotr(x, 18) ^
           (x >> 3);
}


static inline std::uint32_t SmallSigma1(
    std::uint32_t x)
{
    return rotr(x, 17) ^
           rotr(x, 19) ^
           (x >> 10);
}


// ================================================================
// BIG-ENDIAN LOAD
// ================================================================

static inline std::uint32_t load_be32(
    const std::uint8_t* p)
{
    return
        (static_cast<std::uint32_t>(p[0]) << 24) |
        (static_cast<std::uint32_t>(p[1]) << 16) |
        (static_cast<std::uint32_t>(p[2]) << 8) |
        (static_cast<std::uint32_t>(p[3]));
}


// ================================================================
// BIG-ENDIAN STORE
// ================================================================

static inline void store_be32(
    std::uint8_t* p,
    std::uint32_t x)
{
    p[0] =
        static_cast<std::uint8_t>(x >> 24);

    p[1] =
        static_cast<std::uint8_t>(x >> 16);

    p[2] =
        static_cast<std::uint8_t>(x >> 8);

    p[3] =
        static_cast<std::uint8_t>(x);
}


// ================================================================
// SHA-256 FOR 44-BYTE BLOCK HEADER
// ================================================================
//
// Header:
//
//      4 bytes  block index
//     32 bytes  previous hash
//      8 bytes  nonce
//
// Total:
//
//     44 bytes
//
// SHA-256 padding makes this exactly one 64-byte block.
//
// No heap allocation occurs during mining.
// ================================================================

static inline void sha256_header(
    const std::uint8_t header[44],
    std::uint8_t digest[32])
{
    std::uint32_t w[64];

    // 44-byte message = 11 words.
    for (int i = 0; i < 11; ++i)
    {
        w[i] =
            load_be32(
                header + i * 4);
    }

    // SHA-256 padding.
    w[11] = 0x80000000U;

    // Remaining padding words.
    w[12] = 0;
    w[13] = 0;

    // High 32 bits of message length.
    w[14] = 0;

    // 44 bytes * 8 = 352 bits.
    w[15] = 352;

    // Message schedule.
    for (int i = 16; i < 64; ++i)
    {
        w[i] =
            SmallSigma1(w[i - 2]) +
            w[i - 7] +
            SmallSigma0(w[i - 15]) +
            w[i - 16];
    }

    // Initial SHA-256 state.
    std::uint32_t a = 0x6a09e667;
    std::uint32_t b = 0xbb67ae85;
    std::uint32_t c = 0x3c6ef372;
    std::uint32_t d = 0xa54ff53a;
    std::uint32_t e = 0x510e527f;
    std::uint32_t f = 0x9b05688c;
    std::uint32_t g = 0x1f83d9ab;
    std::uint32_t h = 0x5be0cd19;

    // Compression.
    for (int i = 0; i < 64; ++i)
    {
        const std::uint32_t t1 =
            h +
            BigSigma1(e) +
            Ch(e, f, g) +
            K[i] +
            w[i];

        const std::uint32_t t2 =
            BigSigma0(a) +
            Maj(a, b, c);

        h = g;
        g = f;
        f = e;
        e = d + t1;
        d = c;
        c = b;
        b = a;
        a = t1 + t2;
    }

    // Add initial state.
    a += 0x6a09e667;
    b += 0xbb67ae85;
    c += 0x3c6ef372;
    d += 0xa54ff53a;
    e += 0x510e527f;
    f += 0x9b05688c;
    g += 0x1f83d9ab;
    h += 0x5be0cd19;

    // Produce digest.
    store_be32(digest + 0,  a);
    store_be32(digest + 4,  b);
    store_be32(digest + 8,  c);
    store_be32(digest + 12, d);
    store_be32(digest + 16, e);
    store_be32(digest + 20, f);
    store_be32(digest + 24, g);
    store_be32(digest + 28, h);
}


// ================================================================
// COUNT LEADING ZERO BITS
// ================================================================

static inline unsigned count_leading_zero_bits(
    std::uint32_t x)
{
    if (x == 0)
        return 32;

#if defined(__GNUC__) || defined(__clang__)

    return static_cast<unsigned>(
        __builtin_clz(x));

#elif defined(_MSC_VER)

    unsigned long index;

    #include <intrin.h>

    _BitScanReverse(
        &index,
        x);

    return 31U - index;

#else

    unsigned count = 0;

    for (int bit = 31; bit >= 0; --bit)
    {
        if (x & (1U << bit))
            break;

        ++count;
    }

    return count;

#endif
}


// ================================================================
// ZERO PROFILE
// ================================================================

struct ZeroProfile
{
    std::array<unsigned, NUM_REGIONS>
        zeros{};

    unsigned total = 0;

    bool success = false;
};


// ================================================================
// CHECK POW
// ================================================================
//
// Fast path:
//     profile == nullptr
//
// In that case we stop immediately at the first failing region.
//
// This is the hot mining path.
//
// ================================================================

static inline bool check_pow(
    const std::uint8_t digest[32],
    ZeroProfile* profile = nullptr)
{
    bool success = true;

    unsigned total = 0;

    for (std::size_t region = 0;
         region < NUM_REGIONS;
         ++region)
    {
        const std::uint32_t value =
            load_be32(
                digest + region * 4);

        const unsigned zeros =
            count_leading_zero_bits(value);

        if (profile)
        {
            profile->zeros[region] =
                zeros;
        }

        total += zeros;

        if (zeros <
            REQUIRED_ZERO_BITS[region])
        {
            success = false;

            // Fast rejection.
            if (!profile)
                return false;
        }
    }

    if (profile)
    {
        profile->total = total;
        profile->success = success;
    }

    return success;
}


// ================================================================
// HASH TO HEX
// ================================================================

static constexpr char HEX[] =
    "0123456789abcdef";


static void hash_to_hex(
    const std::uint8_t hash[32],
    char output[65])
{
    for (int i = 0; i < 32; ++i)
    {
        output[i * 2] =
            HEX[hash[i] >> 4];

        output[i * 2 + 1] =
            HEX[hash[i] & 0x0f];
    }

    output[64] = '\0';
}


// ================================================================
// MAKE HEADER
// ================================================================

static inline void make_header(
    std::uint32_t block_index,
    const std::array<std::uint8_t, 32>& previous_hash,
    std::uint64_t nonce,
    std::uint8_t header[44])
{
    // Block index.
    header[0] =
        static_cast<std::uint8_t>(
            block_index >> 24);

    header[1] =
        static_cast<std::uint8_t>(
            block_index >> 16);

    header[2] =
        static_cast<std::uint8_t>(
            block_index >> 8);

    header[3] =
        static_cast<std::uint8_t>(
            block_index);

    // Previous block hash.
    std::memcpy(
        header + 4,
        previous_hash.data(),
        32);

    // Nonce.
    for (int i = 0; i < 8; ++i)
    {
        header[36 + i] =
            static_cast<std::uint8_t>(
                nonce >> (56 - i * 8));
    }
}


// ================================================================
// BLOCK
// ================================================================

struct Block
{
    std::uint32_t index = 0;

    std::array<std::uint8_t, 32>
        previous_hash{};

    std::uint64_t nonce = 0;

    std::array<std::uint8_t, 32>
        hash{};

    ZeroProfile profile;
};


// ================================================================
// PRINT HASH ATTEMPT
// ================================================================

static void print_attempt(
    std::uint32_t block,
    std::uint64_t nonce,
    const std::uint8_t digest[32],
    const ZeroProfile& profile)
{
    char hash_string[65];

    hash_to_hex(
        digest,
        hash_string);

    std::cout
        << "\n------------------------------------------------------------\n";

    std::cout
        << "BLOCK : "
        << block
        << '\n';

    std::cout
        << "NONCE : "
        << nonce
        << '\n';

    std::cout
        << "HASH  : "
        << hash_string
        << '\n';

    std::cout
        << "\nREGIONS\n";

    for (std::size_t region = 0;
         region < NUM_REGIONS;
         ++region)
    {
        const std::size_t first_bit =
            region * REGION_BITS;

        const std::size_t last_bit =
            first_bit + REGION_BITS - 1;

        std::cout
            << "Region "
            << region
            << " ["
            << first_bit
            << "-"
            << last_bit
            << "]  "
            << std::setw(2)
            << profile.zeros[region]
            << " / "
            << std::setw(2)
            << REQUIRED_ZERO_BITS[region];

        if (profile.zeros[region] >=
            REQUIRED_ZERO_BITS[region])
        {
            std::cout
                << "  PASS";
        }
        else
        {
            std::cout
                << "  FAIL";
        }

        std::cout << '\n';
    }

    std::cout
        << "TOTAL ZERO BITS: "
        << profile.total
        << '\n';

    std::cout
        << "RESULT: "
        << (profile.success
            ? "POW SUCCESS"
            : "FAIL")
        << '\n';

    std::cout
        << "------------------------------------------------------------\n";
}


// ================================================================
// MINE ONE BLOCK
// ================================================================

static Block mine_block(
    std::uint32_t block_index,
    const std::array<std::uint8_t, 32>& previous_hash,
    std::uint64_t& total_hashes,
    std::uint64_t& printed_hashes)
{
    Block block;

    block.index =
        block_index;

    block.previous_hash =
        previous_hash;

    // ------------------------------------------------------------
    // Header is initialized once.
    // Only bytes 36..43 change during mining.
    // ------------------------------------------------------------

    std::uint8_t header[44];

    make_header(
        block_index,
        previous_hash,
        0,
        header);


    std::uint8_t digest[32];


    const auto start =
        std::chrono::steady_clock::now();


    std::uint64_t nonce = 0;


    while (true)
    {
        // --------------------------------------------------------
        // Update nonce only.
        // --------------------------------------------------------

        header[36] =
            static_cast<std::uint8_t>(
                nonce >> 56);

        header[37] =
            static_cast<std::uint8_t>(
                nonce >> 48);

        header[38] =
            static_cast<std::uint8_t>(
                nonce >> 40);

        header[39] =
            static_cast<std::uint8_t>(
                nonce >> 32);

        header[40] =
            static_cast<std::uint8_t>(
                nonce >> 24);

        header[41] =
            static_cast<std::uint8_t>(
                nonce >> 16);

        header[42] =
            static_cast<std::uint8_t>(
                nonce >> 8);

        header[43] =
            static_cast<std::uint8_t>(
                nonce);


        // --------------------------------------------------------
        // SHA-256
        // --------------------------------------------------------

        sha256_header(
            header,
            digest);

        ++total_hashes;


        // --------------------------------------------------------
        // FAST POW TEST
        // --------------------------------------------------------

        if (check_pow(
                digest,
                nullptr))
        {
            // Winning hash.
            ZeroProfile profile;

            check_pow(
                digest,
                &profile);

            block.nonce =
                nonce;

            std::memcpy(
                block.hash.data(),
                digest,
                32);

            block.profile =
                profile;

            return block;
        }


        // --------------------------------------------------------
        // OPTIONAL HASH DISPLAY
        // --------------------------------------------------------

        if (SHOW_ALL_HASHES &&
            printed_hashes <
                MAX_PRINTED_HASHES)
        {
            ZeroProfile profile;

            check_pow(
                digest,
                &profile);

            print_attempt(
                block_index,
                nonce,
                digest,
                profile);

            ++printed_hashes;
        }


        // --------------------------------------------------------
        // PROGRESS
        // --------------------------------------------------------

        if (SHOW_PROGRESS &&
            total_hashes > 0 &&
            total_hashes %
                PROGRESS_INTERVAL == 0)
        {
            const auto now =
                std::chrono::steady_clock::now();

            const double seconds =
                std::chrono::duration<double>(
                    now - start)
                    .count();

            const double rate =
                seconds > 0.0
                ? static_cast<double>(
                      total_hashes) /
                      seconds
                : 0.0;

            std::cout
                << "\rBlock "
                << block_index
                << " | hashes = "
                << total_hashes
                << " | nonce = "
                << nonce
                << " | "
                << std::fixed
                << std::setprecision(2)
                << rate
                << " H/s"
                << std::flush;
        }


        // --------------------------------------------------------
        // NEXT NONCE
        // --------------------------------------------------------

        ++nonce;


        // Detect uint64 overflow.
        if (nonce == 0)
        {
            std::cerr
                << "\nNonce space exhausted.\n";

            std::exit(EXIT_FAILURE);
        }
    }
}


