for a much harder search. The program calculates the corresponding approximate expected work before mining starts.

One correction I made from the earlier version: **the SHA-256 header is exactly 44 bytes and the optimized miner hashes it as one fixed 64-byte SHA-256 block**, avoiding per-nonce heap allocation. The eight regions are also exactly the eight consecutive 32-bit words of the 256-bit digest, so there is no overlap or reuse between regions.

For the first run

- Use a faster test setup

Yes. The clean way to do this is to make the **lexical layer fractal**: each space-delimited token becomes a path through a recursive first-character partition:

`space → first character → second character → third character → ... → terminal`

The Markov/context layer can then operate on the resulting discrete word IDs exactly as before. This keeps the membrane/context graph intact while making vocabulary lookup hierarchical rather than a flat dictionary.

Below is the complete reorganized version. It also actually wires `beta`/`alpha` into the diffusion/blending path, while keeping the fractal lexical organization separate from the transition dynamics.

```python
import argparse
import glob
import math
import re
import sys
from collections import Counter

import numpy as np
import scipy.sparse as sp
from scipy.linalg import expm


UNK = "<unk>"
BOS = "<bos>"
SPACE = " "


# ============================================================================
# FRACTAL ORGANIZATION
# ============================================================================
#
# The lexical space is recursively partitioned by character.
#
# Example:
#
#     "the"
#
#     root
#       └── t
#           └── h
#               └── e
#                   └── <terminal>
#
# A corpus is first divided by SPACE into discrete lexical units.
# Each lexical unit is then recursively organized according to its
# successive first character.
#
# This produces:
#
#     SPACE
#       ├── a
#       │   ├── b
#       │   ├── c
#       │   └── ...
#       ├── b
#       ├── c
#       └── ...
#
# The recursion is deliberately independent from the Markov membrane.
# The fractal lexical tree determines word identity; the membrane determines
# transitions between context states.
# ============================================================================


class FractalNode:
    """
    One node of the recursive character tree.

    Every edge is labeled by one character.

    A terminal node corresponds to one complete space-delimited token.
    """

    __slots__ = (
        "children",
        "terminal",
        "token",
    )

    def __init__(self):
        self.children = {}
        self.terminal = False
        self.token = None

    def insert(self, token, position=0):
        if position >= len(token):
            self.terminal = True
            self.token = token
            return

        ch = token[position]

        if ch not in self.children:
            self.children[ch] = FractalNode()

        self.children[ch].insert(token, position + 1)

    def lookup(self, token, position=0):
        if position >= len(token):
            if self.terminal:
                return self.token
            return None

        ch = token[position]

        child = self.children.get(ch)
        if child is None:
            return None

        return child.lookup(token, position + 1)

    def collect_tokens(self, output=None):
        if output is None:
            output = []

        if self.terminal and self.token is not None:
            output.append(self.token)

        for ch in sorted(self.children):
            self.children[ch].collect_tokens(output)

        return output

    def depth(self):
        if not self.children:
            return 1

        return 1 + max(child.depth() for child in self.children.values())

    def node_count(self):
        total = 1

        for child in self.children.values():
            total += child.node_count()

        return total


class FractalLexicon:
    """
    Space-delimited lexical system organized recursively by first character.

    The important distinction is:

        token boundary = SPACE

        lexical organization =
            first character
            -> second character
            -> third character
            -> ...

    This gives a fractal/trie-like representation without changing the
    discrete token semantics used by the Markov model.
    """

    def __init__(self, special_tokens=None):
        self.root = FractalNode()

        if special_tokens:
            for token in special_tokens:
                self.insert(token)

    def insert(self, token):
        self.root.insert(token)

    def lookup(self, token):
        return self.root.lookup(token)

    def contains(self, token):
        return self.lookup(token) is not None

    def tokens(self):
        return self.root.collect_tokens()

    def depth(self):
        return self.root.depth()

    def node_count(self):
        return self.root.node_count()

    def first_character_buckets(self):
        return {
            ch: len(node.collect_tokens())
            for ch, node in sorted(self.root.children.items())
        }


# ============================================================================
# 1. DATASET LOADING
# ============================================================================


def read_files(paths):
    text_chunks = []

    if not paths:
        return text_chunks

    found_any = False

    for pattern in paths:
        for fp in sorted(glob.glob(pattern)):
            found_any = True

            try:
                with open(
                    fp,
                    "r",
                    encoding="utf-8",
                    errors="ignore",
                ) as f:
                    text_chunks.append(f.read())
            except OSError as exc:
                print(
                    f"[warn] could not read '{fp}': {exc}",
                    file=sys.stderr,
                )

    if not found_any:
        print(
            f"[warn] no files matched {paths}",
            file=sys.stderr,
        )

    return text_chunks


def tokenize_space_delimited(text, lowercase=True, strip_punct=False):
    """
    Space-delimited lexical tokenization.

    Punctuation is retained as separate discrete lexical units unless
    strip_punct=True.

    Example:

        "The fox, runs."

    becomes:

        ["the", "fox", ",", "runs", "."]

    The SPACE is therefore the primary token boundary.
    """

    if lowercase:
        text = text.lower()

    if strip_punct:
        return re.findall(
            r"[a-z0-9']+",
            text,
        )

    return re.findall(
        r"[a-z0-9']+|[.,!?;:]",
        text,
    )


def load_corpus(
    paths=None,
    raw_text=None,
    lowercase=True,
    strip_punct=False,
):
    text_chunks = read_files(paths)

    if raw_text:
        text_chunks.append(raw_text)

    if not text_chunks:
        text_chunks.append(_DEMO_CORPUS)

    full_text = "\n".join(text_chunks)

    return tokenize_space_delimited(
        full_text,
        lowercase=lowercase,
        strip_punct=strip_punct,
    )


# ============================================================================
# 2. FRACTAL VOCABULARY
# ============================================================================


def build_fractal_vocab(tokens, min_count=1):
    """
    Build the vocabulary through the fractal character tree.

    Frequency filtering happens before insertion.

    Returns:

        vocab
        word_to_idx
        counts
        fractal_lexicon
    """

    counts = Counter(tokens)

    kept = sorted(
        word
        for word, count in counts.items()
        if count >= min_count
    )

    vocab = [
        UNK,
        BOS,
    ] + kept

    word_to_idx = {
        word: i
        for i, word in enumerate(vocab)
    }

    lexicon = FractalLexicon(
        special_tokens=[
            UNK,
            BOS,
        ]
    )

    for word in kept:
        lexicon.insert(word)

    return (
        vocab,
        word_to_idx,
        counts,
        lexicon,
    )


# ============================================================================
# 3. FRACTAL TOKEN ENCODING
# ============================================================================


def encode_tokens(
    tokens,
    fractal_lexicon,
    word_to_idx,
):
    """
    Resolve each space-delimited lexical unit through the fractal tree.

    Unknown words fall into <unk>.
    """

    unk_idx = word_to_idx[UNK]

    encoded = []

    for token in tokens:
        resolved = fractal_lexicon.lookup(token)

        if resolved is None:
            encoded.append(unk_idx)
        else:
            encoded.append(
                word_to_idx.get(
                    resolved,
                    unk_idx,
                )
            )

    return encoded


# ============================================================================
# 4. MEMBRANE / CONTEXT STATE CONSTRUCTION
# ============================================================================


def build_membrane_transition_graph(
    tokens,
    word_to_idx,
    order=3,
):
    """
    Build:

        context -> context

    transition counts.

    For an order-3 model:

        [w1, w2] -> [w2, w3]

    Each transition crosses the discrete membrane once.
    """

    ctx_len = order - 1

    if ctx_len < 1:
        raise ValueError(
            "order must be >= 2"
        )

    bos_idx = word_to_idx[BOS]
    unk_idx = word_to_idx[UNK]

    ids = [
        word_to_idx.get(
            token,
            unk_idx,
        )
        for token in tokens
    ]

    padded = (
        [bos_idx] * ctx_len
        + ids
    )

    context_to_idx = {}
    contexts = []

    context_counts = Counter()
    edges = Counter()

    def get_ctx_idx(ctx):
        if ctx not in context_to_idx:
            context_to_idx[ctx] = len(contexts)
            contexts.append(ctx)

        return context_to_idx[ctx]

    n = len(padded)

    for i in range(n - ctx_len):
        ctx = tuple(
            padded[
                i:i + ctx_len
            ]
        )

        next_ctx = tuple(
            padded[
                i + 1:i + 1 + ctx_len
            ]
        )

        ci = get_ctx_idx(ctx)
        cj = get_ctx_idx(next_ctx)

        context_counts[ctx] += 1
        edges[(ci, cj)] += 1.0

    m = len(contexts)

    if edges:
        rows, cols, data = zip(
            *[
                (r, c, value)
                for (r, c), value in edges.items()
            ]
        )
    else:
        rows = ()
        cols = ()
        data = ()

    membrane = sp.csr_matrix(
        (
            data,
            (rows, cols),
        ),
        shape=(m, m),
        dtype=np.float64,
    )

    return (
        contexts,
        context_to_idx,
        membrane,
        context_counts,
    )


# ============================================================================
# 5. FRACTAL CONTEXT ORDERING
# ============================================================================
#
# Contexts are themselves recursively related because each transition removes
# the first lexical element and introduces one new lexical element.
#
# We retain the frequency ordering from the original implementation, but
# expose an optional character-aware ordering.
# ============================================================================


def log_sort_contexts(
    contexts,
    context_counts,
):
    def key(ctx):
        count = context_counts.get(
            ctx,
            0,
        )

        return -math.log(
            count + 1.0
        )

    return sorted(
        range(len(contexts)),
        key=lambda i: key(
            contexts[i]
        ),
    )


def fractal_context_sort(
    contexts,
    vocab,
    context_counts,
):
    """
    Character-aware recursive ordering.

    A context is represented by its lexical tokens. The first character of
    the first lexical token is used first, then subsequent lexical tokens.

    This does not alter probabilities; it only changes matrix ordering.
    """

    def lexical_signature(ctx):
        words = [
            vocab[token_id]
            for token_id in ctx
        ]

        chars = []

        for word in words:
            if word:
                chars.append(
                    word[0]
                )
            else:
                chars.append(
                    ""
                )

        return (
            tuple(chars),
            -context_counts.get(
                ctx,
                0,
            ),
            tuple(words),
        )

    return sorted(
        range(len(contexts)),
        key=lambda i: lexical_signature(
            contexts[i]
        ),
    )


def permute_matrix(M, order):
    order = np.asarray(
        order,
        dtype=np.int64,
    )

    if sp.issparse(M):
        return (
            M[order, :]
            [:, order]
            .tocsr()
        )

    return M[
        np.ix_(
            order,
            order,
        )
    ]


# ============================================================================
# 6. MEMBRANE FLUX NORMALIZATION
# ============================================================================


def membrane_flux_normalize(
    M,
    eps=1e-9,
):
    """
    Convert transition weights into a row-stochastic matrix.
    """

    if sp.issparse(M):
        row_sums = np.asarray(
            M.sum(axis=1)
        ).ravel()

        row_sums[
            row_sums == 0
        ] = 1.0

        inv = sp.diags(
            1.0 / row_sums
        )

        return (
            inv @ M
        ).tocsr()

    row_sums = M.sum(
        axis=1,
        keepdims=True,
    )

    row_sums[
        row_sums == 0
    ] = 1.0

    return (
        M
        / (
            row_sums
            + eps
        )
    )


# ============================================================================
# 7. MASS-DENSITY / DIFFUSION TERM
# ============================================================================


def build_mass_density_term(
    P,
    beta=0.15,
    remove_self_loops=True,
):
    """
    Continuous diffusion over the existing membrane.

    P is converted to a dense matrix only for this operation.
    """

    m = P.shape[0]

    if m == 0:
        return P

    if sp.issparse(P):
        P_dense = P.toarray()
    else:
        P_dense = np.asarray(
            P,
            dtype=np.float64,
        )

    L = (
        P_dense
        - np.eye(m)
    )

    D = expm(
        beta * L
    )

    D = np.clip(
        D,
        0.0,
        None,
    )

    if remove_self_loops:
        np.fill_diagonal(
            D,
            0.0,
        )

        row_sums = D.sum(
            axis=1
        )

        dead_rows = (
            row_sums
            <= 1e-12
        )

        if np.any(dead_rows):
            fallback = (
                P_dense.copy()
            )

            np.fill_diagonal(
                fallback,
                0.0,
            )

            fb_sums = fallback.sum(
                axis=1,
                keepdims=True,
            )

            fb_sums[
                fb_sums == 0
            ] = 1.0

            fallback = (
                fallback
                / fb_sums
            )

            D[
                dead_rows
            ] = fallback[
                dead_rows
            ]

    return membrane_flux_normalize(
        D
    )


def blend_temporal_orientation(
    P_retrospective,
    P_diffused,
    alpha=0.5,
    remove_self_loops=True,
):
    """
    Linear mixture between the retrospective transition law and the
    diffused transition law.

    alpha = 0:
        pure retrospective

    alpha = 1:
        pure diffusion
    """

    alpha = float(
        np.clip(
            alpha,
            0.0,
            1.0,
        )
    )

    P_ret = (
        P_retrospective.toarray()
        if sp.issparse(
            P_retrospective
        )
        else np.asarray(
            P_retrospective,
            dtype=np.float64,
        )
    )

    P_diff = (
        P_diffused.toarray()
        if sp.issparse(
            P_diffused
        )
        else np.asarray(
            P_diffused,
            dtype=np.float64,
        )
    )

    P = (
        (1.0 - alpha)
        * P_ret
        + alpha
        * P_diff
    )

    if remove_self_loops:
        np.fill_diagonal(
            P,
            0.0,
        )

    return membrane_flux_normalize(
        P
    )


# ============================================================================
# 8. MASS-DENSITY MEASUREMENT
# ============================================================================


def compute_mass_density(
    num_states,
    dtype_bytes=8,
):
    dense_bytes = (
        num_states
        ** 2
        * dtype_bytes
    )

    rho_eff = (
        dense_bytes
        / max(
            num_states,
            1,
        )
    )

    return (
        dense_bytes,
        rho_eff,
    )


# ============================================================================
# 9. TEMPORAL INDEX
# ============================================================================


def compute_temporal_index(
    boost_strength,
    lookahead_ops=1,
    retrospective_ops=1,
):
    if boost_strength == 0.0:
        return -1.0

    total = (
        lookahead_ops
        + retrospective_ops
    )

    if total <= 0:
        return 0.0

    numerator = (
        boost_strength
        * lookahead_ops
        - retrospective_ops
    )

    denominator = (
        boost_strength
        * lookahead_ops
        + retrospective_ops
    )

    if denominator == 0:
        return 0.0

    return (
        numerator
        / denominator
    )


# ============================================================================
# 10. TEMPERATURE
# ============================================================================


def sinusoidal_temperature(
    step,
    base_temp=0.8,
    amplitude=0.4,
    omega=0.5,
    phase=0.0,
    floor=0.05,
):
    temperature = (
        base_temp
        + amplitude
        * math.sin(
            omega * step
            + phase
        )
    )

    return max(
        floor,
        temperature,
    )


# ============================================================================
# 11. BOUNDARY SAMPLING
# ============================================================================


def sample_at_boundary(
    probs,
    temperature=1.0,
    top_k=10,
    rng=None,
    lookahead_bias=None,
    boost_strength=0.0,
):
    rng = (
        rng
        if rng is not None
        else np.random.default_rng()
    )

    probs = np.asarray(
        probs,
        dtype=np.float64,
    )

    nonzero_idx = np.nonzero(
        probs > 0
    )[0]

    if len(nonzero_idx) == 0:
        return None

    if (
        top_k is not None
        and 0 < top_k
        < len(nonzero_idx)
    ):
        sub = np.argpartition(
            probs[nonzero_idx],
            -top_k,
        )[-top_k:]

        top_idx = (
            nonzero_idx[sub]
        )
    else:
        top_idx = nonzero_idx

    top_probs = probs[
        top_idx
    ]

    temperature = max(
        float(temperature),
        1e-6,
    )

    logits = (
        np.log(
            top_probs
        )
        / temperature
    )

    if (
        lookahead_bias is not None
        and boost_strength != 0.0
    ):
        bias = np.asarray(
            lookahead_bias,
            dtype=np.float64,
        )

        logits = (
            logits
            + boost_strength
            * bias[top_idx]
        )

    logits -= logits.max()

    weights = np.exp(
        logits
    )

    total = weights.sum()

    if (
        not np.isfinite(total)
        or total <= 0
    ):
        weights = np.ones(
            len(top_idx),
            dtype=np.float64,
        )
        weights /= weights.sum()
    else:
        weights /= total

    choice = rng.choice(
        len(top_idx),
        p=weights,
    )

    return int(
        top_idx[choice]
    )


# ============================================================================
# 12. PAYLOAD PARSING
# ============================================================================


def parse_payload(
    payload_str,
    word_to_idx,
):
    vocab_size = len(
        word_to_idx
    )

    payload_vector = np.zeros(
        vocab_size,
        dtype=np.float64,
    )

    if not payload_str:
        return payload_vector

    for item in payload_str.split(","):
        item = item.strip()

        if not item:
            continue

        if ":" in item:
            word, weight_str = (
                item.rsplit(
                    ":",
                    1,
                )
            )

            try:
                weight = float(
                    weight_str
                )
            except ValueError:
                print(
                    f"[warn] payload entry "
                    f"'{item}' has a non-numeric "
                    f"weight; skipping",
                    file=sys.stderr,
                )
                continue
        else:
            word = item
            weight = 1.0

        word = word.strip().lower()

        idx = word_to_idx.get(
            word
        )

        if idx is None:
            print(
                f"[warn] payload word "
                f"'{word}' is not in "
                f"the vocabulary; skipping",
                file=sys.stderr,
            )
            continue

        payload_vector[
            idx
        ] = weight

    return payload_vector


# ============================================================================
# 13. HECM MODEL
# ============================================================================


class HECMModel:
    """
    HECM with three separate layers:

        1. FRACTAL LEXICON
           character-recursive lexical organization

        2. MEMBRANE
           context -> context transition graph

        3. DECISION OPERATOR
           temperature/top-k/payload reranking

    The layers remain mathematically distinct.
    """

    def __init__(
        self,
        tokens,
        order=3,
        min_count=1,
        beta=0.0,
        alpha=0.0,
        max_diffusion_states=1500,
        payload=None,
        boost_strength=0.0,
    ):
        self.order = order
        self.beta = beta
        self.alpha = alpha
        self.max_diffusion_states = (
            max_diffusion_states
        )

        # ------------------------------------------------------------
        # FRACTAL LEXICAL LAYER
        # ------------------------------------------------------------

        (
            vocab,
            word_to_idx,
            counts,
            fractal_lexicon,
        ) = build_fractal_vocab(
            tokens,
            min_count=min_count,
        )

        self.vocab = vocab
        self.word_to_idx = word_to_idx
        self.counts = counts
        self.fractal_lexicon = (
            fractal_lexicon
        )

        # ------------------------------------------------------------
        # MEMBRANE CONSTRUCTION
        # ------------------------------------------------------------

        (
            contexts,
            context_to_idx,
            membrane,
            context_counts,
        ) = build_membrane_transition_graph(
            tokens,
            word_to_idx,
            order=order,
        )

        # ------------------------------------------------------------
        # FRACTAL/FREQUENCY MATRIX ORDER
        # ------------------------------------------------------------

        perm = fractal_context_sort(
            contexts,
            vocab,
            context_counts,
        )

        contexts = [
            contexts[i]
            for i in perm
        ]

        membrane = permute_matrix(
            membrane,
            perm,
        )

        context_to_idx = {
            ctx: i
            for i, ctx in enumerate(
                contexts
            )
        }

        self.contexts = contexts
        self.context_to_idx = (
            context_to_idx
        )
        self.context_counts = (
            context_counts
        )

        # ------------------------------------------------------------
        # RETROSPECTIVE LAW
        # ------------------------------------------------------------

        self.P_retrospective = (
            membrane_flux_normalize(
                membrane
            )
        )

        # ------------------------------------------------------------
        # MASS DENSITY
        # ------------------------------------------------------------

        num_states = len(
            contexts
        )

        (
            self.dense_bytes,
            self.rho_eff,
        ) = compute_mass_density(
            num_states
        )

        # ------------------------------------------------------------
        # DIFFUSION
        # ------------------------------------------------------------

        if (
            beta > 0.0
            and num_states
            <= max_diffusion_states
        ):
            self.P_diffused = (
                build_mass_density_term(
                    self.P_retrospective,
                    beta=beta,
                    remove_self_loops=True,
                )
            )

            self.P_final = (
                blend_temporal_orientation(
                    self.P_retrospective,
                    self.P_diffused,
                    alpha=alpha,
                    remove_self_loops=True,
                )
            )

        else:
            self.P_diffused = (
                self.P_retrospective
            )

            self.P_final = (
                self.P_retrospective
            )

        # ------------------------------------------------------------
        # TEMPORAL INDEX
        # ------------------------------------------------------------

        self.boost_strength = (
            boost_strength
        )

        self.tau = (
            compute_temporal_index(
                boost_strength
            )
        )

        # ------------------------------------------------------------
        # PAYLOAD
        # ------------------------------------------------------------

        if payload is None:
            payload = np.zeros(
                len(vocab),
                dtype=np.float64,
            )

        self.payload = payload

        self._rebuild_payload_scores()

    # ==================================================================
    # MODEL METADATA
    # ==================================================================

    def vocab_size(self):
        return len(
            self.vocab
        )

    def num_states(self):
        return len(
            self.contexts
        )

    def fractal_depth(self):
        return (
            self.fractal_lexicon.depth()
        )

    def fractal_nodes(self):
        return (
            self.fractal_lexicon.node_count()
        )

    # ==================================================================
    # PAYLOAD
    # ==================================================================

    def _rebuild_payload_scores(self):
        self.context_word_score = np.array(
            [
                sum(
                    self.payload[word_id]
                    for word_id in ctx
                )
                for ctx in self.contexts
            ],
            dtype=np.float64,
        )

        self.introduced_word_score = np.array(
            [
                self.payload[
                    ctx[-1]
                ]
                for ctx in self.contexts
            ],
            dtype=np.float64,
        )

        self.context_total_score = (
            self.context_word_score
        )

    # ==================================================================
    # MATRIX ACCESS
    # ==================================================================

    def _get_row(self, ctx_idx):
        row = self.P_final[
            ctx_idx
        ]

        if sp.issparse(
            self.P_final
        ):
            return np.asarray(
                row.todense()
            ).ravel()

        return np.asarray(
            row,
            dtype=np.float64,
        )

    # ==================================================================
    # FRACTAL PROMPT TOKENIZATION
    # ==================================================================

    def _tokenize_prompt(self, prompt):
        tokens = tokenize_space_delimited(
            prompt,
            lowercase=True,
            strip_punct=False,
        )

        return encode_tokens(
            tokens,
            self.fractal_lexicon,
            self.word_to_idx,
        )

    # ==================================================================
    # CONTEXT FALLBACK
    # ==================================================================

    def _weighted_pick(
        self,
        candidates,
        boost_strength,
        rng,
    ):
        if not candidates:
            return None

        if (
            boost_strength == 0.0
            or len(candidates) == 1
        ):
            return candidates[
                rng.integers(
                    len(candidates)
                )
            ]

        scores = (
            boost_strength
            * self.context_total_score[
                candidates
            ]
        )

        scores -= scores.max()

        weights = np.exp(
            scores
        )

        total = weights.sum()

        if (
            not np.isfinite(total)
            or total <= 0
        ):
            return candidates[
                rng.integers(
                    len(candidates)
                )
            ]

        weights /= total

        return candidates[
            rng.choice(
                len(candidates),
                p=weights,
            )
        ]

    def _initial_context(
        self,
        prompt_ids,
        rng,
        boost_strength=0.0,
    ):
        ctx_len = (
            self.order - 1
        )

        bos = self.word_to_idx[
            BOS
        ]

        padded = (
            [bos] * ctx_len
            + prompt_ids
        )

        desired = tuple(
            padded[-ctx_len:]
        )

        if (
            desired
            in self.context_to_idx
        ):
            return self.context_to_idx[
                desired
            ]

        # ------------------------------------------------------------
        # FRACTAL SUFFIX SEARCH
        # ------------------------------------------------------------

        for k in range(
            ctx_len - 1,
            0,
            -1,
        ):
            suffix = desired[
                -k:
            ]

            candidates = [
                i
                for i, ctx
                in enumerate(
                    self.contexts
                )
                if ctx[-k:] == suffix
            ]

            if candidates:
                return self._weighted_pick(
                    candidates,
                    boost_strength,
                    rng,
                )

        # ------------------------------------------------------------
        # FREQUENCY FALLBACK
        # ------------------------------------------------------------

        counts_arr = np.array(
            [
                self.context_counts.get(
                    ctx,
                    0,
                )
                for ctx in self.contexts
            ],
            dtype=np.float64,
        )

        count = min(
            10,
            len(
                counts_arr
            ),
        )

        if count == 0:
            return None

        top_candidates = list(
            np.argsort(
                counts_arr
            )[-count:]
        )

        return self._weighted_pick(
            top_candidates,
            boost_strength,
            rng,
        )

    # ==================================================================
    # GENERATION
    # ==================================================================

    def generate(
        self,
        prompt,
        max_new_tokens=40,
        top_k=10,
        base_temp=0.8,
        amplitude=0.4,
        omega=0.5,
        phase=0.0,
        seed=None,
        boost_strength=0.0,
    ):
        rng = np.random.default_rng(
            seed
        )

        prompt_ids = (
            self._tokenize_prompt(
                prompt
            )
        )

        ctx_idx = (
            self._initial_context(
                prompt_ids,
                rng,
                boost_strength=boost_strength,
            )
        )

        if ctx_idx is None:
            self.last_quanta_crossed = 0
            return _detokenize(
                [
                    self.vocab[i]
                    for i in prompt_ids
                ]
            )

        out_ids = list(
            prompt_ids
        )

        quanta_crossed = 0

        for step in range(
            max_new_tokens
        ):
            temperature = (
                sinusoidal_temperature(
                    step,
                    base_temp=base_temp,
                    amplitude=amplitude,
                    omega=omega,
                    phase=phase,
                )
            )

            probs = self._get_row(
                ctx_idx
            )

            next_ctx_idx = (
                sample_at_boundary(
                    probs,
                    temperature=temperature,
                    top_k=top_k,
                    rng=rng,
                    lookahead_bias=(
                        self.introduced_word_score
                    ),
                    boost_strength=(
                        boost_strength
                    ),
                )
            )

            if next_ctx_idx is None:
                ctx_idx = (
                    self._initial_context(
                        out_ids,
                        rng,
                        boost_strength=boost_strength,
                    )
                )

                if ctx_idx is None:
                    break

                continue

            next_word_id = (
                self.contexts[
                    next_ctx_idx
                ][-1]
            )

            out_ids.append(
                next_word_id
            )

            ctx_idx = (
                next_ctx_idx
            )

            quanta_crossed += 1

        self.last_quanta_crossed = (
            quanta_crossed
        )

        words = [
            self.vocab[i]
            for i in out_ids
        ]

        return _detokenize(
            words
        )


# ============================================================================
# 14. DETOKENIZATION
# ============================================================================


def _detokenize(tokens):
    out = []

    for token in tokens:
        if token in (
            BOS,
        ):
            continue

        if (
            out
            and re.match(
                r"[.,!?;:]",
                token,
            )
        ):
            out[-1] = (
                out[-1]
                + token
            )
        else:
            out.append(
                token
            )

    text = " ".join(
        out
    )

    if text:
        text = (
            text[0].upper()
            + text[1:]
        )

    return text


