from collections import Counter

import numpy as np
import scipy.sparse as sp
from scipy.linalg import expm


UNK = "<unk>"
BOS = "<bos>"


# ============================================================================
# DEMO DATASET
# ============================================================================

_DEMO_CORPUS = """
the quick brown fox jumps over the lazy dog.
the fox runs through the forest.
the dog watches the fox.
the forest contains trees, rivers, stones, and animals.
the river flows through the valley.
the valley contains a quiet village.
the village watches the river.
a language model predicts the next token from its context.
a fractal lexicon organizes words by their characters.
a membrane transition graph represents movement between contexts.
probability flows through the context membrane.
temporal diffusion changes the boundary distribution.
the model samples a new word and continues the sequence.
"""


# ============================================================================
# FRACTAL CHARACTER LEXICON
# ============================================================================

class FractalNode:

    __slots__ = ("children", "terminal", "token")

    def __init__(self):
        self.children = {}
        self.terminal = False
        self.token = None

    def insert(self, token, position=0):
        if position >= len(token):
            self.terminal = True
            self.token = token
            return

        ch = token[position]
        child = self.children.get(ch)

        if child is None:
            child = FractalNode()
            self.children[ch] = child

        child.insert(token, position + 1)

    def lookup(self, token, position=0):
        if position >= len(token):
            return self.token if self.terminal else None

        child = self.children.get(token[position])

        if child is None:
            return None

        return child.lookup(token, position + 1)

    def collect_tokens(self, output=None):
        if output is None:
            output = []

        if self.terminal and self.token is not None:
            output.append(self.token)

        for ch in sorted(self.children):
            self.children[ch].collect_tokens(output)

        return output

    def depth(self):
        if not self.children:
            return 1

        return 1 + max(
            child.depth()
            for child in self.children.values()
        )

    def node_count(self):
        return 1 + sum(
            child.node_count()
            for child in self.children.values()
        )


class FractalLexicon:

    def __init__(self, special_tokens=None):
        self.root = FractalNode()

        for token in special_tokens or []:
            self.insert(token)

    def insert(self, token):
        self.root.insert(token)

    def lookup(self, token):
        return self.root.lookup(token)

    def tokens(self):
        return self.root.collect_tokens()

    def depth(self):
        return self.root.depth()

    def node_count(self):
        return self.root.node_count()

    def first_character_buckets(self):
        return {
            ch: len(node.collect_tokens())
            for ch, node in sorted(
                self.root.children.items()
            )
        }


# ============================================================================
# TOKENIZATION
# ============================================================================

def tokenize_space_delimited(
    text,
    lowercase=True,
    strip_punct=False,
):
    if lowercase:
        text = text.lower()

    if strip_punct:
        return re.findall(
            r"[a-z0-9']+",
            text,
        )

    return re.findall(
        r"[a-z0-9']+|[.,!?;:]",
        text,
    )


def load_corpus(
    paths=None,
    raw_text=None,
    lowercase=True,
    strip_punct=False,
):
    chunks = []

    if paths:
        found = False

        for pattern in paths:
            matches = sorted(
                glob.glob(pattern)
            )

            for fp in matches:
                found = True

                with open(
                    fp,
                    "r",
                    encoding="utf-8",
                    errors="ignore",
                ) as f:
                    chunks.append(f.read())

        if not found:
            print(
                f"[warn] no files matched: {paths}",
                file=sys.stderr,
            )

    if raw_text:
        chunks.append(raw_text)

    if not chunks:
        chunks.append(_DEMO_CORPUS)

    return tokenize_space_delimited(
        "\n".join(chunks),
        lowercase=lowercase,
        strip_punct=strip_punct,
    )


# ============================================================================
# FRACTAL VOCABULARY
# ============================================================================

def build_fractal_vocab(
    tokens,
    min_count=1,
):
    counts = Counter(tokens)

    kept = sorted(
        word
        for word, count in counts.items()
        if count >= min_count
    )

    vocab = [
        UNK,
        BOS,
    ] + kept

    word_to_idx = {
        word: i
        for i, word in enumerate(vocab)
    }

    lexicon = FractalLexicon([
        UNK,
        BOS,
    ])

    for word in kept:
        lexicon.insert(word)

    return (
        vocab,
        word_to_idx,
        counts,
        lexicon,
    )


def encode_tokens(
    tokens,
    lexicon,
    word_to_idx,
):
    unk = word_to_idx[UNK]
    encoded = []

    for token in tokens:
        resolved = lexicon.lookup(token)

        encoded.append(
            word_to_idx.get(
                resolved,
                unk,
            )
            if resolved is not None
            else unk
        )

    return encoded


# ============================================================================
# MEMBRANE TRANSITION GRAPH
# ============================================================================

def build_membrane_transition_graph(
    tokens,
    word_to_idx,
    order=3,
):
    if order < 2:
        raise ValueError(
            "order must be >= 2"
        )

    context_len = order - 1

    bos = word_to_idx[BOS]
    unk = word_to_idx[UNK]

    ids = [
        word_to_idx.get(
            token,
            unk,
        )
        for token in tokens
    ]

    padded = [
        bos
    ] * context_len + ids

    context_to_idx = {}
    contexts = []
    context_counts = Counter()
    edges = Counter()

    def get_context_index(ctx):
        idx = context_to_idx.get(ctx)

        if idx is None:
            idx = len(contexts)
            context_to_idx[ctx] = idx
            contexts.append(ctx)

        return idx

    for i in range(
        len(padded) - context_len
    ):
        ctx = tuple(
            padded[
                i:i + context_len
            ]
        )

        nxt = tuple(
            padded[
                i + 1:
                i + 1 + context_len
            ]
        )

        ci = get_context_index(ctx)
        cj = get_context_index(nxt)

        context_counts[ctx] += 1
        edges[(ci, cj)] += 1.0

    n = len(contexts)

    if edges:
        rows, cols, data = zip(
            *[
                (r, c, v)
                for (r, c), v
                in edges.items()
            ]
        )
    else:
        rows, cols, data = [], [], []

    matrix = sp.csr_matrix(
        (
            data,
            (rows, cols),
        ),
        shape=(n, n),
        dtype=np.float64,
    )

    return (
        contexts,
        context_to_idx,
        matrix,
        context_counts,
    )


def fractal_context_sort(
    contexts,
    vocab,
    context_counts,
):
    def key(ctx):
        words = tuple(
            vocab[i]
            for i in ctx
        )

        first_chars = tuple(
            word[0]
            if word
            else ""
            for word in words
        )

        return (
            first_chars,
            -context_counts.get(
                ctx,
                0,
            ),
            words,
        )

    return sorted(
        range(len(contexts)),
        key=lambda i: key(
            contexts[i]
        ),
    )


def permute_matrix(
    matrix,
    order,
):
    order = np.asarray(
        order,
        dtype=np.int64,
    )

    if sp.issparse(matrix):
        return matrix[
            order,
            :
        ][
            :,
            order
        ].tocsr()

    return matrix[
        np.ix_(
            order,
            order,
        )
    ]


def membrane_flux_normalize(
    matrix,
    eps=1e-12,
):
    if sp.issparse(matrix):
        sums = np.asarray(
            matrix.sum(
                axis=1
            )
        ).ravel()

        sums[
            sums <= eps
        ] = 1.0

        return (
            sp.diags(
                1.0 / sums
            ) @ matrix
        ).tocsr()

    sums = matrix.sum(
        axis=1,
        keepdims=True,
    )

    sums[
        sums <= eps
    ] = 1.0

    return matrix / sums


# ============================================================================
# MASS-DENSITY / TEMPORAL DIFFUSION
# ============================================================================

def build_mass_density_term(
    P,
    beta=0.15,
    remove_self_loops=True,
):
    if sp.issparse(P):
        P = P.toarray()

    P = np.asarray(
        P,
        dtype=np.float64,
    )

    n = P.shape[0]

    if n == 0:
        return P

    generator = (
        P - np.eye(n)
    )

    density = expm(
        beta * generator
    )

    density = np.nan_to_num(
        density,
        nan=0.0,
        posinf=0.0,
        neginf=0.0,
    )

    density = np.clip(
        density,
        0.0,
        None,
    )

    if remove_self_loops:
        np.fill_diagonal(
            density,
            0.0,
        )

    row_sum = density.sum(
        axis=1
    )

    dead = (
        row_sum <= 1e-12
    )

    if np.any(dead):
        fallback = P.copy()

        np.fill_diagonal(
            fallback,
            0.0,
        )

        fallback_sum = fallback.sum(
            axis=1,
            keepdims=True,
        )

        fallback_sum[
            fallback_sum <= 1e-12
        ] = 1.0

        fallback = (
            fallback
            / fallback_sum
        )

        density[dead] = (
            fallback[dead]
        )

    return membrane_flux_normalize(
        density
    )


def blend_temporal_orientation(
    P_retrospective,
    P_diffused,
    alpha=0.5,
):
    alpha = float(
        np.clip(
            alpha,
            0.0,
            1.0,
        )
    )

    if sp.issparse(
        P_retrospective
    ):
        P_retrospective = (
            P_retrospective.toarray()
        )

    if sp.issparse(
        P_diffused
    ):
        P_diffused = (
            P_diffused.toarray()
        )

    P = (
        (1.0 - alpha)
        * np.asarray(
            P_retrospective
        )
        + alpha
        * np.asarray(
            P_diffused
        )
    )

    P = np.nan_to_num(
        P,
        nan=0.0,
        posinf=0.0,
        neginf=0.0,
    )

    P = np.clip(
        P,
        0.0,
        None,
    )

    np.fill_diagonal(
        P,
        0.0,
    )

    return membrane_flux_normalize(
        P
    )


def compute_mass_density(
    num_states,
    dtype_bytes=8,
):
    dense_bytes = (
        int(num_states) ** 2
        * dtype_bytes
    )

    bytes_per_state = (
        dense_bytes
        / max(
            int(num_states),
            1,
        )
    )

    return (
        dense_bytes,
        bytes_per_state,
    )


def compute_temporal_index(
    boost_strength,
):
    if boost_strength == 0.0:
        return -1.0

    return (
        boost_strength - 1.0
    ) / (
        boost_strength + 1.0
    )


# ============================================================================
# SAMPLING
# ============================================================================

def sinusoidal_temperature(
    step,
    base_temp=0.8,
    amplitude=0.4,
    omega=0.5,
    phase=0.0,
    floor=0.05,
):
    value = (
        base_temp
        + amplitude
        * math.sin(
            omega * step
            + phase
        )
    )

    return max(
        floor,
        value,
    )


def sample_at_boundary(
    probs,
    temperature=1.0,
    top_k=10,
    rng=None,
    lookahead_bias=None,
    boost_strength=0.0,
):
    rng = (
        rng
        or np.random.default_rng()
    )

    probs = np.asarray(
        probs,
        dtype=np.float64,
    )

    probs = np.nan_to_num(
        probs,
        nan=0.0,
        posinf=0.0,
        neginf=0.0,
    )

    probs = np.clip(
        probs,
        0.0,
        None,
    )

    indices = np.flatnonzero(
        probs > 0.0
    )

    if len(indices) == 0:
        return None

    if (
        top_k is not None
        and 0 < top_k < len(indices)
    ):
        chosen = np.argpartition(
            probs[indices],
            -top_k,
        )[-top_k:]

        indices = indices[
            chosen
        ]

    temperature = max(
        float(temperature),
        1e-6,
    )

    logits = np.log(
        np.maximum(
            probs[indices],
            1e-300,
        )
    ) / temperature

    if (
        lookahead_bias is not None
        and boost_strength != 0.0
    ):
        bias = np.asarray(
            lookahead_bias,
            dtype=np.float64,
        )

        logits += (
            float(boost_strength)
            * bias[indices]
        )

    logits -= np.max(
        logits
    )

    weights = np.exp(
        logits
    )

    total = weights.sum()

    if (
        not np.isfinite(total)
        or total <= 0.0
    ):
        weights = (
            np.ones(
                len(indices)
            )
            / len(indices)
        )
    else:
        weights /= total

    return int(
        indices[
            rng.choice(
                len(indices),
                p=weights,
            )
        ]
    )


# ============================================================================
# PAYLOAD
# ============================================================================

def parse_payload(
    payload_str,
    word_to_idx,
):
    vector = np.zeros(
        len(word_to_idx),
        dtype=np.float64,
    )

    if not payload_str:
        return vector

    for item in payload_str.split(","):
        item = item.strip()

        if not item:
            continue

        if ":" in item:
            word, value = item.rsplit(
                ":",
                1,
            )

            try:
                weight = float(value)
            except ValueError:
                continue

        else:
            word = item
            weight = 1.0

        word = (
            word
            .strip()
            .lower()
        )

        idx = word_to_idx.get(
            word
        )

        if idx is not None:
            vector[idx] = weight

    return vector


# ============================================================================
# HECM MODEL
# ============================================================================

class HECMModel:

    def __init__(
        self,
        tokens,
        order=3,
        min_count=1,
        beta=0.0,
        alpha=0.0,
        max_diffusion_states=1500,
        payload=None,
        boost_strength=0.0,
    ):
        self.order = int(order)
        self.beta = float(beta)
        self.alpha = float(alpha)

        self.max_diffusion_states = int(
            max_diffusion_states
        )

        (
            self.vocab,
            self.word_to_idx,
            self.counts,
            self.lexicon,
        ) = build_fractal_vocab(
            tokens,
            min_count,
        )

        (
            contexts,
            _,
            membrane,
            context_counts,
        ) = build_membrane_transition_graph(
            tokens,
            self.word_to_idx,
            self.order,
        )

        permutation = fractal_context_sort(
            contexts,
            self.vocab,
            context_counts,
        )

        self.contexts = [
            contexts[i]
            for i in permutation
        ]

        membrane = permute_matrix(
            membrane,
            permutation,
        )

        self.context_to_idx = {
            ctx: i
            for i, ctx in enumerate(
                self.contexts
            )
        }

        self.context_counts = (
            context_counts
        )

        self.P_retrospective = (
            membrane_flux_normalize(
                membrane
            )
        )

        (
            self.dense_bytes,
            self.rho_eff,
        ) = compute_mass_density(
            len(self.contexts)
        )

        if (
            self.beta > 0.0
            and len(self.contexts)
            <= self.max_diffusion_states
        ):
            self.P_diffused = (
                build_mass_density_term(
                    self.P_retrospective,
                    self.beta,
                )
            )

            self.P_final = (
                blend_temporal_orientation(
                    self.P_retrospective,
                    self.P_diffused,
                    self.alpha,
                )
            )

        else:
            self.P_diffused = (
                self.P_retrospective
            )

            self.P_final = (
                self.P_retrospective
            )

        self.boost_strength = float(
            boost_strength
        )

        self.tau = compute_temporal_index(
            self.boost_strength
        )

        self.payload = (
            payload
            if payload is not None
            else np.zeros(
                len(self.vocab),
                dtype=np.float64,
            )
        )

        self._rebuild_payload_scores()
        self.last_quanta_crossed = 0

    def _rebuild_payload_scores(self):
        self.context_word_score = np.array(
            [
                sum(
                    self.payload[w]
                    for w in ctx
                )
                for ctx in self.contexts
            ],
            dtype=np.float64,
        )

        self.introduced_word_score = np.array(
            [
                self.payload[
                    ctx[-1]
                ]
                for ctx in self.contexts
            ],
            dtype=np.float64,
        )

        self.context_total_score = (
            self.context_word_score
        )

    def vocab_size(self):
        return len(self.vocab)

    def num_states(self):
        return len(self.contexts)

    def fractal_depth(self):
        return self.lexicon.depth()

    def fractal_nodes(self):
        return self.lexicon.node_count()

    def _get_row(self, index):
        if sp.issparse(
            self.P_final
        ):
            row = self.P_final[
                index
            ]

            return np.asarray(
                row.toarray()
            ).ravel()

        return np.asarray(
            self.P_final[index]
        ).ravel()

    def _tokenize_prompt(
        self,
        prompt,
    ):
        tokens = tokenize_space_delimited(
            prompt
        )

        return encode_tokens(
            tokens,
            self.lexicon,
            self.word_to_idx,
        )

    def _initial_context(
        self,
        prompt_ids,
        rng,
    ):
        context_len = (
            self.order - 1
        )

        bos = self.word_to_idx[BOS]

        desired = tuple(
            (
                [bos] * context_len
                + prompt_ids
            )[
                -context_len:
            ]
        )

        exact = self.context_to_idx.get(
            desired
        )

        if exact is not None:
            return exact

        for k in range(
            context_len - 1,
            0,
            -1,
        ):
            suffix = desired[
                -k:
            ]

            candidates = [
                i
                for i, ctx
                in enumerate(
                    self.contexts
                )
                if ctx[-k:] == suffix
            ]

            if candidates:
                return int(
                    candidates[
                        rng.integers(
                            len(candidates)
                        )
                    ]
                )

        counts = np.array(
            [
                self.context_counts.get(
                    ctx,
                    0,
                )
                for ctx in self.contexts
            ],
            dtype=np.float64,
        )

        return int(
            np.argmax(counts)
        )

    def generate(
        self,
        prompt,
        max_new_tokens=40,
        top_k=10,
        base_temp=0.8,
        amplitude=0.4,
        omega=0.5,
        phase=0.0,
        seed=None,
        boost_strength=0.0,
    ):
        rng = np.random.default_rng(
            seed
        )

        prompt_ids = (
            self._tokenize_prompt(
                prompt
            )
        )

        ctx_idx = (
            self._initial_context(
                prompt_ids,
                rng,
            )
        )

        output = list(
            prompt_ids
        )

        crossed = 0

        for step in range(
            int(max_new_tokens)
        ):
            temperature = (
                sinusoidal_temperature(
                    step,
                    base_temp,
                    amplitude,
                    omega,
                    phase,
                )
            )

            probs = self._get_row(
                ctx_idx
            )

            nxt = sample_at_boundary(
                probs,
                temperature,
                top_k,
                rng,
                self.introduced_word_score,
                boost_strength,
            )

            if nxt is None:
                break

            next_token = (
                self.contexts[nxt][-1]
            )

            output.append(
                next_token
            )

            ctx_idx = nxt
            crossed += 1

        self.last_quanta_crossed = (
            crossed
        )

        return _detokenize(
            [
                self.vocab[i]
                for i in output
            ]
        )


# ============================================================================
# DETOKENIZATION
# ============================================================================

def _detokenize(tokens):
    output = []

    for token in tokens:
        if token == BOS:
            continue

        if (
            output
            and re.fullmatch(
                r"[.,!?;:]",
                token,
            )
        ):
            output[-1] += token

        else:
            output.append(token)

    text = " ".join(
        output
    )

    if text:
        text = (
            text[:1].upper()
            + text[1:]
        )

    return text


# ============================================================================
# DIAGNOSTICS
# ============================================================================

def print_model_diagnostics(
    model,
):
    print(
        "[info] "
        f"vocab={model.vocab_size()} | "
        f"states={model.num_states()} | "
        f"fractal_nodes={model.fractal_nodes()} | "
        f"fractal_depth={model.fractal_depth()} | "
        f"rho_eff={model.rho_eff:.1f} bytes/state | "
        f"tau={model.tau:.3f}",
        file=sys.stderr,
    )

    if (
        model.beta > 0.0
        and model.num_states()
        > model.max_diffusion_states
    ):
        print(
            "[info] diffusion skipped: "
            f"{model.num_states()} states exceed "
            "max_diffusion_states="
            f"{model.max_diffusion_states}",
            file=sys.stderr,
        )

    elif model.beta > 0.0:
        print(
            "[info] mass-density diffusion enabled: "
            f"beta={model.beta:.4g}, "
            f"alpha={model.alpha:.4g}",
            file=sys.stderr,
        )


# ============================================================================
# SELF TEST
# ============================================================================

def _self_test(model):
    if model.vocab_size() < 2:
        raise RuntimeError(
            "Vocabulary construction failed."
        )

    if model.num_states() == 0:
        raise RuntimeError(
            "No membrane states were created."
        )

    row = model._get_row(0)

    if not np.all(
        np.isfinite(row)
    ):
        raise RuntimeError(
            "Transition row contains "
            "non-finite values."
        )

    if np.any(
        row < -1e-10
    ):
        raise RuntimeError(
            "Transition row contains "
            "negative probabilities."
        )

    total = float(
        row.sum()
    )

    if (
        total > 0.0
        and not np.isclose(
            total,
            1.0,
            atol=1e-6,
        )
    ):
        raise RuntimeError(
            "Transition row is not "
            f"normalized: {total}"
        )


# ============================================================================
# MAIN
# ============================================================================

def main():
    parser = argparse.ArgumentParser(
        description=(
            "Fractal HECM trigram language "
            "model with self-repositioning "
            "source dataset."
        )
    )

    parser.add_argument(
        "--data",
        nargs="*",
        default=None,
        help="Corpus files or glob patterns.",
    )

    parser.add_argument(
        "--order",
        type=int,
        default=3,
        help="N-gram order; 3 means trigram.",
    )

    parser.add_argument(
        "--min-count",
        type=int,
        default=1,
    )

    parser.add_argument(
        "--beta",
        type=float,
        default=0.3,
    )

    parser.add_argument(
        "--alpha",
        type=float,
        default=0.1,
    )

    parser.add_argument(
        "--max-diffusion-states",
        type=int,
        default=1500,
    )

    parser.add_argument(
        "--prompt",
        type=str,
        default=None,
    )

    parser.add_argument(
        "--length",
        type=int,
        default=40,
    )

    parser.add_argument(
        "--top-k",
        type=int,
        default=10,
    )

    parser.add_argument(
        "--base-temp",
        type=float,
        default=0.8,
    )

    parser.add_argument(
        "--amplitude",
        type=float,
        default=0.4,
    )

    parser.add_argument(
        "--omega",
