    )

    parser.add_argument(
        "--boost",
        type=str,
        default=None,
        help="word:weight,word:weight,...",
    )

    parser.add_argument(
        "--boost-strength",
        type=float,
        default=1.0,
    )

    args = parser.parse_args()

    tokens = load_corpus(
        paths=args.data
    )

    if not tokens:
        raise RuntimeError(
            "Corpus contains no usable tokens."
        )

    print(
        f"[info] loaded {len(tokens)} tokens",
        file=sys.stderr,
    )

    model = HECMModel(
        tokens,
        order=args.order,
        min_count=args.min_count,
        beta=args.beta,
        alpha=args.alpha,
        max_diffusion_states=(
            args.max_diffusion_states
        ),
        boost_strength=(
            args.boost_strength
            if args.boost
            else 0.0
        ),
    )

    if args.boost:
        model.payload = parse_payload(
            args.boost,
            model.word_to_idx,
        )

        model._rebuild_payload_scores()

    print_model_diagnostics(
        model
    )

    _self_test(model)

    def generate(prompt):
        return model.generate(
            prompt,
            max_new_tokens=args.length,
            top_k=args.top_k,
            base_temp=args.base_temp,
            amplitude=args.amplitude,
            omega=args.omega,
            phase=args.phase,
            seed=args.seed,
            boost_strength=(
                args.boost_strength
                if args.boost
                else 0.0
            ),
        )

    if args.prompt is not None:
        print(
            generate(args.prompt)
        )
        return

    print(
        "[info] interactive mode -- "
        "type quit or exit to stop",
        file=sys.stderr,
    )

    while True:
        try:
            prompt = input(
                "prompt> "
