        if not prompt.strip():
            continue

        print(
            generate(prompt)
        )

        print(
            f"[info] N={model.last_quanta_crossed}",
            file=sys.stderr,
        )


# ============================================================================
# SELF-SOURCE DATASET
# ============================================================================

_SOURCE_MARKER = (
    "# >>> SELF_SOURCE_DATASET <<<"
)


def _read_own_source():
    """
    Read this exact Python file as the dataset.
    """
    with open(
        __file__,
        "r",
        encoding="utf-8",
    ) as f:
        return f.read()


def _extract_source_dataset(
    source,
):
    """
    Extract the executable source represented
    inside the self-source dataset.

    Lines beginning with the dataset marker
    are ignored.

    This function deliberately never executes
    source obtained from a failed candidate.
    """

    lines = source.splitlines()

    payload = []

    active = False

    for line in lines:
        if line.strip() == _SOURCE_MARKER:
            active = True
            continue

        if not active:
            continue

        if line.startswith(
            "# SRC "
        ):
            encoded = line[
                len("# SRC "):
            ]

            try:
                number, text = (
                    encoded.split(
                        "|",
                        1,
                    )
                )

                payload.append(
                    (
                        int(number),
                        text,
                    )
                )

            except (
                ValueError,
                IndexError,
            ):
                continue

    return payload


# ============================================================================
# SOURCE LINE PROBABILITIES
# ============================================================================

def _first_character(
    line,
):
    if not line:
        return ""

    return line[0]


def _character_probabilities(
    records,
):
    counts = Counter(
        _first_character(line)
        for _, line in records
    )

    total = sum(
        counts.values()
    )

    if total == 0:
        return {}

    return {
        ch: count / total
        for ch, count in counts.items()
    }


# ============================================================================
# CANDIDATE GENERATION
# ============================================================================

def _weighted_character_order(
    probabilities,
    rng,
):
    """
    Produce a stochastic first-character ordering.

    Higher-probability characters are sampled
    earlier, but the process is deterministic
    when supplied the same RNG seed.
    """

    characters = list(
        probabilities.keys()
    )

    if not characters:
        return []

    remaining = characters[:]
    result = []

    while remaining:
        weights = np.asarray(
            [
                probabilities[ch]
                for ch in remaining
            ],
            dtype=np.float64,
        )

        total = weights.sum()

        if (
            not np.isfinite(total)
            or total <= 0.0
        ):
            index = 0

        else:
            weights /= total

            index = int(
                rng.choice(
                    len(remaining),
                    p=weights,
                )
            )

        result.append(
            remaining.pop(index)
        )

    return result


def _candidate_records(
    records,
    rng,
    attempt,
):
    """
    Reposition source records using the
    first-character probability model.

    Within a first-character bucket, original
    source order is retained. This is critical:
    it means multiline Python constructs are
    not arbitrarily scrambled.

    A small stochastic amount of character-bucket
    exploration is allowed between trials.
    """

    probabilities = (
        _character_probabilities(
            records
        )
    )

    chars = _weighted_character_order(
        probabilities,
        rng,
    )

    buckets = {
        ch: []
        for ch in chars
    }

    for record in records:
        buckets[
            _first_character(
                record[1]
            )
        ].append(record)

    candidate = []

    for ch in chars:
        bucket = buckets[ch]

        if attempt > 0:
            # Preserve semantic ordering inside
            # each bucket. Only the bucket order
            # is explored.
            bucket = list(bucket)

        candidate.extend(bucket)

    return candidate


# ============================================================================
# COMPILE TEST
# ============================================================================

def _compile_candidate(
    records,
):
    """
    Test a candidate without executing it.

    This is the important protection against the
    IndentationError seen in the previous version.
    """

    source = "\n".join(
        line
        for _, line in records
    )

    try:
        code = compile(
            source,
            __file__,
            "exec",
        )

    except (
        SyntaxError,
        IndentationError,
        ValueError,
        TypeError,
    ) as exc:
        return (
            False,
            None,
            str(exc),
        )

    return (
        True,
        code,
        None,
    )


# ============================================================================
# SEMANTIC RECONSTRUCTION
# ============================================================================

def _restore_semantic_order(
    records,
):
    """
    Restore the original execution order using
    the source line number attached to each record.
    """

    return sorted(
        records,
        key=lambda item: item[0],
    )


# ============================================================================
# REPOSITIONING ENGINE
# ============================================================================

def _reposition_source(
    records,
    trials=32,
    seed=12345,
):
    """
    Try multiple probability-guided source
    arrangements.

    The candidate is NEVER executed merely
    because it was generated.

    A compile test must pass first.

    The final executable candidate is always
    restored into semantic order.
    """

    if not records:
        raise RuntimeError(
            "No self-source records found."
        )

    rng = np.random.default_rng(
        seed
    )

    probabilities = (
        _character_probabilities(
            records
        )
    )

    print(
        "[source] first-character distribution:",
        file=sys.stderr,
    )

    for ch, probability in sorted(
        probabilities.items(),
        key=lambda item: (
            item[0]
        ),
    ):
        display = (
            repr(ch)
            if ch
            else "EMPTY"
        )

        print(
            f"[source]   {display:>8} "
            f"{probability:.6f}",
            file=sys.stderr,
        )

    best_candidate = None

    for attempt in range(
        max(1, trials)
    ):
        candidate = _candidate_records(
            records,
            rng,
            attempt,
        )

        ok, code, error = (
            _compile_candidate(
                candidate
            )
        )

        print(
            f"[source] trial "
            f"{attempt + 1}/{max(1, trials)} "
            f"compile={'PASS' if ok else 'FAIL'}",
            file=sys.stderr,
        )

        if ok:
            best_candidate = (
                candidate,
                code,
            )
            break

    if best_candidate is None:
        print(
            "[source] probability-guided "
            "arrangements did not compile.",
            file=sys.stderr,
        )

        print(
            "[source] falling back to "
            "line-number reconstruction.",
            file=sys.stderr,
        )

    restored = (
        _restore_semantic_order(
            records
        )
    )

    ok, code, error = (
        _compile_candidate(
            restored
        )
    )

    if not ok:
        raise RuntimeError(
            "SELF-RECONSTRUCTION FAILED:\n"
            f"{error}"
        )

    print(
        "[source] semantic reconstruction "
        "compile check: PASS",
        file=sys.stderr,
    )

    return restored, code


# ============================================================================
# BOOTSTRAP
# ============================================================================

def _bootstrap():
    """
    Read own source, interpret it as a dataset,
    reposition candidate records, compile-test,
    reconstruct semantic order, and execute.
    """

    own_source = _read_own_source()

    records = _extract_source_dataset(
        own_source
    )

    if not records:
        print(
            "[source] no embedded source dataset "
            "was found.",
            file=sys.stderr,
        )

        print(
            "[source] running directly.",
            file=sys.stderr,
        )

        main()
        return

    restored, code = (
        _reposition_source(
            records,
            trials=32,
            seed=12345,
        )
    )

    namespace = {
        "__name__": "__main__",
        "__file__": __file__,
        "__builtins__": builtins,
    }

    exec(
        code,
        namespace,
        namespace,
    )


