#!/usr/bin/env python3 
""" 
Reduced-valve optical Q compiler/interpreter. 

Features 
-------- 
- Time-multiplexed binary optical operations 
- 32-bit arithmetic 
- AND32 / OR32 / XOR32 / NOT32 
- ADD32 
- SHR / SHL / ROTR 
- Lists 
- List indexing 
- List assignment 
- Functions 
- Return 
- If / else 
- While 
- For / range 
- SHA-256 capable Q programs 
- Optical operation tracing 
- Optical statistics 
- Simulator backend 

Example: 

    python reduced_valve_optical_stats.py \ 
        --program sha256.q \ 
        --input abc 

Self-test: 

    python reduced_valve_optical_stats.py \ 
        --program sha256.q \ 
        --self-test 

Trace: 

    python reduced_valve_optical_stats.py \ 
        --program sha256.q \ 
        --input abc \ 
        --trace \ 
        --trace-limit 100 

Stats: 

    python reduced_valve_optical_stats.py \ 
        --program sha256.q \ 
        --input abc \ 
        --stats 
""" 

from __future__ import annotations 

import argparse 
import ast 
import hashlib 
import sys 

from dataclasses import dataclass, field 
from typing import Any, Iterable, Optional 


# ============================================================ 
# CONSTANTS 
# ============================================================ 

MAX_LOOP_ITERATIONS = 1_000_000 
MASK32 = 0xFFFFFFFF 


# ============================================================ 
# VALIDATION 
# ============================================================ 

def _nonnegative_int( 
    name: str, 
    value: Any, 
) -> int: 

    if isinstance(value, bool): 
        raise ValueError( 
            f"{name} expects an integer" 
        ) 

    if not isinstance(value, int): 
        raise ValueError( 
            f"{name} expects an integer, " 
            f"got {value!r}" 
        ) 

    if value < 0: 
        raise ValueError( 
            f"{name} expects a nonnegative " 
            f"integer, got {value!r}" 
        ) 

    return value 


def _bit( 
    name: str, 
    value: Any, 
) -> int: 

    value = _nonnegative_int( 
        name, 
        value, 
    ) 

    if value not in (0, 1): 
        raise ValueError( 
            f"{name} expects 0 or 1, " 
            f"got {value!r}" 
        ) 

    return value 


def _u32( 
    value: int, 
) -> int: 

    return int(value) & MASK32 


# ============================================================ 
# BIT CONVERSION 
# ============================================================ 

def int_to_bits( 
    value: int, 
    width: Optional[int] = None, 
) -> list[int]: 

    value = int(value) 

    if width is None: 
        width = 32 

    if width < 1: 
        raise ValueError("width must be positive") 

    value &= (1 << width) - 1 

    return [ 
        (value >> i) & 1 
        for i in range(width) 
    ] 

def bits_to_int( 
    bits: Iterable[int], 
) -> int: 

    result = 0 

    for i, value in enumerate(bits): 

        result |= ( 
            _bit( 
                "bit", 
                int(value), 
            ) 
            << i 
        ) 

    return result 


# ============================================================ 
# OPTICAL SIMULATOR 
# ============================================================ 

class SimulatedOptics: 
    """ 
    Deterministic optical hardware simulator. 

    The two-valve concept is represented by reusable bit 
    operations rather than unary hole-count arithmetic. 
    """ 

    def and_bit( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        return ( 
            _bit("a", a) 
            & 
            _bit("b", b) 
        ) 

    def sum_bits( 
        self, 
        values: Iterable[int], 
    ) -> int: 

        return sum( 
            _bit( 
                "value", 
                int(v), 
            ) 
            for v in values 
        ) 

    def sample( 
        self, 
        value: int, 
    ) -> int: 

        return int(value) 


# ============================================================ 
# OPTICAL BACKEND 
# ============================================================ 

class OpticalBackend: 

    def __init__( 
        self, 
        driver: Optional[Any] = None, 
        valve_count: int = 2, 
    ): 

        self.driver = ( 
            driver 
            or SimulatedOptics() 
        ) 

        self.valve_count = valve_count 

    def and_bit( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        return _bit( 
            "AND result", 
            self.driver.and_bit( 
                a, 
                b, 
            ), 
        ) 

    def sum_bits( 
        self, 
        values: Iterable[int], 
    ) -> int: 

        return int( 
            self.driver.sum_bits(values) 
        ) 

    def sample( 
        self, 
        value: int, 
    ) -> int: 

        return int( 
            self.driver.sample(value) 
        ) 


# ============================================================ 
# OPTICAL TRACE 
# ============================================================ 

@dataclass 
class OpticalTrace: 

    events: list[ 
        tuple[ 
            str, 
            tuple[Any, ...], 
            Any, 
        ] 
    ] = field( 
        default_factory=list 
    ) 

    def record( 
        self, 
        operation: str, 
        inputs: tuple[Any, ...], 
        result: Any, 
    ) -> Any: 

        self.events.append( 
            ( 
                operation, 
                inputs, 
                result, 
            ) 
        ) 

        return result 

    def print( 
        self, 
        limit: Optional[int] = None, 
    ) -> None: 

        events = self.events 

        if limit is not None: 
            events = events[:limit] 

        for index, ( 
            operation, 
            inputs, 
            result, 
        ) in enumerate( 
            events, 
            1, 
        ): 

            print( 
                f"[{index}] " 
                f"{operation}{inputs} " 
                f"-> {result}" 
            ) 

        if ( 
            limit is not None 
            and len(self.events) > limit 
        ): 

            print( 
                f"... " 
                f"{len(self.events) - limit} " 
                f"more events" 
            ) 


# ============================================================ 
# STATISTICS 
# ============================================================ 

@dataclass 
class OpticalStats: 

    counts: dict[str, int] = field( 
        default_factory=dict 
    ) 

    total_events: int = 0 

    def record( 
        self, 
        operation: str, 
    ) -> None: 

        self.total_events += 1 

        self.counts[operation] = ( 
            self.counts.get( 
                operation, 
                0, 
            ) 
            + 1 
        ) 

    def print(self) -> None: 

        print() 
        print("=" * 60) 
        print("OPTICAL STATISTICS") 
        print("=" * 60) 

        print( 
            f"Total optical events: " 
            f"{self.total_events}" 
        ) 

        print() 

        for name, count in sorted( 
            self.counts.items(), 
            key=lambda item: ( 
                -item[1], 
                item[0], 
            ), 
        ): 

            print( 
                f"{name:25s} " 
                f"{count:12d}" 
            ) 

        print("=" * 60) 


# ============================================================ 
# REDUCED VALVE MACHINE 
# ============================================================ 

class ReducedValveMachine: 

    def __init__( 
        self, 
        backend: Optional[ 
            OpticalBackend 
        ] = None, 
        width: int = 32, 
        trace: Optional[ 
            OpticalTrace 
        ] = None, 
        stats: Optional[ 
            OpticalStats 
        ] = None, 
    ): 

        self.backend = ( 
            backend 
            or OpticalBackend() 
        ) 

        self.width = width 

        self.trace = ( 
            trace 
            or OpticalTrace() 
        ) 

        self.stats = ( 
            stats 
            or OpticalStats() 
        ) 

    # -------------------------------------------------------- 
    # RECORD 
    # -------------------------------------------------------- 

    def _record( 
        self, 
        operation: str, 
        inputs: tuple[Any, ...], 
        result: Any, 
    ) -> Any: 

        self.stats.record( 
            operation 
        ) 

        return self.trace.record( 
            operation, 
            inputs, 
            result, 
        ) 

    # -------------------------------------------------------- 
    # BIT OPERATIONS 
    # -------------------------------------------------------- 

    def and_bit( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        result = self.backend.and_bit( 
            _bit("a", a), 
            _bit("b", b), 
        ) 

        return self._record( 
            "AND", 
            (a, b), 
            result, 
        ) 

    def or_bit( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        total = self.backend.sum_bits( 
            [ 
                _bit("a", a), 
                _bit("b", b), 
            ] 
        ) 

        result = int(total > 0) 

        return self._record( 
            "OR", 
            (a, b), 
            result, 
        ) 

    def xor_bit( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        total = self.backend.sum_bits( 
            [ 
                _bit("a", a), 
                _bit("b", b), 
            ] 
        ) 

        result = total & 1 

        return self._record( 
            "XOR", 
            (a, b), 
            result, 
        ) 

    def not_bit( 
        self, 
        a: int, 
    ) -> int: 

        result = 1 - _bit( 
            "NOT", 
            a, 
        ) 

        return self._record( 
            "NOT", 
            (a,), 
            result, 
        ) 

    # -------------------------------------------------------- 
    # SERIAL BINARY 
    # -------------------------------------------------------- 

    def _serial_binary( 
        self, 
        a: int, 
        b: int, 
        operation: str, 
        width: Optional[int] = None, 
    ) -> int: 

        width = width or self.width 

        mask = (1 << width) - 1 

        a = int(a) & mask 
        b = int(b) & mask 

        result = 0 

        for slot in range(width): 

            ai = (a >> slot) & 1 
            bi = (b >> slot) & 1 

            if operation == "AND": 

                value = self.backend.and_bit( 
                    ai, 
                    bi, 
                ) 

            elif operation == "OR": 

                value = int( 
                    self.backend.sum_bits( 
                        [ai, bi] 
                    ) > 0 
                ) 

            elif operation == "XOR": 

                value = ( 
                    self.backend.sum_bits( 
                        [ai, bi] 
                    ) & 1 
                ) 

            else: 

                raise ValueError( 
                    f"unknown operation {operation}" 
                ) 

            result |= ( 
                int(value) & 1 
            ) << slot 

            self._record( 
                f"{operation}[t={slot}]", 
                (ai, bi), 
                value, 
            ) 

        return result & mask 

    # -------------------------------------------------------- 
    # 32 BIT LOGIC 
    # -------------------------------------------------------- 

    def and32( 
        self, 
        *values: int, 
    ) -> int: 

        if not values: 
            return MASK32 

        result = _u32( 
            values[0] 
        ) 

        for value in values[1:]: 

            result = ( 
                self._serial_binary( 
                    result, 
                    _u32(value), 
                    "AND", 
                    32, 
                ) 
                & MASK32 
            ) 

        return self._record( 
            "AND32", 
            tuple(values), 
            result, 
        ) 

    def or32( 
        self, 
        *values: int, 
    ) -> int: 

        if not values: 
            return 0 

        result = _u32( 
            values[0] 
        ) 

        for value in values[1:]: 

            result = ( 
                self._serial_binary( 
                    result, 
                    _u32(value), 
                    "OR", 
                    32, 
                ) 
                & MASK32 
            ) 

        return self._record( 
            "OR32", 
            tuple(values), 
            result, 
        ) 

    def xor32( 
        self, 
        *values: int, 
    ) -> int: 

        if not values: 
            return 0 

        result = _u32( 
            values[0] 
        ) 

        for value in values[1:]: 

            result = ( 
                self._serial_binary( 
                    result, 
                    _u32(value), 
                    "XOR", 
                    32, 
                ) 
                & MASK32 
            ) 

        return self._record( 
            "XOR32", 
            tuple(values), 
            result, 
        ) 

    def not32( 
        self, 
        value: int, 
    ) -> int: 

        result = ( 
            ~_u32(value) 
        ) & MASK32 

        return self._record( 
            "NOT32", 
            (value,), 
            result, 
        ) 

    # -------------------------------------------------------- 
    # ADDITION 
    # -------------------------------------------------------- 

    def _add_raw( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        carry = 0 
        result = 0 

        for slot in range(32): 

            ai = ( 
                a >> slot 
            ) & 1 

            bi = ( 
                b >> slot 
            ) & 1 

            total = ( 
                self.backend.sum_bits( 
                    [ 
                        ai, 
                        bi, 
                        carry, 
                    ] 
                ) 
            ) 

            output_bit = ( 
                total & 1 
            ) 

            carry = int( 
                total >= 2 
            ) 

            result |= ( 
                output_bit 
                << slot 
            ) 

            self._record( 
                f"ADD32[t={slot}]", 
                ( 
                    ai, 
                    bi, 
                    carry, 
                ), 
                output_bit, 
            ) 

        return result & MASK32 

    def _add_raw( 
        self, 
        a: int, 
        b: int, 
        ) -> int: 

        a &= MASK32 
        b &= MASK32 

        result = 0 
        carry = 0 

        for slot in range(32): 

            ai = (a >> slot) & 1 
            bi = (b >> slot) & 1 

            total = self.backend.sum_bits( 
                [ 
                    ai, 
                    bi, 
                    carry, 
                ] 
            ) 

            output_bit = total & 1 

            next_carry = int( 
                total >= 2 
            ) 

            result |= ( 
                output_bit << slot 
            ) 

            self._record( 
                f"ADD32[t={slot}]", 
                ( 
                    ai, 
                    bi, 
                    carry, 
                ), 
                output_bit, 
            ) 

            carry = next_carry 

        return result & MASK32 


    def add32( 
        self, 
        *values: int, 
    ) -> int: 

        result = 0 

        for value in values: 

            result = self._add_raw( 
                result, 
                int(value) & MASK32, 
            ) 

        result &= MASK32 

        return self._record( 
            "ADD32", 
            tuple(values), 
            result, 
        ) 

    # -------------------------------------------------------- 
    # SUBTRACT 
    # -------------------------------------------------------- 

    def subtract( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        result = ( 
            _u32(a) 
            - 
            _u32(b) 
        ) & MASK32 

        return self._record( 
            "SUB32", 
            (a, b), 
            result, 
        ) 

    # -------------------------------------------------------- 
    # SHIFTS 
    # -------------------------------------------------------- 

    def shr( 
        self, 
        value: int, 
        amount: int, 
    ) -> int: 

        value = _u32(value) 
        amount = int(amount) 

        if amount >= 32: 
            result = 0 
        else: 
            result = ( 
                value >> amount 
            ) 

        return self._record( 
            "SHR", 
            (value, amount), 
            result, 
        ) 

    def shl( 
        self, 
        value: int, 
        amount: int, 
    ) -> int: 

        result = ( 
            _u32(value) 
            << int(amount) 
        ) & MASK32 

        return self._record( 
            "SHL", 
            (value, amount), 
            result, 
        ) 

    def rotr( 
        self, 
        value: int, 
        amount: int, 
    ) -> int: 

        value = _u32(value) 

        amount %= 32 

        if amount == 0: 

            result = value 

        else: 

            result = ( 
                (value >> amount) 
                | 
                ( 
                    value 
                    << (32 - amount) 
                ) 
            ) & MASK32 

        return self._record( 
            "ROTR", 
            (value, amount), 
            result, 
        ) 

    # -------------------------------------------------------- 
    # MULTIPLY 
    # -------------------------------------------------------- 

    def multiply( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        result = 0 
        row = _u32(a) 

        b = _u32(b) 

        shift = 0 

        while ( 
            b >> shift 
        ): 

            if ( 
                (b >> shift) & 1 
            ): 

                result = self.add32( 
                    result, 
                    row, 
                ) 

            row = ( 
                row << 1 
            ) & MASK32 

            shift += 1 

        return self._record( 
            "MUL32", 
            (a, b), 
            result, 
        ) 

    # -------------------------------------------------------- 
    # COMPARISON 
    # -------------------------------------------------------- 

    def compare( 
        self, 
        a: int, 
        b: int, 
    ) -> int: 

        if a == b: 
            result = 0 

        elif a > b: 
            result = 1 

        else: 
            result = -1 

        return self._record( 
            "CMP", 
            (a, b), 
            result, 
        ) 

    def eq(self, a, b): 
        return int( 
            self.compare(a, b) == 0 
        ) 

    def ne(self, a, b): 
        return int( 
            self.compare(a, b) != 0 
        ) 

    def lt(self, a, b): 
        return int( 
            self.compare(a, b) < 0 
        ) 

    def le(self, a, b): 
        return int( 
            self.compare(a, b) <= 0 
        ) 

    def gt(self, a, b): 
        return int( 
            self.compare(a, b) > 0 
        ) 

    def ge(self, a, b): 
        return int( 
            self.compare(a, b) >= 0 
        ) 


# ============================================================ 
# Q RUNTIME 
# ============================================================ 

class QRuntime: 

    def __init__( 
        self, 
        machine: ReducedValveMachine, 
        data: bytes, 
    ): 

        self.machine = machine 
        self.data = bytes(data) 

    def byte( 
        self, 
        index: int, 
    ) -> int: 

        index = int(index) 

        if ( 
            index < 0 
            or index >= len(self.data) 
        ): 

            return 0 

        return self.data[index] 

    def length(self) -> int: 

        return len(self.data) 

    def padded( 
        self, 
    ) -> bytes: 

        message = bytearray( 
            self.data 
        ) 

        bit_length = ( 
            len(message) 
            * 8 
        ) 

        message.append( 
            0x80 
        ) 

        while ( 
            len(message) % 64 
            != 56 
        ): 

            message.append( 
                0 
            ) 

        message.extend( 
            bit_length.to_bytes( 
                8, 
                "big", 
            ) 
        ) 

        return bytes(message) 

    def word( 
        self, 
        index: int, 
    ) -> int: 

        data = self.padded() 

        offset = ( 
            int(index) 
            * 4 
        ) 

        if ( 
            offset + 4 
            > len(data) 
        ): 

            return 0 

        return int.from_bytes( 
            data[ 
                offset: 
                offset + 4 
            ], 
            "big", 
        ) 

    def word_count( 
        self, 
    ) -> int: 

        return ( 
            len(self.padded()) 
            // 4 
        ) 


# ============================================================ 
