@dataclass 
class QFunction: 

    node: ast.FunctionDef 


# ============================================================ 
# EXPRESSION EVALUATOR 
# ============================================================ 

class ExpressionEvaluator( 
    ast.NodeVisitor 
): 

    def __init__( 
        self, 
        machine: ReducedValveMachine, 
        variables: dict[str, Any], 
        functions: dict[str, QFunction], 
        runtime: QRuntime, 
        executor: "StatementExecutor", 
    ): 

        self.machine = machine 
        self.variables = variables 
        self.functions = functions 
        self.runtime = runtime 
        self.executor = executor 

    # -------------------------------------------------------- 
    # CONSTANT 
    # -------------------------------------------------------- 

    def visit_Constant( 
        self, 
        node: ast.Constant, 
    ): 

        if isinstance( 
            node.value, 
            ( 
                int, 
                str, 
                bytes, 
            ), 
        ): 

            return node.value 

        if node.value is None: 

            return None 

        raise SyntaxError( 
            f"unsupported constant: " 
            f"{node.value!r}" 
        ) 

    # -------------------------------------------------------- 
    # VARIABLE 
    # -------------------------------------------------------- 

    def visit_Name( 
        self, 
        node: ast.Name, 
    ): 

        if ( 
            node.id 
            not in self.variables 
        ): 

            raise NameError( 
                f"undefined Q variable: " 
                f"{node.id}" 
            ) 

        return self.variables[ 
            node.id 
        ] 

    # -------------------------------------------------------- 
    # LIST 
    # 
    # THIS FIXES THE ERROR IN YOUR TRACEBACK. 
    # -------------------------------------------------------- 

    def visit_List( 
        self, 
        node: ast.List, 
    ): 

        return [ 
            self.visit(element) 
            for element in node.elts 
        ] 

    # -------------------------------------------------------- 
    # TUPLE 
    # -------------------------------------------------------- 

    def visit_Tuple( 
        self, 
        node: ast.Tuple, 
    ): 

        return tuple( 
            self.visit(element) 
            for element in node.elts 
        ) 

    # -------------------------------------------------------- 
    # INDEXING 
    # 
    # Supports: 
    # 
    #   K[j] 
    #   w[j] 
    #   state[0] 
    # -------------------------------------------------------- 

    def visit_Subscript( 
        self, 
        node: ast.Subscript, 
    ): 

        container = self.visit( 
            node.value 
        ) 

        index = self.visit( 
            node.slice 
        ) 

        return container[index] 

    # Python 3.11 compatibility. 

    def visit_Index( 
        self, 
        node: ast.Index, 
    ): 

        return self.visit( 
            node.value 
        ) 

    # -------------------------------------------------------- 
    # LIST REPETITION 
    # 
    # Supports: 
    # 
    #   [0] * 64 
    # -------------------------------------------------------- 

    # -------------------------------------------------------- 
    # UNARY 
    # -------------------------------------------------------- 

    def visit_UnaryOp( 
        self, 
        node: ast.UnaryOp, 
    ): 

        value = self.visit( 
            node.operand 
        ) 

        if isinstance( 
            node.op, 
            ast.Invert, 
        ): 

            return self.machine.not32( 
                value 
            ) 

        if isinstance( 
            node.op, 
            ast.USub, 
        ): 

            return ( 
                -int(value) 
            ) & MASK32 

        if isinstance( 
            node.op, 
            ast.UAdd, 
        ): 

            return int(value) 

        if isinstance( 
            node.op, 
            ast.Not, 
        ): 

            return int( 
                not value 
            ) 

        raise SyntaxError( 
            "unsupported unary operation" 
        ) 

    # -------------------------------------------------------- 
    # BINARY 
    # -------------------------------------------------------- 

    def visit_BinOp( 
        self, 
        node: ast.BinOp, 
    ): 

        left = self.visit( 
            node.left 
        ) 

        right = self.visit( 
            node.right 
        ) 

        # List repetition. 

        if isinstance( 
            node.op, 
            ast.Mult, 
        ): 

            if isinstance( 
                left, 
                list, 
            ) and isinstance( 
                right, 
                int, 
            ): 

                return left * right 

            if isinstance( 
                right, 
                list, 
            ) and isinstance( 
                left, 
                int, 
            ): 

                return right * left 

        # String/list concatenation. 

        if isinstance( 
            node.op, 
            ast.Add, 
        ) and ( 
            isinstance(left, list) 
            or isinstance(right, list) 
            or isinstance(left, str) 
            or isinstance(right, str) 
        ): 

            return left + right 

        if isinstance( 
            node.op, 
            ast.BitAnd, 
        ): 

            return self.machine.and32( 
                left, 
                right, 
            ) 

        if isinstance( 
            node.op, 
            ast.BitOr, 
        ): 

            return self.machine.or32( 
                left, 
                right, 
            ) 

        if isinstance( 
            node.op, 
            ast.BitXor, 
        ): 

            return self.machine.xor32( 
                left, 
                right, 
            ) 

        if isinstance( 
            node.op, 
            ast.Add, 
        ): 

            return self.machine.add32( 
                left, 
                right, 
            ) 

        if isinstance( 
            node.op, 
            ast.Sub, 
        ): 

            return self.machine.subtract( 
                left, 
                right, 
            ) 

        if isinstance( 
            node.op, 
            ast.LShift, 
        ): 

            return self.machine.shl( 
                left, 
                right, 
            ) 

        if isinstance( 
            node.op, 
            ast.RShift, 
        ): 

            return self.machine.shr( 
                left, 
                right, 
            ) 

        if isinstance( 
            node.op, 
            ast.Mod, 
        ): 

            return left % right 

        if isinstance( 
            node.op, 
            ast.Mult, 
        ): 

            return left * right 

        raise SyntaxError( 
            "unsupported binary operator" 
        ) 

    # -------------------------------------------------------- 
    # BOOLEAN 
    # -------------------------------------------------------- 

    def visit_BoolOp( 
        self, 
        node: ast.BoolOp, 
    ): 

        values = [ 
            self.visit(v) 
            for v in node.values 
        ] 

        if isinstance( 
            node.op, 
            ast.And, 
        ): 

            return int( 
                all(values) 
            ) 

        if isinstance( 
            node.op, 
            ast.Or, 
        ): 

            return int( 
                any(values) 
            ) 

        raise SyntaxError( 
            "unsupported boolean operator" 
        ) 

    # -------------------------------------------------------- 
    # COMPARISON 
    # -------------------------------------------------------- 

    def visit_Compare( 
        self, 
        node: ast.Compare, 
    ): 

        left = self.visit( 
            node.left 
        ) 

        result = True 

        for op, comparator in zip( 
            node.ops, 
            node.comparators, 
        ): 

            right = self.visit( 
                comparator 
            ) 

            if isinstance( 
                op, 
                ast.Eq, 
            ): 

                current = ( 
                    left == right 
                ) 

            elif isinstance( 
                op, 
                ast.NotEq, 
            ): 

                current = ( 
                    left != right 
                ) 

            elif isinstance( 
                op, 
                ast.Lt, 
            ): 

                current = ( 
                    left < right 
                ) 

            elif isinstance( 
                op, 
                ast.LtE, 
            ): 

                current = ( 
                    left <= right 
                ) 

            elif isinstance( 
                op, 
                ast.Gt, 
            ): 

                current = ( 
                    left > right 
                ) 

            elif isinstance( 
                op, 
                ast.GtE, 
            ): 

                current = ( 
                    left >= right 
                ) 

            else: 

                raise SyntaxError( 
                    "unsupported comparison" 
                ) 

            result = ( 
                result 
                and current 
            ) 

            left = right 

        return int(result) 

    # -------------------------------------------------------- 
    # CALL 
    # -------------------------------------------------------- 

    def visit_Call( 
        self, 
        node: ast.Call, 
    ): 

        if not isinstance( 
            node.func, 
            ast.Name, 
        ): 

            raise SyntaxError( 
                "Q only permits " 
                "named function calls" 
            ) 

        name = node.func.id 

        args = [ 
            self.visit(arg) 
            for arg in node.args 
        ] 

        # Optical primitives. 

        if name == "ADD32": 

            return self.machine.add32( 
                *args 
            ) 

        if name == "AND32": 

            return self.machine.and32( 
                *args 
            ) 

        if name == "OR32": 

            return self.machine.or32( 
                *args 
            ) 

        if name == "XOR32": 

            return self.machine.xor32( 
                *args 
            ) 

        if name == "NOT32": 

            return self.machine.not32( 
                args[0] 
            ) 

        if name == "ROTR": 

            return self.machine.rotr( 
                args[0], 
                args[1], 
            ) 

        if name == "SHR": 

            return self.machine.shr( 
                args[0], 
                args[1], 
            ) 

        if name == "SHL": 

            return self.machine.shl( 
                args[0], 
                args[1], 
            ) 

        # Runtime input. 

        if name == "BYTE": 

            return self.runtime.byte( 
                args[0] 
            ) 

        if name == "INPUT_LENGTH": 

            return self.runtime.length() 

        if name == "INPUT_WORD": 

            return self.runtime.word( 
                args[0] 
            ) 

        if name == "WORD_COUNT": 

            return self.runtime.word_count() 

        # Helpers. 

        if name == "len": 

            return len(args[0]) 

        if name == "range": 

            return range(*args) 

        if name == "int": 

            return int(args[0]) 

        if name == "U32": 

            return _u32( 
                args[0] 
            ) 

        # User function. 

        if name in self.functions: 

            return self.executor.call_function( 
                self.functions[name], 
                args, 
            ) 

        raise NameError( 
            f"unknown Q function: " 
            f"{name}" 
        ) 

    # -------------------------------------------------------- 
    # OTHERWISE 
    # -------------------------------------------------------- 

    def generic_visit( 
        self, 
        node, 
    ): 

        raise SyntaxError( 
            f"unsupported syntax: " 
            f"{type(node).__name__}" 
        ) 


# ============================================================ 
# STATEMENT EXECUTOR 
# ============================================================ 

class StatementExecutor( 
    ast.NodeVisitor 
): 

    def __init__( 
        self, 
        machine: ReducedValveMachine, 
        variables: Optional[ 
            dict[str, Any] 
        ] = None, 
        runtime: Optional[ 
            QRuntime 
        ] = None, 
        functions: Optional[ 
            dict[str, QFunction] 
        ] = None, 
    ): 

        self.machine = machine 

        self.variables = ( 
            variables 
            if variables is not None 
            else {} 
        ) 

        self.runtime = runtime 

        self.functions = ( 
            functions 
            if functions is not None 
            else {} 
        ) 

    def evaluate( 
        self, 
        node, 
    ): 

        return ExpressionEvaluator( 
            self.machine, 
            self.variables, 
            self.functions, 
            self.runtime, 
            self, 
        ).visit(node) 

    # -------------------------------------------------------- 
    # MODULE 
    # -------------------------------------------------------- 

    def visit_Module( 
        self, 
        node: ast.Module, 
    ): 

        for statement in node.body: 

            self.visit( 
                statement 
            ) 

    # -------------------------------------------------------- 
    # FUNCTION 
    # -------------------------------------------------------- 

    def visit_FunctionDef( 
        self, 
        node: ast.FunctionDef, 
    ): 

        self.functions[ 
            node.name 
        ] = QFunction(node) 

    # -------------------------------------------------------- 
    # FUNCTION CALL 
    # -------------------------------------------------------- 

    def call_function( 
        self, 
        function: QFunction, 
        args: list[Any], 
    ): 

        node = function.node 

        expected = len( 
            node.args.args 
        ) 

        if len(args) != expected: 

            raise TypeError( 
                f"{node.name} expects " 
                f"{expected} arguments, " 
                f"got {len(args)}" 
            ) 

        local = dict( 
            self.variables 
        ) 

        for argument, value in zip( 
            node.args.args, 
            args, 
        ): 

            local[ 
                argument.arg 
            ] = value 

        child = StatementExecutor( 
            self.machine, 
            local, 
            self.runtime, 
            self.functions, 
        ) 

        try: 

            for statement in node.body: 

                child.visit( 
                    statement 
                ) 

        except QReturn as returned: 

            return returned.value 

        return None 

    # -------------------------------------------------------- 
    # RETURN 
    # -------------------------------------------------------- 

    def visit_Return( 
        self, 
        node: ast.Return, 
    ): 

        value = ( 
            self.evaluate( 
                node.value 
            ) 
            if node.value is not None 
            else None 
        ) 

        raise QReturn( 
            value 
        ) 

    # -------------------------------------------------------- 
    # ASSIGNMENT 
    # -------------------------------------------------------- 

    def visit_Assign( 
        self, 
        node: ast.Assign, 
    ): 

        value = self.evaluate( 
            node.value 
        ) 

        for target in node.targets: 

            self.assign( 
                target, 
                value, 
            ) 

    # -------------------------------------------------------- 
    # ASSIGN TARGET 
    # -------------------------------------------------------- 

    def assign( 
        self, 
        target, 
        value, 
    ): 

        # x = value 

        if isinstance( 
            target, 
            ast.Name, 
        ): 

            self.variables[ 
                target.id 
            ] = value 

            return 

        # w[j] = value 

        if isinstance( 
            target, 
            ast.Subscript, 
        ): 

            container = self.evaluate( 
                target.value 
            ) 

            index = self.evaluate( 
                target.slice 
            ) 

            container[ 
                index 
            ] = value 

            return 

        raise SyntaxError( 
            "unsupported assignment target" 
        ) 

    # -------------------------------------------------------- 
    # AUGMENTED ASSIGNMENT 
    # -------------------------------------------------------- 

    def visit_AugAssign( 
        self, 
        node: ast.AugAssign, 
    ): 

        # Simple variable +=. 

        if isinstance( 
            node.target, 
            ast.Name, 
        ): 

            name = node.target.id 

            lhs = self.variables[ 
                name 
            ] 

            rhs = self.evaluate( 
                node.value 
            ) 

            if isinstance( 
                node.op, 
                ast.Add, 
            ): 

                value = ( 
                    self.machine.add32( 
                        lhs, 
                        rhs, 
                    ) 
                ) 

            elif isinstance( 
                node.op, 
                ast.Sub, 
            ): 

                value = ( 
                    self.machine.subtract( 
                        lhs, 
                        rhs, 
                    ) 
                ) 

            elif isinstance( 
                node.op, 
                ast.BitXor, 
            ): 

                value = ( 
                    self.machine.xor32( 
                        lhs, 
                        rhs, 
                    ) 
                ) 

            elif isinstance( 
                node.op, 
                ast.BitAnd, 
            ): 

                value = ( 
                    self.machine.and32( 
                        lhs, 
                        rhs, 
                    ) 
                ) 

            elif isinstance( 
                node.op, 
                ast.BitOr, 
            ): 

                value = ( 
                    self.machine.or32( 
                        lhs, 
                        rhs, 
                    ) 
                ) 

            else: 

                raise SyntaxError( 
                    "unsupported " 
                    "augmented operator" 
                ) 

            self.variables[ 
                name 
            ] = value 

            return 

        # w[j] += value 

        if isinstance( 
            node.target, 
            ast.Subscript, 
        ): 

            container = self.evaluate( 
                node.target.value 
            ) 

            index = self.evaluate( 
                node.target.slice 
            ) 

            lhs = container[index] 

            rhs = self.evaluate( 
                node.value 
            ) 

            if isinstance( 
                node.op, 
                ast.Add, 
            ): 

                container[index] = ( 
                    self.machine.add32( 
                        lhs, 
                        rhs, 
                    ) 
                ) 

                return 

            if isinstance( 
                node.op, 
                ast.BitXor, 
            ): 

                container[index] = ( 
                    self.machine.xor32( 
                        lhs, 
                        rhs, 
                    ) 
                ) 

                return 

            raise SyntaxError( 
                "unsupported indexed " 
                "augmented operator" 
            ) 

        raise SyntaxError( 
            "unsupported augmented " 
            "assignment" 
        ) 

    # -------------------------------------------------------- 
    # EXPRESSION STATEMENT 
    # -------------------------------------------------------- 

    def visit_Expr( 
        self, 
        node: ast.Expr, 
    ): 

        if isinstance( 
            node.value, 
            ast.Call, 
        ): 

            if ( 
                isinstance( 
                    node.value.func, 
                    ast.Name, 
                ) 
                and node.value.func.id 
                == "print" 
            ): 

                values = [ 
                    self.evaluate( 
                        arg 
                    ) 
                    for arg 
                    in node.value.args 
                ] 

                print( 
                    *values 
                ) 

                return 

            if ( 
                isinstance( 
                    node.value.func, 
                    ast.Name, 
                ) 
                and node.value.func.id 
                == "print_hex" 
            ): 

                value = self.evaluate( 
                    node.value.args[0] 
                ) 

                print( 
                    f"{_u32(value):08x}" 
                ) 

                return 

            if ( 
                isinstance( 
                    node.value.func, 
                    ast.Name, 
                ) 
                and node.value.func.id 
                == "print_digest" 
            ): 

                values = [ 
                    self.evaluate( 
                        arg 
                    ) 
                    for arg 
                    in node.value.args 
                ] 

                print( 
                    "".join( 
                        f"{_u32(value):08x}" 
                        for value 
                        in values 
                    ) 
                ) 

                return 

        self.evaluate( 
            node.value 
        ) 

    # -------------------------------------------------------- 
    # IF 
    # -------------------------------------------------------- 

    def visit_If( 
        self, 
        node: ast.If, 
    ): 

        if self.evaluate( 
            node.test 
        ): 

            for statement in node.body: 

                self.visit( 
                    statement 
                ) 

        else: 

            for statement in node.orelse: 

                self.visit( 
                    statement 
                ) 

    # -------------------------------------------------------- 
    # WHILE 
    # -------------------------------------------------------- 

    def visit_While( 
        self, 
        node: ast.While, 
    ): 

        iterations = 0 

        while self.evaluate( 
            node.test 
        ): 

            iterations += 1 

            if ( 
                iterations 
                > MAX_LOOP_ITERATIONS 
            ): 

                raise RuntimeError( 
                    "Q loop limit exceeded" 
                ) 

            try: 

                for statement in node.body: 

                    self.visit( 
                        statement 
                    ) 

            except QBreak: 

                break 

            except QContinue: 

                continue 

    # -------------------------------------------------------- 
    # FOR 
    # -------------------------------------------------------- 

    def visit_For( 
        self, 
        node: ast.For, 
    ): 

        if not isinstance( 
            node.target, 
            ast.Name, 
        ): 

            raise SyntaxError( 
                "Q for target must " 
                "be a variable" 
            ) 

        iterable = self.evaluate( 
            node.iter 
        ) 

        for value in iterable: 

            self.variables[ 
                node.target.id 
            ] = value 

            try: 

                for statement in node.body: 

                    self.visit( 
                        statement 
                    ) 

            except QBreak: 

                break 

            except QContinue: 

                continue 

    # -------------------------------------------------------- 
    # BREAK 
    # -------------------------------------------------------- 

    def visit_Break( 
        self, 
        node: ast.Break, 
    ): 

        raise QBreak() 

    # -------------------------------------------------------- 
    # CONTINUE 
    # -------------------------------------------------------- 

    def visit_Continue( 
        self, 
        node: ast.Continue, 
    ): 

        raise QContinue() 

    # -------------------------------------------------------- 
    # PASS 
    # -------------------------------------------------------- 

    def visit_Pass( 
        self, 
        node: ast.Pass, 
    ): 

        pass 

    # -------------------------------------------------------- 
    # UNSUPPORTED 
    # -------------------------------------------------------- 

    def generic_visit( 
        self, 
        node, 
    ): 

        raise SyntaxError( 
            f"unsupported Q statement: " 
            f"{type(node).__name__}" 
        ) 


# ============================================================ 
# Q VALIDATOR 
# ============================================================ 

FORBIDDEN_NODES = ( 
    ast.Import, 
    ast.ImportFrom, 
    ast.ClassDef, 
    ast.AsyncFunctionDef, 
    ast.AsyncFor, 
    ast.AsyncWith, 
    ast.With, 
    ast.Try, 
    ast.Raise, 
    ast.Delete, 
    ast.Global, 
    ast.Nonlocal, 
    ast.Lambda, 
    ast.Yield, 
    ast.YieldFrom, 
) 


BUILTIN_CALLS = { 
    "ADD32", 
    "AND32", 
    "OR32", 
    "XOR32", 
    "NOT32", 
    "ROTR", 
    "SHR", 
    "SHL", 
    "BYTE", 
    "INPUT_LENGTH", 
    "INPUT_WORD", 
    "WORD_COUNT", 
    "U32", 
    "len", 
    "range", 
    "int", 
    "print", 
    "print_hex", 
    "print_digest", 
} 


def validate_q( 
    tree: ast.AST, 
) -> None: 

    functions = { 
        node.name 
        for node in ast.walk(tree) 
        if isinstance( 
            node, 
            ast.FunctionDef, 
        ) 
    } 

    allowed_calls = ( 
        BUILTIN_CALLS 
        | functions 
    ) 

    for node in ast.walk(tree): 

        if isinstance( 
            node, 
            FORBIDDEN_NODES, 
        ): 

            raise SyntaxError( 
                "forbidden Q construct: " 
                f"{type(node).__name__}" 
            ) 

        if isinstance( 
            node, 
            ast.Call, 
        ): 

            if not isinstance( 
                node.func, 
                ast.Name, 
            ): 

                raise SyntaxError( 
                    "Q requires named " 
                    "function calls" 
                ) 

            if ( 
                node.func.id 
                not in allowed_calls 
            ): 

                raise SyntaxError( 
                    f"unknown Q function: " 
                    f"{node.func.id}" 
                ) 


# ============================================================ 
# Q RUNNER 
# ============================================================ 

def run_q( 
    source: str, 
    data: bytes, 
    trace: Optional[ 
        OpticalTrace 
    ] = None, 
    statistics: Optional[ 
        OpticalStats 
    ] = None, 
): 

    machine = ReducedValveMachine( 
        width=32, 
        trace=( 
            trace 
            or OpticalTrace() 
        ), 
        stats=( 
            statistics 
            or OpticalStats() 
        ), 
    ) 

    runtime = QRuntime( 
        machine, 
        data, 
    ) 

    variables = {} 

    tree = ast.parse( 
        source, 
        filename="<Q>", 
        mode="exec", 
    ) 

    validate_q( 
        tree 
    ) 

    executor = StatementExecutor( 
        machine, 
        variables, 
        runtime, 
    ) 

    executor.visit( 
        tree 
    ) 

    return ( 
        variables, 
        machine, 
    ) 


# ============================================================ 
# SHA-256 RESULT 
# ============================================================ 

def extract_sha256( 
    variables: dict[str, Any], 
) -> str: 

    names = ( 
        "h0", 
        "h1", 
        "h2", 
        "h3", 
        "h4", 
        "h5", 
        "h6", 
        "h7", 
    ) 

    missing = [ 
        name 
        for name in names 
        if name not in variables 
    ] 

    if missing: 

        raise RuntimeError( 
            "Q program did not produce " 
            "SHA-256 state variables: " 
            + ", ".join(missing) 
        ) 

    return "".join( 
        f"{_u32(variables[name]):08x}" 
        for name in names 
    ) 


# ============================================================ 
# SELF TEST 
# ============================================================ 
def primitive_self_test(): 

    machine = ReducedValveMachine() 

    tests = [ 
        (0x00000000, 0x00000000), 
        (0xFFFFFFFF, 0x00000000), 
        (0xFFFFFFFF, 0xFFFFFFFF), 
        (0x12345678, 0x87654321), 
        (0xAAAAAAAA, 0x55555555), 
        (0x80000000, 0x00000001), 
    ] 

    for a, b in tests: 

        got = machine.and32(a, b) 
        expected = ( 
            a & b 
        ) & MASK32 

        assert got == expected, ( 
            f"AND32 failed: " 
            f"{a:08x} & {b:08x} = " 
            f"{got:08x}, expected " 
            f"{expected:08x}" 
        ) 

        got = machine.or32(a, b) 
        expected = ( 
            a | b 
        ) & MASK32 

        assert got == expected, ( 
            f"OR32 failed: " 
            f"{a:08x} | {b:08x} = " 
            f"{got:08x}, expected " 
            f"{expected:08x}" 
        ) 

        got = machine.xor32(a, b) 
        expected = ( 
            a ^ b 
        ) & MASK32 

        assert got == expected, ( 
            f"XOR32 failed: " 
            f"{a:08x} ^ {b:08x} = " 
            f"{got:08x}, expected " 
            f"{expected:08x}" 
        ) 

        got = machine.add32(a, b) 
        expected = ( 
            a + b 
        ) & MASK32 

        assert got == expected, ( 
            f"ADD32 failed: " 
            f"{a:08x} + {b:08x} = " 
            f"{got:08x}, expected " 
            f"{expected:08x}" 
        ) 

        got = machine.not32(a) 
        expected = ( 
            ~a 
        ) & MASK32 

        assert got == expected, ( 
            f"NOT32 failed: " 
            f"~{a:08x} = " 
            f"{got:08x}, expected " 
            f"{expected:08x}" 
        ) 

    rotations = [ 
        (0x12345678, 0), 
        (0x12345678, 1), 
        (0x12345678, 2), 
        (0x12345678, 7), 
        (0x12345678, 13), 
        (0x12345678, 16), 
        (0x12345678, 31), 
        (0xFFFFFFFF, 17), 
    ] 

    for value, amount in rotations: 

        got = machine.rotr( 
            value, 
            amount, 
        ) 

        amount %= 32 

        expected = ( 
            value 
            if amount == 0 
            else ( 
                (value >> amount) 
                | 
                ( 
                    value 
                    << (32 - amount) 
                ) 
            ) 
        ) & MASK32 

        assert got == expected, ( 
            f"ROTR failed: " 
            f"ROTR({value:08x}, {amount}) = " 
            f"{got:08x}, expected " 
            f"{expected:08x}" 
        ) 

    print( 
        "OPTICAL PRIMITIVE SELF-TEST PASSED" 
    ) 

def self_test( 
    source: str, 
) -> None: 

    tests = [ 
        b"", 
        b"a", 
        b"abc", 
        b"hello", 
        b"hello world", 
        b"The quick brown fox jumps over the lazy dog", 
        b"The quick brown fox jumps over the lazy dog.", 
        b"a" * 55, 
        b"a" * 56, 
        b"a" * 57, 
        b"a" * 63, 
        b"a" * 64, 
        b"a" * 65, 
        b"a" * 127, 
        b"a" * 128, 
        b"a" * 129, 
        b"a" * 1000, 
    ] 

    for data in tests: 

        variables, machine = run_q( 
            source, 
            data, 
        ) 

        got = extract_sha256( 
            variables 
        ) 

        expected = hashlib.sha256( 
            data 
        ).hexdigest() 

        if got != expected: 

            print() 
            print( 
                "SHA-256 FAILURE" 
            ) 

            print( 
                f"length : {len(data)}" 
            ) 

            print( 
                f"Q      : {got}" 
            ) 

            print( 
                f"hashlib: {expected}" 
            ) 

            raise SystemExit(1) 

        print( 
            f"PASS " 
            f"{len(data):5d} bytes " 
            f"{got}" 
        ) 

    print() 
    print( 
        "ALL Q SHA-256 TESTS PASSED" 
    ) 


# ============================================================ 
# INPUT 
# ============================================================ 

def load_input( 
    args, 
) -> bytes: 

    if args.input is not None: 

        return args.input.encode( 
            "utf-8" 
        ) 

    if args.file: 

        with open( 
            args.file, 
            "rb", 
        ) as f: 

            return f.read() 

    if args.hex is not None: 

        return bytes.fromhex( 
            args.hex 
        ) 

    if args.stdin: 

        return sys.stdin.buffer.read() 

    return b"" 


# ============================================================ 
