# ============================================================ 

def Ch(x, y, z): 
    return XOR32( 
        AND32(x, y), 
        AND32( 
            NOT32(x), 
            z 
        ) 
    ) 


def Maj(x, y, z): 
    return XOR32( 
        AND32(x, y), 
        AND32(x, z), 
        AND32(y, z) 
    ) 


def Sigma0(x): 
    return XOR32( 
        ROTR(x, 2), 
        ROTR(x, 13), 
        ROTR(x, 22) 
    ) 


