# ============================================================ 
# SHA-256 ROUND 
# ============================================================ 

def round( 
    a, 
    b, 
    c, 
    d, 
    e, 
    f, 
    g, 
    h, 
    k, 
    w 
): 

    t1 = ADD32( 
        h, 
        Sigma1(e), 
        Ch(e, f, g), 
        k, 
        w 
    ) 

    t2 = ADD32( 
        Sigma0(a), 
        Maj(a, b, c) 
    ) 

    new_h = g 
    new_g = f 
    new_f = e 
    new_e = ADD32( 
        d, 
        t1 
    ) 

    new_d = c 
    new_c = b 
    new_b = a 
    new_a = ADD32( 
        t1, 
        t2 
    ) 

    return [ 
        new_a, 
        new_b, 
        new_c, 
        new_d, 
        new_e, 
        new_f, 
        new_g, 
        new_h 
    ] 


