def sha256(): 

    h0 = 0x6a09e667 
    h1 = 0xbb67ae85 
    h2 = 0x3c6ef372 
    h3 = 0xa54ff53 
    h4 = 0x510e527f 
    h5 = 0x9b05688c 
    h6 = 0x1f83d9ab 
    h7 = 0x5be0cd19 

    block = 0 

    while block < WORD_COUNT(): 

        # ---------------------------------------------------- 
        # Message schedule 
        # ---------------------------------------------------- 

        w = [0] * 64 

        j = 0 

        while j < 16: 

            w[j] = INPUT_WORD( 
                block + j 
            ) 

            j = j + 1 

        j = 16 

        while j < 64: 

            w[j] = ADD32( 
                sigma1( 
                    w[j - 2] 
                ), 
                w[j - 7], 
                sigma0( 
                    w[j - 15] 
                ), 
                w[j - 16] 
            ) 

            j = j + 1 

        # ---------------------------------------------------- 
        # Working state 
        # ---------------------------------------------------- 

        a = h0 
        b = h1 
        c = h2 
        d = h3 
        e = h4 
        f = h5 
        g = h6 
        h = h7 

        # ---------------------------------------------------- 
        # 64 compression rounds 
        # ---------------------------------------------------- 

        j = 0 

        while j < 64: 

            state = round( 
                a, 
                b, 
                c, 
                d, 
                e, 
                f, 
                g, 
                h, 
