            b = state[1] 
            c = state[2] 
            d = state[3] 
            e = state[4] 
            f = state[5] 
            g = state[6] 
            h = state[7] 

            j = j + 1 

        # ---------------------------------------------------- 
        # Feed-forward 
        # ---------------------------------------------------- 

        h0 = ADD32( 
            h0, 
            a 
        ) 

        h1 = ADD32( 
            h1, 
            b 
        ) 

        h2 = ADD32( 
            h2, 
            c 
