        ) 

        h4 = ADD32( 
            h4, 
            e 
        ) 

        h5 = ADD32( 
            h5, 
            f 
        ) 

        h6 = ADD32( 
            h6, 
            g 
        ) 

        h7 = ADD32( 
            h7, 
            h 
        ) 

        block = block + 16 

    # -------------------------------------------------------- 
    # CRITICAL FIX: 
    # Return the final hash state. 
    # -------------------------------------------------------- 

    return [ 
        h0, 
        h1, 
        h2, 
        h3, 
        h4, 
        h5, 
        h6, 
        h7 
    ] 


