    "nudge_number",
    "flip_operator",
    "duplicate_statement",
    "delete_statement",
    "decrement_number",
    "double_number",
    "halve_number",
    "zero_number",
    "negate_number",
    "flip_boolean_operator",
    "flip_comparison",
    "invert_if_condition",
    "wrap_condition_not",
    "flip_boolean_constant",
    "change_string_literal",
    "append_string_literal",
    "prepend_string_literal",
    "swap_comparison_operands",
    "add_zero_to_expression",
    "multiply_expression_by_one",
    "replace_add_with_multiply",
    "replace_multiply_with_add",
    "invert_unary_operator",
    "remove_assert",
    "change_list_to_tuple",
    "reverse_list_literal",
    "swap_call_arguments",
    "change_range_step",
    "change_return_value",
]

OPERATOR_FLIPS = {
    ast.Add: ast.Sub,
    ast.Sub: ast.Add,
    ast.Mult: ast.Div,
    ast.Div: ast.Mult,
    ast.FloorDiv: ast.Mult,
    ast.Mod: ast.Add,
    ast.Eq: ast.NotEq,
    ast.NotEq: ast.Eq,
    ast.Gt: ast.LtE,
    ast.Lt: ast.GtE,
    ast.GtE: ast.Lt,
    ast.LtE: ast.Gt,
}

COMPARISON_REVERSE = {
    ast.Eq: ast.Eq,
    ast.NotEq: ast.NotEq,
    ast.Gt: ast.Lt,
    ast.Lt: ast.Gt,
    ast.GtE: ast.LtE,
    ast.LtE: ast.GtE,
    ast.In: ast.In,
    ast.NotIn: ast.NotIn,
    ast.Is: ast.Is,
    ast.IsNot: ast.IsNot,
}


def read_text(path):
    return Path(path).read_text(encoding="utf-8-sig")


def mutate_source(source, mode):
    """Apply one AST mutation. Return None if no eligible target exists."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None

    if mode in {
        "nudge_number", "decrement_number", "double_number",
        "halve_number", "zero_number", "negate_number",
    }:
        class NumberMutator(ast.NodeTransformer):
            changed = False

            def visit_Constant(self, node):
                if self.changed or isinstance(node.value, bool):
                    return node
                if not isinstance(node.value, (int, float, complex)):
                    return node

                value = node.value

                if mode == "nudge_number":
                    new_value = value + 1
                elif mode == "decrement_number":
                    new_value = value - 1
                elif mode == "double_number":
                    new_value = value * 2
                elif mode == "halve_number":
                    new_value = value / 2
                elif mode == "zero_number":
                    new_value = 0 if value != 0 else 1
                else:
                    new_value = -value if value != 0 else 1

                self.changed = True
                return ast.copy_location(ast.Constant(value=new_value), node)

        mutator = NumberMutator()
        tree = mutator.visit(tree)
        if not mutator.changed:
            return None

    elif mode in {
        "flip_operator", "flip_comparison",
        "flip_boolean_operator", "replace_add_with_multiply",
        "replace_multiply_with_add", "invert_unary_operator",
        "swap_comparison_operands", "add_zero_to_expression",
        "multiply_expression_by_one",
    }:
        class ExpressionMutator(ast.NodeTransformer):
            changed = False

            def visit_BinOp(self, node):
                self.generic_visit(node)
                if self.changed:
                    return node

                if mode == "replace_add_with_multiply" and isinstance(node.op, ast.Add):
                    node.op = ast.Mult()
                    self.changed = True
                elif mode == "replace_multiply_with_add" and isinstance(node.op, ast.Mult):
                    node.op = ast.Add()
                    self.changed = True
                elif mode == "flip_operator":
                    replacement = OPERATOR_FLIPS.get(type(node.op))
                    if replacement:
                        node.op = replacement()
                        self.changed = True
                elif mode == "add_zero_to_expression":
                    self.changed = True
                    return ast.copy_location(
                        ast.BinOp(left=node, op=ast.Add(), right=ast.Constant(value=0)),
                        node,
                    )
                elif mode == "multiply_expression_by_one":
                    self.changed = True
                    return ast.copy_location(
                        ast.BinOp(left=node, op=ast.Mult(), right=ast.Constant(value=1)),
                        node,
                    )
                return node

            def visit_Compare(self, node):
                self.generic_visit(node)
                if self.changed:
                    return node

                if mode in {"flip_operator", "flip_comparison"}:
                    for index, op in enumerate(node.ops):
                        replacement = OPERATOR_FLIPS.get(type(op))
                        if replacement and (
                            mode == "flip_operator"
                            or isinstance(op, (ast.Eq, ast.NotEq, ast.Gt, ast.Lt,
                                                ast.GtE, ast.LtE))
                        ):
                            node.ops[index] = replacement()
                            self.changed = True
                            break

                elif mode == "swap_comparison_operands" and len(node.ops) == 1:
                    op_type = type(node.ops[0])
                    replacement = COMPARISON_REVERSE.get(op_type)
                    if replacement:
                        node.left, node.comparators[0] = node.comparators[0], node.left
                        node.ops[0] = replacement()
                        self.changed = True

                return node

            def visit_BoolOp(self, node):
                self.generic_visit(node)
                if not self.changed and mode == "flip_boolean_operator":
                    if isinstance(node.op, ast.And):
                        node.op = ast.Or()
                        self.changed = True
                    elif isinstance(node.op, ast.Or):
                        node.op = ast.And()
                        self.changed = True
                return node

            def visit_UnaryOp(self, node):
                self.generic_visit(node)
                if self.changed or mode != "invert_unary_operator":
                    return node

                if isinstance(node.op, ast.USub):
                    node.op = ast.UAdd()
                    self.changed = True
                elif isinstance(node.op, ast.UAdd):
                    node.op = ast.USub()
                    self.changed = True
                elif isinstance(node.op, ast.Not):
                    node.op = ast.Invert()
                    self.changed = True
                elif isinstance(node.op, ast.Invert):
                    node.op = ast.Not()
                    self.changed = True
                return node

        mutator = ExpressionMutator()
        tree = mutator.visit(tree)
        if not mutator.changed:
            return None

    elif mode in {
        "invert_if_condition", "wrap_condition_not",
        "flip_boolean_constant", "change_string_literal",
        "append_string_literal", "prepend_string_literal",
        "change_list_to_tuple", "reverse_list_literal",
        "swap_call_arguments", "change_range_step",
        "change_return_value", "remove_assert",
    }:
        class GeneralMutator(ast.NodeTransformer):
            changed = False

            def visit_If(self, node):
                self.generic_visit(node)
                if not self.changed and mode in {
                    "invert_if_condition", "wrap_condition_not"
                }:
                    node.test = ast.copy_location(
                        ast.UnaryOp(op=ast.Not(), operand=node.test), node.test
                    )
                    self.changed = True
                return node

            def visit_While(self, node):
                self.generic_visit(node)
                if not self.changed and mode == "wrap_condition_not":
                    node.test = ast.copy_location(
                        ast.UnaryOp(op=ast.Not(), operand=node.test), node.test
                    )
                    self.changed = True
                return node

            def visit_Constant(self, node):
                if self.changed:
                    return node

                if mode == "flip_boolean_constant" and isinstance(node.value, bool):
                    self.changed = True
                    return ast.copy_location(ast.Constant(value=not node.value), node)

                if mode in {
                    "change_string_literal", "append_string_literal",
                    "prepend_string_literal",
                } and isinstance(node.value, str):
                    if mode == "change_string_literal":
                        value = "MUTATED_STRING" if node.value != "MUTATED_STRING" else "CHANGED"
                    elif mode == "append_string_literal":
                        value = node.value + "_mutated"
                    else:
                        value = "mutated_" + node.value

                    self.changed = True
                    return ast.copy_location(ast.Constant(value=value), node)

                return node

            def visit_List(self, node):
                self.generic_visit(node)
                if self.changed:
                    return node

                if mode == "change_list_to_tuple":
                    self.changed = True
                    return ast.copy_location(
                        ast.Tuple(elts=node.elts, ctx=node.ctx), node
                    )

                if mode == "reverse_list_literal" and len(node.elts) >= 2:
                    node.elts.reverse()
                    self.changed = True

                return node

            def visit_Call(self, node):
                self.generic_visit(node)
                if self.changed:
                    return node

                if mode == "swap_call_arguments" and len(node.args) >= 2:
                    node.args[0], node.args[1] = node.args[1], node.args[0]
                    self.changed = True

                elif mode == "change_range_step":
                    if isinstance(node.func, ast.Name) and node.func.id == "range":
                        if len(node.args) >= 3:
                            last = node.args[-1]
                            if isinstance(last, ast.Constant) and isinstance(last.value, int):
                                last.value = last.value + 1 if last.value != -1 else 1
                                self.changed = True
                        elif len(node.args) in (1, 2):
                            node.args.append(ast.Constant(value=2))
                            self.changed = True

                return node

            def visit_Return(self, node):
                self.generic_visit(node)
                if not self.changed and mode == "change_return_value" and node.value is not None:
                    if isinstance(node.value, ast.Constant) and isinstance(
                        node.value.value, (int, float)
                    ) and not isinstance(node.value.value, bool):
                        node.value.value += 1
                    else:
                        node.value = ast.Constant(value=None)
                    self.changed = True
                return node

            def visit_Assert(self, node):
                self.generic_visit(node)
                if not self.changed and mode == "remove_assert":
                    self.changed = True
                    return None
                return node

        mutator = GeneralMutator()
        tree = mutator.visit(tree)
        if not mutator.changed:
            return None

    elif mode in {"duplicate_statement", "delete_statement"}:
        candidates = [
            i for i, node in enumerate(tree.body)
            if isinstance(node, (ast.Assign, ast.AnnAssign, ast.Expr))
            and not (
                isinstance(node, ast.Expr)
                and isinstance(node.value, ast.Constant)
                and isinstance(node.value.value, str)
            )
        ]
        if not candidates:
            return None

        index = candidates[len(candidates) // 2]
        if mode == "duplicate_statement":
            tree.body.insert(index + 1, copy.deepcopy(tree.body[index]))
        else:
            tree.body.pop(index)

    else:
        return None

    ast.fix_missing_locations(tree)

    try:
        new_source = ast.unparse(tree) + "\n"
        compile(new_source, "<mutated-source>", "exec")
    except (SyntaxError, ValueError, TypeError):
        return None

    if new_source == source:
        return None

    return new_source


def run_modified_script(script_source, original_script, corpus, prompt, extra_args, timeout):
    """Run a temporary variant beside the original so local imports still work."""
    temp_path = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            suffix=".py",
            prefix=f".{original_script.stem}_mutation_",
            dir=str(original_script.parent),
            delete=False,
        ) as handle:
            handle.write(script_source)
            temp_path = Path(handle.name)

        command = [
            sys.executable,
            str(temp_path),
            str(corpus.resolve()),
            "--prompt",
            prompt,
            *extra_args,
        ]

        print("\nCOMMAND:", shlex.join(command), flush=True)

        return subprocess.run(
            command,
            cwd=str(original_script.parent),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
            check=False,
        )
    finally:
        if temp_path is not None:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass


def main():
    parser = argparse.ArgumentParser(
        description="Mutate Python source, run each variant, and save successful versions."
    )
    parser.add_argument("script_path", help="Python source file, e.g. markov_gen.py")
    parser.add_argument("corpus_path", help="Training corpus passed to the script")
    parser.add_argument("--prompt", default="once upon a time")
    parser.add_argument("--timeout", type=float, default=10.0)
    parser.add_argument("--extra-arg", action="append", default=[])
    parser.add_argument("--modes", default=",".join(DEFAULT_MUTATIONS))
    parser.add_argument("--limit", type=int, default=0)
    parser.add_argument("--output-dir", default="successful_source_mutations")
    parser.add_argument("--stop-on-error", action="store_true")
    args = parser.parse_args()

    if args.timeout <= 0 or args.limit < 0:
        parser.error("Timeout must be positive and limit cannot be negative.")

    script = Path(args.script_path).expanduser().resolve()
    corpus = Path(args.corpus_path).expanduser().resolve()

    if not script.is_file():
        parser.error(f"Source script not found: {script}")
    if not corpus.is_file():
        parser.error(f"Corpus not found: {corpus}")

    original_source = read_text(script)
    try:
        ast.parse(original_source)
    except SyntaxError as exc:
        parser.error(f"Original source has a syntax error: {exc}")

    modes = [mode.strip() for mode in args.modes.split(",") if mode.strip()]
    invalid = sorted(set(modes) - set(DEFAULT_MUTATIONS))
    if invalid:
        parser.error(f"Unknown modes: {', '.join(invalid)}")

    output_dir = Path(args.output_dir).expanduser().resolve()
    stats = {
        "attempted": 0, "ok": 0, "failed": 0,
        "timeout": 0, "skipped": 0,
    }

    for mode in modes:
        if args.limit and stats["attempted"] >= args.limit:
            break

        mutated_source = mutate_source(original_source, mode)

        if mutated_source is None:
            print(f"\n[mode={mode}] Skipped: no eligible mutation found.")
            stats["skipped"] += 1
            continue

        stats["attempted"] += 1


        try:
            result = run_modified_script(
                mutated_source, script, corpus, args.prompt,
                args.extra_arg, args.timeout,
            )

            print(f"\nEXIT CODE: {result.returncode}")
            print("\n>>> PROMPT-GENERATED RESULT <<<")
            print(result.stdout.strip() or "(No stdout produced.)")

            if result.stderr.strip():
                print("\n>>> STDERR / DIAGNOSTICS <<<")
                print(result.stderr.strip())

            if result.returncode == 0:
                output_dir.mkdir(parents=True, exist_ok=True)
                output_path = output_dir / f"{script.stem}_{mode}.py"
                output_path.write_text(mutated_source, encoding="utf-8")
                stats["ok"] += 1
                print(f"\nSUCCESS: Modified source saved to {output_path}")
            else:
                stats["failed"] += 1
                print("\nFAILED: Modified source was not saved.")

        except subprocess.TimeoutExpired:
            stats["timeout"] += 1
            print(f"\nTIMEOUT: Process exceeded {args.timeout:g} seconds.")

        except OSError as exc:
            stats["failed"] += 1
            print(f"\nEXECUTION ERROR: {exc}")

        if args.stop_on_error and (stats["failed"] or stats["timeout"]):
            break

    print("\n" + "=" * 78)
    print("SOURCE MUTATION SUMMARY")
    print("=" * 78)
    print(f"Available modes: {len(DEFAULT_MUTATIONS)}")
    print(f"Executions     : {stats['attempted']}")
    print(f"Successful     : {stats['ok']}")
    print(f"Failed         : {stats['failed']}")
    print(f"Timeouts       : {stats['timeout']}")
    print(f"Skipped        : {stats['skipped']}")
    print(f"Output dir     : {output_dir}")


if __name__ == "__main__":
    main()

