#!/usr/bin/env python3
"""Python source mutation tester.

Creates independent AST-based mutations of a Python script, prints each
mutated source before execution, runs it against a corpus and prompt, and
saves only mutations whose subprocess exits successfully.

Example:
    python mutation_tester.py markov_gen.py data.txt --prompt "once upon a time"

Pass additional target-script arguments with:
    --extra-arg=--n --extra-arg=3
"""

import argparse
import ast
import copy
import os
import subprocess
import sys
import tempfile
import time
from pathlib import Path


DEFAULT_MUTATIONS = [
    "nudge_number",
    "flip_operator",
    "duplicate_statement",
    "delete_statement",
    "decrement_number",
    "double_number",
    "halve_number",
    "zero_number",
    "negate_number",
    "flip_boolean_operator",
    "flip_comparison",
    "invert_if_condition",
    "wrap_condition_not",
    "flip_boolean_constant",
    "change_string_literal",
    "append_string_literal",
    "prepend_string_literal",
    "swap_comparison_operands",
    "add_zero_to_expression",
    "multiply_expression_by_one",
    "replace_add_with_multiply",
    "replace_multiply_with_add",
    "invert_unary_operator",
    "remove_assert",
    "change_list_to_tuple",
    "reverse_list_literal",
    "swap_call_arguments",
    "change_range_step",
    "change_return_value",
]


OPERATOR_FLIPS = {
    ast.Add: ast.Sub,
    ast.Sub: ast.Add,
    ast.Mult: ast.Div,
    ast.Div: ast.Mult,
    ast.FloorDiv: ast.Mult,
    ast.Mod: ast.Add,
    ast.BitAnd: ast.BitOr,
    ast.BitOr: ast.BitAnd,
    ast.BitXor: ast.BitAnd,
    ast.And: ast.Or,
    ast.Or: ast.And,
}

COMPARISON_FLIPS = {
    ast.Eq: ast.NotEq,
    ast.NotEq: ast.Eq,
    ast.Gt: ast.LtE,
    ast.Lt: ast.GtE,
    ast.GtE: ast.Lt,
    ast.LtE: ast.Gt,
    ast.Is: ast.IsNot,
    ast.IsNot: ast.Is,
    ast.In: ast.NotIn,
    ast.NotIn: ast.In,
}

COMPARISON_REVERSE = {
    ast.Eq: ast.Eq,
    ast.NotEq: ast.NotEq,
    ast.Gt: ast.Lt,
    ast.Lt: ast.Gt,
    ast.GtE: ast.LtE,
    ast.LtE: ast.GtE,
    ast.Is: ast.Is,
    ast.IsNot: ast.IsNot,
    ast.In: ast.In,
    ast.NotIn: ast.NotIn,
}

UNARY_FLIPS = {
    ast.UAdd: ast.USub,
    ast.USub: ast.UAdd,
    ast.Not: ast.Not,
    ast.Invert: ast.Invert,
}


def is_number(value):
    """True for numeric constants but not booleans."""
    return isinstance(value, (int, float, complex)) and not isinstance(value, bool)


def is_docstring_statement(node):
    return (
        isinstance(node, ast.Expr)
        and isinstance(node.value, ast.Constant)
        and isinstance(node.value.value, str)
    )


def get_numeric_constants(tree):
    return [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Constant) and is_number(node.value)
    ]


def get_string_constants(tree):
    return [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Constant) and isinstance(node.value, str)
    ]


def get_boolean_constants(tree):
    return [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Constant) and isinstance(node.value, bool)
    ]


def get_binary_operations(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.BinOp)]


def get_boolean_operations(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.BoolOp)]


def get_comparisons(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.Compare)]


def get_unary_operations(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.UnaryOp)]


def get_if_nodes(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.If)]


def get_while_nodes(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.While)]


def get_list_literals(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.List)]


def get_call_nodes(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.Call)]


def get_return_nodes(tree):
    return [node for node in ast.walk(tree) if isinstance(node, ast.Return)]


def get_statement_candidates(tree):
    candidates = []

    for node in ast.walk(tree):
        if not isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef,
                                 ast.ClassDef, ast.If, ast.For, ast.AsyncFor,
                                 ast.While, ast.With, ast.AsyncWith, ast.Try,
                                 ast.ExceptHandler)):
            continue

        body = getattr(node, "body", None)
        if not isinstance(body, list):
            continue

        for index, statement in enumerate(body):
            if is_docstring_statement(statement):
                continue

            if isinstance(statement, (ast.Assign, ast.AnnAssign, ast.Expr,
                                      ast.AugAssign, ast.Pass, ast.Return)):
                candidates.append((body, index, statement))

    return candidates


def get_assert_candidates(tree):
    return [
        node for node in ast.walk(tree)
        if isinstance(node, ast.Assert)
    ]


def set_numeric_value(node, value):
    node.value = value


def numeric_mutation(tree, mode, attempt):
    candidates = get_numeric_constants(tree)
    if not candidates:
        return False

    node = candidates[attempt % len(candidates)]
    value = node.value
    step = (attempt // max(1, len(candidates))) + 1

    if mode == "nudge_number":
        node.value = value + step
    elif mode == "decrement_number":
        node.value = value - step
    elif mode == "double_number":
        node.value = value * (step + 1)
    elif mode == "halve_number":
        node.value = value / (step + 1)
    elif mode == "zero_number":
        node.value = 0 if value != 0 else step
    elif mode == "negate_number":
        node.value = -value if value != 0 else step
    else:
        return False

    return True


def mutate_source(source, mode, attempt=0):
    """Return a mutated Python source string, or None if not applicable."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None

    changed = False

    if mode in {
        "nudge_number", "decrement_number", "double_number",
        "halve_number", "zero_number", "negate_number",
    }:
        changed = numeric_mutation(tree, mode, attempt)

    elif mode in {
        "flip_operator", "replace_add_with_multiply",
        "replace_multiply_with_add", "add_zero_to_expression",
        "multiply_expression_by_one",
    }:
        candidates = get_binary_operations(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]

            if mode == "flip_operator":
                replacement = OPERATOR_FLIPS.get(type(node.op))
                if replacement is not None:
                    node.op = replacement()
                    changed = True

            elif mode == "replace_add_with_multiply":
                if isinstance(node.op, ast.Add):
                    node.op = ast.Mult()
                    changed = True

            elif mode == "replace_multiply_with_add":
                if isinstance(node.op, ast.Mult):
                    node.op = ast.Add()
                    changed = True

            elif mode == "add_zero_to_expression":
                original = copy.deepcopy(node)
                node.left = ast.BinOp(
                    left=original.left,
                    op=ast.Add(),
                    right=ast.Constant(value=attempt + 0),
                )
                changed = True

            elif mode == "multiply_expression_by_one":
                original = copy.deepcopy(node)
                node.left = ast.BinOp(
                    left=original.left,
                    op=ast.Mult(),
                    right=ast.Constant(value=attempt + 1),
                )
                changed = True

    elif mode == "flip_boolean_operator":
        candidates = get_boolean_operations(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            if isinstance(node.op, ast.And):
                node.op = ast.Or()
                changed = True
            elif isinstance(node.op, ast.Or):
                node.op = ast.And()
                changed = True

    elif mode == "flip_comparison":
        candidates = get_comparisons(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            for index, operator in enumerate(node.ops):
                replacement = COMPARISON_FLIPS.get(type(operator))
                if replacement is not None:
                    node.ops[index] = replacement()
                    changed = True
                    break

    elif mode in {"invert_if_condition", "wrap_condition_not"}:
        candidates = get_if_nodes(tree) + get_while_nodes(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            node.test = ast.UnaryOp(op=ast.Not(), operand=node.test)
            changed = True

    elif mode == "flip_boolean_constant":
        candidates = get_boolean_constants(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            node.value = not node.value
            changed = True

    elif mode in {
        "change_string_literal", "append_string_literal",
        "prepend_string_literal",
    }:
        candidates = get_string_constants(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            value = node.value
            variation = attempt + 1

            if mode == "change_string_literal":
                node.value = f"{value}_mut{variation}"
            elif mode == "append_string_literal":
                node.value = value + ("x" * variation)
            else:
                node.value = ("x" * variation) + value

            changed = True

    elif mode == "swap_comparison_operands":
        candidates = get_comparisons(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            if len(node.ops) == 1 and len(node.comparators) == 1:
                original_left = node.left
                original_right = node.comparators[0]
                node.left = original_right
                node.comparators[0] = original_left

                replacement = COMPARISON_REVERSE.get(type(node.ops[0]))
                if replacement is not None:
                    node.ops[0] = replacement()
                changed = True

    elif mode in {"duplicate_statement", "delete_statement"}:
        candidates = get_statement_candidates(tree)
        if candidates:
            body, index, statement = candidates[attempt % len(candidates)]

            if mode == "duplicate_statement":
                body.insert(index + 1, copy.deepcopy(statement))
                changed = True
            elif len(body) > 1:
                del body[index]
                changed = True

    elif mode == "invert_unary_operator":
        candidates = get_unary_operations(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            replacement = UNARY_FLIPS.get(type(node.op))
            if replacement is not None:
                if isinstance(node.op, ast.Not):
                    node.operand = ast.UnaryOp(
                        op=ast.Not(),
                        operand=node.operand,
                    )
                else:
                    node.op = replacement()
                changed = True

    elif mode == "remove_assert":
        candidates = get_assert_candidates(tree)
        if candidates:
            target = candidates[attempt % len(candidates)]
            parent_lists = []

            for parent in ast.walk(tree):
                for field_name, value in ast.iter_fields(parent):
                    if isinstance(value, list) and target in value:
                        parent_lists.append((value, target))

            if parent_lists:
                body, target_node = parent_lists[0]
                body.remove(target_node)
                changed = True

    elif mode == "change_list_to_tuple":
        candidates = get_list_literals(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            replacement = ast.Tuple(
                elts=node.elts,
                ctx=node.ctx,
            )
            for parent in ast.walk(tree):
                for field_name, value in ast.iter_fields(parent):
                    if value is node:
                        setattr(parent, field_name, replacement)
                        changed = True
                        break
                    elif isinstance(value, list):
                        for index, item in enumerate(value):
                            if item is node:
                                value[index] = replacement
                                changed = True
                                break
                if changed:
                    break

    elif mode == "reverse_list_literal":
        candidates = get_list_literals(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            if len(node.elts) > 1:
                node.elts.reverse()
                changed = True
            elif len(node.elts) == 1:
                node.elts.append(copy.deepcopy(node.elts[0]))
                changed = True

    elif mode == "swap_call_arguments":
        candidates = [
            node for node in get_call_nodes(tree)
            if len(node.args) >= 2
        ]
        if candidates:
            node = candidates[attempt % len(candidates)]
            left = attempt % (len(node.args) - 1)
            node.args[left], node.args[left + 1] = (
                node.args[left + 1],
                node.args[left],
            )
            changed = True

    elif mode == "change_range_step":
        candidates = [
            node for node in get_call_nodes(tree)
            if isinstance(node.func, ast.Name)
            and node.func.id == "range"
        ]
        if candidates:
            node = candidates[attempt % len(candidates)]
            if len(node.args) == 1:
                node.args.append(ast.Constant(value=attempt + 2))
            elif len(node.args) == 2:
                node.args.append(ast.Constant(value=attempt + 2))
            else:
                current = node.args[2]
                if isinstance(current, ast.Constant) and is_number(current.value):
                    current.value = -(attempt + 2) if current.value >= 0 else attempt + 2
                else:
                    node.args[2] = ast.Constant(value=attempt + 2)
            changed = True

    elif mode == "change_return_value":
        candidates = get_return_nodes(tree)
        if candidates:
            node = candidates[attempt % len(candidates)]
            if node.value is None:
                node.value = ast.Constant(value=attempt + 1)
            else:
                node.value = ast.Constant(value=None)
            changed = True

    if not changed:
        return None

    ast.fix_missing_locations(tree)

    try:
        mutated_source = ast.unparse(tree)
        compile(mutated_source, "<mutated-source>", "exec")
    except (SyntaxError, ValueError, TypeError):
        return None

    if mutated_source.strip() == source.strip():
        return None

    return mutated_source + "\n"


def run_modified_script(
    script_source,
    original_script,
    corpus,
    prompt,
    extra_args,
    timeout,
):
    """Execute the mutation from a temporary file beside the target script."""
    original_script = original_script.resolve()
    corpus = corpus.resolve()

    temp_path = None

    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            suffix=".py",
            prefix=f"{original_script.stem}_mutation_",
            dir=str(original_script.parent),
            delete=False,
            newline="\n",
        ) as handle:
            handle.write(script_source)
            temp_path = Path(handle.name)

        command = [
            sys.executable,
            str(temp_path),
            str(corpus),
            "--prompt",
            prompt,
            *extra_args,
        ]

        try:
            result = subprocess.run(
                command,
                cwd=str(original_script.parent),
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=timeout,
                check=False,
            )
            return {
                "command": command,
                "returncode": result.returncode,
                "stdout": result.stdout,
                "stderr": result.stderr,
                "timed_out": False,
            }

        except subprocess.TimeoutExpired as exc:
            stdout = exc.stdout or ""
            stderr = exc.stderr or ""

            if isinstance(stdout, bytes):
                stdout = stdout.decode("utf-8", errors="replace")
            if isinstance(stderr, bytes):
                stderr = stderr.decode("utf-8", errors="replace")

            return {
                "command": command,
                "returncode": None,
                "stdout": stdout,
                "stderr": stderr,
                "timed_out": True,
            }

    finally:
        if temp_path is not None:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass


def save_successful_mutation(output_dir, script_stem, mode, attempt, source):
    output_dir.mkdir(parents=True, exist_ok=True)
    output_path = output_dir / (
        f"{script_stem}_{mode}_{attempt:03d}.py"
    )
    output_path.write_text(source, encoding="utf-8", newline="\n")
    return output_path


def print_source(source):
    print("\n" + "=" * 88)
    print("MUTATED SOURCE — executing this exact source next")
    print("=" * 88)
    print(source.rstrip())
    print("=" * 88 + "\n")


def print_process_result(result):
    print("Command:")
    print(subprocess.list2cmdline(result["command"]))

    if result["timed_out"]:
        print("Result: TIMEOUT")
    else:
        print(f"Exit code: {result['returncode']}")

    print("\n--- Generated stdout ---")
    print(result["stdout"] if result["stdout"] else "(no stdout)")

    if result["stderr"]:
        print("\n--- stderr ---")
        print(result["stderr"])


def main():
    parser = argparse.ArgumentParser(
        description=(
            "Mutate Python source code, run each variant against a corpus, "
            "and save only successful variants."
        )
    )

    parser.add_argument(
        "script_path",
        type=Path,
        help="Python generator script to mutate, e.g. markov_gen.py",
    )
    parser.add_argument(
        "corpus_path",
        type=Path,
        help="Corpus file passed to the target script",
    )
    parser.add_argument(
        "--prompt",
        default="once upon a time",
        help="Prompt passed to the target script",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=10.0,
        help="Timeout in seconds for each mutation run",
    )
    parser.add_argument(
        "--extra-arg",
        action="append",
        default=[],
        help="Additional argument for the target script; repeat as needed",
    )
    parser.add_argument(
        "--modes",
        nargs="*",
        default=None,
        choices=DEFAULT_MUTATIONS,
        help="Mutation modes to run; default is every available mode",
    )
    parser.add_argument(
        "--mutations-per-mode",
        type=int,
        default=50,
        help="Independent mutation attempts per mode (default: 50)",
    )
    parser.add_argument(
        "--limit",
        type=int,
        default=0,
        help="Maximum total executions; 0 means unlimited",
    )
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=Path("successful_source_mutations"),
        help="Directory for saved successful mutated scripts",
    )
    parser.add_argument(
        "--stop-on-error",
        action="store_true",
        help="Stop after the first mutation that exits unsuccessfully",
    )

    args = parser.parse_args()

    script = args.script_path.resolve()
    corpus = args.corpus_path.resolve()

    if not script.is_file():
        parser.error(f"Python script not found: {script}")

    if not corpus.is_file():
        parser.error(f"Corpus file not found: {corpus}")

    if args.mutations_per_mode < 1:
        parser.error("--mutations-per-mode must be at least 1")

    if args.limit < 0:
        parser.error("--limit cannot be negative")

    if args.timeout <= 0:
        parser.error("--timeout must be greater than zero")

    try:
        original_source = script.read_text(encoding="utf-8")
        ast.parse(original_source)
    except (OSError, UnicodeError, SyntaxError) as exc:
        parser.error(f"Cannot read or parse target script: {exc}")

    modes = args.modes if args.modes is not None else DEFAULT_MUTATIONS

    print("=" * 88)
    print("PYTHON SOURCE MUTATION TESTER")
    print("=" * 88)
    print(f"Target script:       {script}")
    print(f"Corpus:              {corpus}")
    print(f"Prompt:              {args.prompt!r}")
    print(f"Mutation modes:      {len(modes)}")
    print(f"Mutations per mode:  {args.mutations_per_mode}")
    print(
        "Maximum executions: "
        + (str(args.limit) if args.limit else "unlimited")
    )
    print(f"Timeout per run:     {args.timeout}s")
    print(f"Successful outputs:  {args.output_dir.resolve()}")
    print(f"Planned attempts:    {len(modes) * args.mutations_per_mode}")
    print("=" * 88)

    stats = {
        "attempted": 0,
        "executed": 0,
        "saved": 0,
        "failed": 0,
        "timed_out": 0,
        "skipped": 0,
    }

    saved_paths = []
    stop = False
    started = time.time()

    for mode in modes:
        if stop:
            break

        print(f"\n\n{'#' * 88}")
        print(
            f"MODE: {mode} — "
            f"{args.mutations_per_mode} mutation attempts"
        )
        print(f"{'#' * 88}")

        # Each variant starts from the original source, not the previous
        # mutation, so the mutations are independent.
        for attempt in range(args.mutations_per_mode):
            if args.limit and stats["executed"] >= args.limit:
                print("\nReached --limit. Stopping.")
                stop = True
                break

            stats["attempted"] += 1
            attempt_number = attempt + 1

            print(
                f"\n\n--- Mode {mode} | mutation "
                f"{attempt_number}/{args.mutations_per_mode} ---"
            )

            mutated_source = mutate_source(
                original_source,
                mode,
                attempt=attempt,
            )

            if mutated_source is None:
                stats["skipped"] += 1
                print(
                    "Skipped: no applicable, syntactically valid mutation "
                    "could be created for this attempt."
                )
                continue

            print_source(mutated_source)

            result = run_modified_script(
                script_source=mutated_source,
                original_script=script,
                corpus=corpus,
                prompt=args.prompt,
                extra_args=args.extra_arg,
                timeout=args.timeout,
            )

            stats["executed"] += 1
            print_process_result(result)

            if result["timed_out"]:
                stats["timed_out"] += 1
                stats["failed"] += 1
                print("\nMutation failed: execution timed out.")

                if args.stop_on_error:
                    stop = True
                    break

            elif result["returncode"] == 0:
                output_path = save_successful_mutation(
                    output_dir=args.output_dir.resolve(),
                    script_stem=script.stem,
                    mode=mode,
                    attempt=attempt_number,
                    source=mutated_source,
                )
                stats["saved"] += 1
                saved_paths.append(output_path)
                print(f"\nSUCCESS: saved mutated source to {output_path}")

            else:
                stats["failed"] += 1
                print(
                    "\nFAILURE: exit code was not zero. "
                    "Mutated source was not saved."
                )

                if args.stop_on_error:
                    stop = True
                    break

    elapsed = time.time() - started

    print("\n\n" + "=" * 88)
    print("MUTATION TEST SUMMARY")
    print("=" * 88)
    print(f"Mutation attempts considered: {stats['attempted']}")
    print(f"Subprocesses executed:        {stats['executed']}")
    print(f"Successful scripts saved:     {stats['saved']}")
    print(f"Failed executions:            {stats['failed']}")
    print(f"Timed-out executions:         {stats['timed_out']}")
    print(f"Skipped/inapplicable:         {stats['skipped']}")
    print(f"Elapsed time:                 {elapsed:.2f}s")
    print(f"Output directory:             {args.output_dir.resolve()}")

    if saved_paths:
        print("\nSaved source files:")
        for path in saved_paths:
            print(f"  {path}")

    print("=" * 88)

    # The tester itself returns a nonzero status only if interrupted by
    # its own argument validation or another uncaught failure. Individual
    # mutation failures are summarized above.


if __name__ == "__main__":
    main()
