### Run it

```bash
python mutation_tester.py markov_gen.py singlekb.txt --prompt "once upon a time"
```

That runs up to **29 modes × 50 attempts = 1,450 attempts**. Some attempts may be skipped if a mode has no applicable target in your script.

To pass extra arguments to `markov_gen.py`:

```bash
python mutation_tester.py markov_gen.py singlekb.txt --prompt "once upon a time" --extra-arg=--n --extra-arg=3
```

To test only a few modes:

```bash
python mutation_tester.py markov_gen.py singlekb.txt --modes nudge_number flip_operator change_string_literal --mutations-per-mode 50
```

Successful variants are saved in `successful_source_mutations/`; unsuccessful ones are **not saved**. The original script is never overwritten. Note that exit code `0` confirms the target process completed successfully, not necessarily that its generated text is semantically correct.

#!/usr/bin/env python3
import argparse
import re
import shlex
import subprocess
import sys
import tempfile
from pathlib import Path

MATH_LINE_RE = re.compile(r"[\d][\d\s.,+\-*/=^(){}\[\]<>:;]*")
MATH_TOKEN_RE = re.compile(
    r"\d+(?:\.\d+)?(?:[eE][+-]?\d+)?"
    r"|[A-Za-z_][A-Za-z_0-9]*"
    r"|[+\-*/=^(){}\[\]<>.,:;]"
)

DEFAULT_MUTATIONS = [
    "swap_terms",
    "delete_term",
    "duplicate_term",
    "nudge_number",
    "flip_operator",
]

FLIPS = {
    "+": "-", "-": "+", "*": "/", "/": "*",
    "=": "!=", "^": "**",
}


def read_lines(path):
    return Path(path).read_text(encoding="utf-8-sig").splitlines()


def write_lines(path, lines):
    Path(path).write_text(
        "\n".join(lines) + "\n",
        encoding="utf-8",
    )


def is_math_line(line):
    s = line.strip()
    return (
        bool(s)
        and bool(MATH_LINE_RE.search(s))
        and any(ch.isdigit() for ch in s)
    )


def tokenize_line(line):
    return MATH_TOKEN_RE.findall(line)


def detokenize(tokens):
    out = ""
    previous = ""

    for token in tokens:
        if not out:
            out = token
        elif token in {",", ":", ";", ".", ")", "]", "}", ">"}:
            out += token
        elif previous in {"(", "[", "{", "<"}:
            out += token
        elif token in {"(", "[", "{"}:
            out += " " + token
        else:
            out += " " + token
        previous = token

    return out


def mutate_tokens(tokens, mode):
    out = list(tokens)
    number_re = r"\d+(?:\.\d+)?(?:[eE][+-]?\d+)?"

    number_positions = [
        i for i, token in enumerate(out)
        if re.fullmatch(number_re, token)
    ]

    operator_positions = [
        i for i, token in enumerate(out)
        if token in {"+", "-", "*", "/", "=", "^"}
    ]

    if mode == "swap_terms" and len(number_positions) >= 2:
        i, j = number_positions[0], number_positions[-1]
        out[i], out[j] = out[j], out[i]

    elif mode == "delete_term" and number_positions:
        i = number_positions[len(number_positions) // 2]
        out.pop(i)

    elif mode == "duplicate_term" and number_positions:
        i = number_positions[len(number_positions) // 2]
        out.insert(i + 1, out[i])

    elif mode == "nudge_number" and number_positions:
        i = number_positions[len(number_positions) // 2]
        try:
            original = out[i]
            if "e" in original.lower():
                out[i] = str(float(original) + 1.0)
            elif "." in original:
                out[i] = str(float(original) + 1.0)
            else:
                out[i] = str(int(original) + 1)
        except (ValueError, OverflowError):
            return tokens

    elif mode == "flip_operator" and operator_positions:
        i = operator_positions[len(operator_positions) // 2]
        out[i] = FLIPS[out[i]]

    return out


def mutate_line(line, mode):
    if not is_math_line(line):
        return None

    tokens = tokenize_line(line)
    if not tokens:
        return None

    mutated = mutate_tokens(tokens, mode)

    if mutated == tokens:
        return None

    result = detokenize(mutated)

    if result.strip() == line.strip():
        return None

    return result


def run_target(script_path, corpus_path, prompt, extra_args, timeout):
    script = Path(script_path).expanduser().resolve()
    corpus = Path(corpus_path).expanduser().resolve()

    if not script.is_file():
        raise FileNotFoundError(f"Generator script not found: {script}")

    if not corpus.is_file():
        raise FileNotFoundError(f"Mutated corpus not found: {corpus}")

    # algorithm.py accepts the corpus path and --prompt.
    # No default xaa argument is passed.
    cmd = [
        sys.executable,
        str(script),
        str(corpus),
        "--prompt",
        prompt,
        *extra_args,
    ]

    print("\nCOMMAND:", shlex.join(cmd), flush=True)

    return subprocess.run(
        cmd,
        cwd=str(script.parent),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=timeout,
        check=False,
    )


def main():
    parser = argparse.ArgumentParser(
        description=(
            "Mutate corpus lines, execute algorithm.py independently "
            "for each mutation, and show prompt-generated results."
        )
    )

    parser.add_argument("script_path", help="Path to algorithm.py")
    parser.add_argument("corpus_path", help="Original training corpus")
    parser.add_argument("--prompt", default="once upon a")
    parser.add_argument("--timeout", type=float, default=10.0)
    parser.add_argument(
        "--extra-arg",
        action="append",
        default=[],
        help="Optional additional generator argument; repeatable",
    )
    parser.add_argument(
        "--modes",
        default=",".join(DEFAULT_MUTATIONS),
        help="Comma-separated mutation modes",
    )
    parser.add_argument(
        "--limit",
        type=int,
        default=0,
        help="Maximum executions; 0 means unlimited",
    )
    parser.add_argument(
        "--show-output",
        action="store_true",
        help="Show raw stdout/stderr and return code",
    )
    parser.add_argument(
        "--stop-on-error",
        action="store_true",
        help="Stop on the first failed process or timeout",
    )

    args = parser.parse_args()

    if args.timeout <= 0:
        parser.error("--timeout must be greater than zero")

    if args.limit < 0:
        parser.error("--limit cannot be negative")

    script = Path(args.script_path).expanduser().resolve()
    corpus = Path(args.corpus_path).expanduser().resolve()

    if not script.is_file():
        parser.error(f"Generator script not found: {script}")

    if not corpus.is_file():
        parser.error(f"Corpus file not found: {corpus}")

    try:
        lines = read_lines(corpus)
    except (OSError, UnicodeError) as exc:
        parser.error(f"Cannot read corpus: {exc}")

    modes = [
        mode.strip()
        for mode in args.modes.split(",")
        if mode.strip()
    ]

    invalid_modes = sorted(set(modes) - set(DEFAULT_MUTATIONS))
    if invalid_modes:
        parser.error(
            f"Unknown modes: {', '.join(invalid_modes)}. "
            f"Valid modes: {', '.join(DEFAULT_MUTATIONS)}"
        )

    if not modes:
        parser.error("At least one mutation mode is required")

    stats = {
        "attempted": 0,
        "ok": 0,
        "failed": 0,
        "timeout": 0,
        "skipped": 0,
    }

    stop = False

    print("=" * 78)
    print("CORPUS MUTATION AND PROMPT GENERATION")
    print("=" * 78)
    print(f"Generator : {script}")
    print(f"Corpus    : {corpus}")
    print(f"Lines     : {len(lines)}")
    print(f"Prompt    : {args.prompt}")
    print(f"Extra args: {args.extra_arg}")
    print(f"Modes     : {', '.join(modes)}")

    for line_idx, original in enumerate(lines, start=1):
        if not is_math_line(original):
            continue

        for mode in modes:
            mutated = mutate_line(original, mode)

            if mutated is None:
                stats["skipped"] += 1
                continue

            if args.limit and stats["attempted"] >= args.limit:
                stop = True
                break

            stats["attempted"] += 1
            result = None
            error = None

            print("\n" + "=" * 78)
            print(
                f"TEST {stats['attempted']} | "
                f"LINE {line_idx} | MODE {mode}"
            )
            print("-" * 78)
            print(f"PROMPT         : {args.prompt}")
            print(f"ORIGINAL LINE  : {original}")
            print(f"MUTATED LINE   : {mutated}")
            print("-" * 78)

            try:
                # Preserve the full corpus and change only this line.
                # Each test uses a separate temporary corpus and process.
                with tempfile.TemporaryDirectory(
                    prefix="mutation_test_"
                ) as td:
                    mutated_corpus = Path(td) / "mutated.txt"
                    updated_lines = list(lines)
                    updated_lines[line_idx - 1] = mutated
                    write_lines(mutated_corpus, updated_lines)

                    result = run_target(
                        script,
                        mutated_corpus,
                        args.prompt,
                        args.extra_arg,
                        args.timeout,
                    )

                if result.returncode == 0:
                    status = "ok"
                    stats["ok"] += 1
                else:
                    status = f"exit code {result.returncode}"
                    stats["failed"] += 1

            except subprocess.TimeoutExpired as exc:
