        mutated_source = mutate_source(original_source, mode)

        if mutated_source is None:
            print(f"\n[mode={mode}] Skipped: no eligible mutation found.")
            stats["skipped"] += 1
            continue

        stats["attempted"] += 1
        print("\n" + "=" * 78)
        print(f"SOURCE MUTATION {stats['attempted']} | MODE: {mode}")
        print("=" * 78)
        print(">>> NEW PYTHON SOURCE (BEFORE EXECUTION) <<<")
