#!/usr/bin/env python3
import argparse
import subprocess
import tempfile
import sys
import re
from pathlib import Path

MATH_LINE_RE = re.compile(r"[\d][\d\s\.\,\+\-\*\/\=\^\(\)\[\]\{\}<>:;]+")
MATH_TOKEN_RE = re.compile(r"[0-9A-Za-z_]+|[+\-*/=^(){}\[\]<>.,:;]")

DEFAULT_MUTATIONS = [
    "swap_terms",
    "delete_term",
    "duplicate_term",
    "nudge_number",
    "flip_operator",
]


def read_lines(path):
    return Path(path).read_text(encoding="utf-8").splitlines()


def write_lines(path, lines):
    Path(path).write_text("\n".join(lines) + "\n", encoding="utf-8")


def is_math_line(line):
    s = line.strip()
    return bool(MATH_LINE_RE.search(s)) and any(ch.isdigit() for ch in s)


def tokenize_line(line):
    return MATH_TOKEN_RE.findall(line)


def detokenize(tokens):
    out = []
    for t in tokens:
        if not out:
            out.append(t)
        elif t in ",:;)]}>" or t == ".":
            out[-1] += t
        elif out[-1] in "([<{":
            out.append(t)
        else:
            out.append(" " + t)
    return "".join(out)


def mutate_tokens(tokens, mode):
    if not tokens:
        return tokens

    out = list(tokens)

    term_positions = [i for i, t in enumerate(out) if re.fullmatch(r"[0-9]+(?:\.[0-9]+)?", t)]
    op_positions = [i for i, t in enumerate(out) if t in {"+", "-", "*", "/", "=", "^"}]

    if mode == "swap_terms" and len(term_positions) >= 2:
        i, j = term_positions[0], term_positions[-1]
        out[i], out[j] = out[j], out[i]

    elif mode == "delete_term" and term_positions:
        out.pop(term_positions[len(term_positions) // 2])

    elif mode == "duplicate_term" and term_positions:
        i = term_positions[len(term_positions) // 2]
        out.insert(i, out[i])

    elif mode == "nudge_number" and term_positions:
        i = term_positions[len(term_positions) // 2]
        try:
            if "." in out[i]:
                out[i] = str(float(out[i]) + 1.0)
            else:
                out[i] = str(int(out[i]) + 1)
        except ValueError:
            pass

    elif mode == "flip_operator" and op_positions:
        i = op_positions[len(op_positions) // 2]
        flips = {"+": "-", "-": "+", "*": "/", "/": "*", "=": "=", "^": "^"}
        out[i] = flips.get(out[i], out[i])

    return out


def mutate_line(line, mode):
    if not is_math_line(line):
        return None
    tokens = tokenize_line(line)
    mutated = mutate_tokens(tokens, mode)
    if mutated == tokens:
        return None
    return detokenize(mutated)


def run_target(script_path, corpus_path, prompt, extra_args, timeout):
    script_path = str(Path(script_path).resolve())
    corpus_path = str(Path(corpus_path).resolve())
    cmd = [sys.executable, script_path, "singlekb.txt", "--prompt", prompt] + extra_args
    return subprocess.run(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=timeout,
    )


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("script_path", help="path to markov_gen.py")
    ap.add_argument("corpus_path", help="training corpus file")
    ap.add_argument("--prompt", default="once upon a")
    ap.add_argument("--timeout", type=float, default=10.0)
    ap.add_argument("--extra-arg", action="append", default=[])
    ap.add_argument("--modes", default="swap_terms,delete_term,duplicate_term,nudge_number,flip_operator")
    ap.add_argument("--limit", type=int, default=0, help="stop after this many mutated lines; 0 = all")
    args = ap.parse_args()

    lines = read_lines(args.corpus_path)
    modes = [m.strip() for m in args.modes.split(",") if m.strip()]

    total = 0
    for line_idx, line in enumerate(lines):
        if not is_math_line(line):
            continue

        for mode in modes:
            mutated = mutate_line(line, mode)
            if not mutated:
                continue

            with tempfile.TemporaryDirectory() as td:
                tmpdir = Path(td)
                mutated_corpus = tmpdir / "mutated.txt"
                write_lines(mutated_corpus, [mutated])

                try:
                    result = run_target(
                        args.script_path,
                        str(mutated_corpus),
                        args.prompt,
                        args.extra_arg,
                        args.timeout,
                    )
                    status = "ok" if result.returncode == 0 else f"rc={result.returncode}"
                except subprocess.TimeoutExpired:
                    status = "timeout"
                    result = None

                print(f"\n[line {line_idx} mode={mode} status={status}]")
                print("original:", line)
                print("mutated :", mutated)

                if result is not None:
                    out = result.stdout.strip()
                    err = result.stderr.strip()
                    if out:
                        print("stdout:")
                        print(out)
                    if err:
                        print("stderr:")
                        print(err)

            total += 1
            if args.limit and total >= args.limit:
                return


if __name__ == "__main__":
    main()

